window.__D("text/pirush-hamilot/c004",{"p":[[2400650484,"וחיות בבחי' יש מוגבל ונפרד ושניהם אמת שמתחילה נמשך מיש האמיתי לאין ואח\"כ מאין זה נמשך מהעלם לגילוי ליש נפרד מוגבל וכדוגמת משלים הנ\"ל. (כמעיינות תהום לנהרות ומאור חיי רוחני' הנפש בגוף וכח צמיחה רוחני בעשב ומכח התנועה בפועל לתנועה גשמי וכזיו השמש בהארתה בגילוי שבארץ כנ\"ל). ולפי\"ז הרי מובן עכ\"פ בכללות ב' מיני אופנים הנ\"ל מיש לאין ומאין ליש שיש האמיתי הוא בבחי' העצמות ממש טרם שנק' משפיע רק גילוי אורו בלבד ה\"ז מלמעלה למטה שהוא בחי' ד\"ע הנ\"ל ובחי' יש נפרד שמקבל מאין ההעלם שלו הוא בחי' ד\"ת שממטה למעלה כי לגבי המקבל נראה לו בעצמו בבחי' יש והאור השופע לו הוא אצלו בבחי' אין ולגבי העצמיות ממש הדעה להיפך דהוא עצמו הוא היש האמיתי ומה שנשפע ממנו כלא וכאין וב' דעות הללו הפכים הם מן הקצה אל הקצה והוא מד\"ע דיש האמיתי לד\"ת דיש נפרד כו' אבל בחי' אמצעית שביניהם שהוא הארת האין דכלא חשי' לגבי' העצמו' ונק' משפיע לגבי המקבל כלול בו ב' הדעות שמלמעלה למטה ומלמטה למעלה (כי הוא רק בחי' גילוי לגבי העצמות שזהו בבחי' ד\"ע ובחי' העלם ומקיף בחי' מקור מוסתר בבחי' היש דהמקבל כמו חיות הנפש שמוסתר לגמרי בגוף והגוף הוא היש והחיות כאלו אינו כו' ובבחי' עצם הנפש להיפך יש בו כו' וכמו גילוי כח הצמיחה שמוסתר בגשם העשב כנ\"ל. וכך כל ממוצע שמחבר רוחני בגשם כו') ומוכרח שיש בו יתרון מעלה משניהם כנ\"ל. והוא להיות שגם מה שנק' יש האמיתי הוא הנק' חומר ההיולי או חומר הפשוט וכמו שיש צורה לחומר סתם כך יש צורה לחומר הפשוט והיולי ונק' צורה היולית הפשוטה וכך ממילא מובן שלבחי' יש האמיתי שהוא כמו חומר ההיולי יש לו בחי' צורה היולית ופשוט והוא הנק' אין האמיתי שבחי' יש האמיתי נק' חומר שלו המגלה עצם הכח והצורה ההיולית כנ\"ל. ויובן דבר זה גם בדבר פרט כמו עצם כח המשכיל ההיולי להשכיל כל שכל כידוע. והרי יש בו בחי' חומר וצורה היולי' בחי' החומר ההיולי הוא מה שנמצא כח גילוי זה להשכיל תמיד שכלי מוחו מוכנים להשכיל כל חכמה כמו וה' נתן חכ' לשלמה הרי נתן לו לזה חומר פשוט והיולי בכלי המוח והוא הנק' כח וחומר המשכיל ההיולי להשכיל בו עד אין שיעור כו' ובהכרח שיש לכח חומר היולי גדול הזה בחי' צורה ואור רוחני היולי והוא בחי' כח המקור היולי הרוחני שמשם נובע גילוי כח זה בבחי' יש בחומר היולי להשכיל בכל שכל תמיד ונמצא שכח זה הבא בבחי' חומר פשוט והיולי להשכיל בגילוי הוא הנק' יש האמיתי בדרך פרט בבחי' החכ' ובחי' הצורה היולי שלו שהוא המקור שנותן כח החכ' בכלי המשכיל ההיולי החומר הזה"],[2400650485,"נק' אין הרוחני האמיתי שלו כו' כמו שבא הצורה אל החומר בבחי' הגבול והשיעור ונק' אין ויש מוגבל כך ודאי יש בצורה וחומר שלמע' מן השיעור ונק' אין ויש האמיתי. וזהו בדרך כלל ודרך פרט מבחי' מקור הרצון והתענוג עד מקור לסוף מעשה וכו' וד\"ל. כך יובן בבחי' האין דיש האמיתי הנ\"ל שנק' מקור לגבי המקבלים מאחר שסובל ב' הדעות דיש האמיתי ויש הנפרד היינו מצד שרשו באין האמיתי שהוא בחי' הצורה היולי של החומר הפשוט הנק' יש האמיתי כנ\"ל. וכמו במשלים הנ\"ל דגילוי אור וכח וחיות ג' מיני שפע הנ\"ל הרי יש בגילוי אור וכח וחיות זה מאין האמיתי שהוא הצורה היולי' מקור לגבי ישות העצמות דנפש טרם שמחי' כו' וכן יש צורה ואין האמיתי לגבי ישות ועצמות דכח הצומח או כח התנועה העצמי' טרם שמניע כו' ומאחר שגילוי אור זה מקשר רוחני' העצמיות עם הגשם ממש מוכרח שיש לו שורש למעלה משניהם ע\"כ סובל ב' הפכים הללו כא' דמאין ליש ומיש לאין שווין לפניו ממש כו' כמו שלגבי מקור עצם ישות חומר כח המשכיל ההיולי שוה גילוי שכל הבא בבחי' יש מוגבל עם עצם ישות כח החומר ההיולי להשכיל כל שכל בגילוי שנק' יש האמיתי והרי הארה זו נמצאת בחי' ממוצע המביא מאין האמיתי וחומר המשכיל הזה כו' כנ\"ל וד\"ל:\n(קלט) <b>והנמשל</b> מכל הנ\"ל יובן בענין כי אל דעות ה' כו' דמיש האמיתי לאין בכלל היינו ענין ובחי' טה\"ע שנק' אוא\"ס בחי' אור וזיו בלבד רק שהוא בחי' א\"ס ממש (ולכך נק' א\"ס ולא אין לו תחלה כו' כי הוא בא בבחי' גילוי ממש מיש האמיתי שייך לומר בו א\"ס להתפשטותו). וזהו הי' הוא ושמו בלבד [כידוע] ובחי' טה\"ע נק' אין ונק' סדכ\"ס לגבי הארת הקו שאחר הצמצום ונק' מקור הראשון לגילוי הקו כידוע שהוא בחי' יש מוגבל בקו המדה לכל האורות מקו\"פ כו' ובהכרח שיש בו מב' דעות הללו כנ\"ל באריכות והיינו להיות שרש הטה\"ע הזה בבחי' אין האמיתי שהוא בחי' שרש ומקור הראשון שממנו בא לגילוי אוא\"ס זה הנק' בשם טה\"ע (שאינו רק כגילוי אור עצם הנפש ההיולי' שבא בגילוי חיות בגוף כו') בהיותו ממוצע מיש האמיתי ליש דקו\"ח כמובן ממשלים הנ\"ל וד\"ל. ובכ\"ז יובן מ\"ש בזוה\"ק בפי' כי הוי' הוא האלקים דהוא זה הוא הממוצע בין הוי' לאלקי' והוא המחברם יחד כי אלקים בחי' יש והתפשטות כח הפועל בנפעל והוי' הוא יש עצם מדותיו כו' וגילוי יש עצם זה ליש דאלקים ה\"ז כמו גילוי אור השמש מעצם השמש וכמ\"ש כי שמש ומגן הוי' אלקי' והיינו בחי' אין דיש העצמי שנעשה יש דשם אלקים בבחי' הגבול וזהו הוא לשון נסתר דמחבר הוי' לאלקים (וכמשי\"ת"],[2400650486,"בסמוך בענין היש וכן אנכי אנכי הוא מוחה כו' וכן כי אני אני הוא וב\"פ אנכי ה\"ז אין ויש האמיתי). והנה מובן עכ\"פ מענין אל דעות ה' הנ\"ל שבדרך כלל הרי לגבי המקבל הוא להיפוך מאצל המשפיע דאצל המשפיע כל מה שנמשך ממנו נק' אין וכלא כו' ולגבי המקבל להיפוך הוא דמה שלמעלה ממנו נק' אין והעלם ולמטה הוא בחי' יש כנ\"ל. אך הנה אעפ\"כ יוכל לבוא הארת ד\"ע דמשפיע גם למקבלים רק שבא בבחי' מקיף עליהם בהעלם ולא בגילוי והוא ענין ההודאה שיוכלו המקבלים שהן יש מוגבל להודות בהודאה עכ\"פ כפי הדעה (דמשפיע שלא יוכלו להשיג זה בהשגה ממש שהרי זהו היפך השגתו) דמשפיע מלמעלה למטה שהוא באמת בחי' היש מקור הכל וכולא קמי' כלא וכאין ממש היפך דעת המקבל כו' ואעפ\"י שלא יוכלו להשיג זה בהשגה ממש שה\"ז הוא היפוך השגתם ממש מ\"מ בבחי' הודאה עכ\"פ יודה באמת ע\"ז כידוע בענין מודים אנחנו לך כו' כאדם המודה לחבירו שאתו האמת היפך דעתו כך אנחנו מודים שהוא היש ולמטה האין כו' היפך השגתינו המוגבלת כו'. אך לכאורה איך אפשר להיות הודאה זו ואם מפני שמאיר עליהם בבחי' מקיף ה\"ז בהעלם ואיך יבוא הדבר באמיתי' הענין בהודאה גמורה כו'. אמנם הענין הוא באמת עיקר ענין ההודאה הוא דווקא בדבר שהוא למעלה מן ההשגה לגמרי דהודאה שמודה מצד השגה שמשיג שהאמת כדעת זולתו אין זו עיקר ההודאה (כי זהו רק הוד דאימא כמשי\"ת) רק כשנפלא הדבר מן השגה לגמרי אעפ\"כ הוא מודה בהודאה שכן הוא האמת בלי ספק זהו עיקר ההודאה ולכאורה זהו כדבר פלא מאין נמצא בו כח הודאה זו מאחר שנפלא ונעלם הדבר מהשגתו לגמרי איך יודה באמת שכן הוא כו'. והנה יובן ענין זה מענין הודאה על הנס דוקא. דהנה לכאורה י\"ל בענין הודאה על הנס בענין ד' צריכים להודות יורדי הים כו' מפני הנס שאירע להם מה טעם לענין הודאה זו על הנס ואם מפני חסד הוי' שניצולו ישבחו ויברכו להוי' על הטוב הזה ולמה צריכים להודות בהודאה דווקא. אך הנה עיקר ענין הנס ידוע שהוא היפך כח דרכי הטבע והיפך זה בטבע בא מלמעלה מן הטבע דווקא והוא ענין הארת עלמא דאתכסיי' בעלמא דאתגליי' בכלל כו' וכידוע דאלקים בגימ' הטבע לפי ששם אלקים זה הוא שרש לכל הברואים שנבראו מאין ליש כידוע דהאלקים הוא לשון כח כמו יש לאל ידי כו' והוא בחי' כח האלקי ממש המלובש בתוך כל הנבראים ונק' כח הפועל בנפעל וזהו שאלקי' בגימ' הטבע להיות שרש טבעי' של כל הנמצאים שנמצאו משם זה והוא המקור והשרש לכל טבע הברואים דהיינו שהוא המנהיג כח הטבע המוטבע"],[2400650487,"בכל הברואים שבעולם גם לשנותם מהיפך להיפך כמו מי שאמר לשמן וידליק כו' ולפי שצדיק מושל ביראת אלקי' ק\"ך צירופי' אלקים להפוך מצירוף לצירוף כמ\"ש במ\"א לפי שכל פרטי הטבעי' מכח זה השם נמצאים. אך א\"כ לכאורה אינו מובן ענין הנס שהוא היפך הטבע כידוע שזהו למעלה משם אלקים דווקא והוא משם הוי' שלמע' משם אלקים ונק' עלמא דאתכסייא שלמעלה מהטבע כנ\"ל כו'. ובאמת הלא היפך הטבע הוא משם אלקים עצמו אחר שממנו מקור מוצא מאין ליש כו'. אמנם הנה אנו רואים באמת שגם הטבע עצמו אינו רק בחי' מקבל מלמעלה מן הטבע דכל סדר הנהגת הטבע גי' אלקים בכל פרטיו מתנהג הכל עפ\"י שם הוי' המאיר בשם אלקים דווקא כמ\"ש כי הוי' הוא אלקים כולא חד כו' רק ששם הוי' מוסתר ונעלם בשם אלקים והוא מה שהאור האלקי שלמעלה מן הטבע מוסתר הכל בדרכי הטבע ואין גילוי שם הוי' בכל פרט מדרכי הטבע רק גילוי שם אלקים המסתיר עליו בכל פועל הנהגה פרטי' בדרכי הטבע אך בפועל מעשה הנס אז בא אור דשם הוי' המוסתר לידי גילוי ההעלם בלבד לכך נק' נס מל' הרמת נס שהוא דבר גבוה מאוד מוגבה מן הכל והוא ענין הארת אור שלמעלה מן הטבע כשבא לגילוי הטבע שנק' דבר נפלא שהכל תמהים עליו מאד ה\"ז כניצוצי השמש שבוקעים במסך עד שאור זה המבהיק בחורים ובסדקים במסך אור חדש ונפלא שאין העין יכילנו כך אורות חסדים העליוני' דשם הוי' שלמעלה מן הטבע כשמאירין ובוקעין בחושך ההסתר דהטבע דשם אלקים ה\"ז כמו בחי' בקיעת אור מלמעלה ולכך נק' נס לשון הרמה לפי שהטבע הורמה ונתעלה באור זה הנפלא שלמעלה מן הטבע כמו בהגלות נגלות אורו למטה הוא בא ונגלה דהיינו בטבע עצמו כמו מקום שנעשה בו הנס כקריעת י\"ס ולא שהאור הזה מאיר במקומו למעלה אלא למטה בטבע עצמו כמו ים ויבשה שהוטבעו בדרכי הטבע ונהפך ים ליבשה ע\"י הארה דשם הוי' שלמעלה מן הטבע הרי מקום זה גילוי לשם הוי' ממש וממילא נתעלה בחי' טבע זו שבמקום זה דשם אלקים בשם הוי' לכך נק' נס וצריך לברך בשם הוי' דווקא כשרואה מקום זה שנעשה בו נס (וכן מקום ארון אינו מן המדה הרי האור הרוחני זה שלמעלה מגדר ושטח מקום בא בגילוי ממש בגדר ושטח מקום זה שהארון בו כו' וכמ\"ש במ\"א. ולכאו' גם בתחילה הי' אור שם הוי' באלקים והוא מה שהטבע עצמו מתנהגת הכל ע\"פ אור הוי' דווקא רק שהנהגת שם הוי' המנהיג בדרכי הטבע הוא מוסתר ובנס בא לידי גילוי מן ההעלם בלבד וא\"כ מה יש לברך ע\"ז לכאורה אלא צ\"ל שיש הפרש גדול בזה והוא בהיות שהנהגה זו דשם הוי'"],[2400650488,"ע\"י שם אלקי' הרי גילוי הפועל הוא ע\"י שם אלקי' דווקא שלא ישונה מן הטבע כנס דאחשורו' שהי' מלובש בטבע ממש וכנ\"ל וזהו שמסתיר על אור שם הוי' כאדם שעושה ע\"י שליח או מלביש א\"ע ומשנה טעמו שלא יתגלה עצם מהותו כלל וכל הנהגותיו ע\"י העלמות ולבושים שונים משא\"כ גילוי שם הוי' עצמו הרי מפני הארה זו מתבטל הטבע לגמרי כמו הפך ים כו' ונסתר הלבוש דטבע לגמרי ונגלה כבוד הוי' כמו שהוא בעצם למעלה מלבוש והסתר דטבע לגמרי לכך צריך לברך בשם הוי' כו' לפי שהאלקים נכלל ובטל בהוי' ואין כאן רק שם הוי' לבד רק מפני שגילוי ההוי' הוא בדבר שהוא בא בבחי' הטבע דשם אלקים שהוא כמו מקום שנעשה בו הנס כו' שזהו כמשל בקיעת אור הבהיר הבוקע בנקבי המסך כו' לכך הוא נק' נס נפלא ומחודש מאוד ואין חידוש נפלא זה רק לגבי התחתונים המוטבעים בדרכי הטבע ששרשם מבחי' אלקים בלבד כנ\"ל וד\"ל אבל מה שיש היפך הטבע דשם אלקים עצמו הרי הכל באותן צירופי אותיות משם אלקים המסתיר ע\"ש הוי' כמו מי שא' לשמן וידליק כו' ואין כל חדש בזה מאור שם הוי' עצמו כמו שהוא למעלה מאותיות וצירופים דאלקים גימט' הטבע לגמרי (אך הנה הממשלה בצירופים הללו כמו צדיק מושל כו' היינו כמ\"ש והוא ימשול בך שזהו כמו איש שמושל על אשתו שמכריח אותה לעשות כרצונו היפך רצונה אבל עצם הפעולה ע\"י דוקא נעשה רק שהיא עושה ברצון בעלה כך בחי' שם ב\"ן שבאלקים פעולתו אמת כפי פקודת בעלה פועל אמת הוא שם מ\"ה דשם הוי' כמ\"ש והוא ימשול בך כו') משא\"כ גילוי אור משם הוי' עצמו הרי גם עצם הפועל הוא עצמו עושה שלא ע\"י שם אלקים רק שמתלבש פעולתו באותיו' וצירופים דשם אלקי' והוא במקום גשמי שבו נעשה הנס כו' ובזה יובן שיש ב' מיני נסי' א' בהיפוך הטבע בשם אלקי' שאינו חדש מעיקרו והב' נס דהוי' עצמו שצריך להודות ולברך דוקא שהוא אור חדש מעצם שם הוי' שלא נמסר לידי שליח כלל רק בפעולתו בא למטה בעולם הנפרד ולכך העומדים למטה צריכין לברך ולהודות כו' וד\"ל ובכ\"ז יובן שרש ענין ההודאה על הנס שהוא למעלה מן ההשגה לגמרי כי אין השגה מגיע רק בשרש הטבע וגם בהיפוך הצירופים באותיות דשם אלקים לא יכילנו ההשגה רק מ\"מ נוכל להודות ע\"פ השגה שלו בכח שם אלקים המנהיג הטבע אבל בלמעלה מן הטבע לגמרי אין שם השגה כלל וכלל וא\"כ מה שהוא מודה בהודאה שכך הוא האמת אין זו מצד השגתו כלל וכלל רק מפני שבמקום זה נגלה עליו אור הוי' עצמו באופן שאין בו השגה כלל והרי עכ\"פ נראה פעולתו בהיפוך מן הטבע בתוך הטבע עצמה ע\"כ בהכרח יודה בהודאה שכן הוא ואמנם הודאה זו"],[2400650489,"היא בחי' ביטול למעלה מן הטעם והיינו שבא עלי' גילוי אור ובחי' מקיף דשם הוי' שהוא בבחי' מקיף בבחי' עלמא דאתכסיי' כנ\"ל והנס זה בא לידי גילוי כמו שהוא וכל בחי' מקיף שבא לגילוי על זה שייך ענין ההודאה הזה שבבחי' ביטול שלמעלה מן הטעם והשגה דוקא וזהו מטעם שצריכין להודות לשם הוי' דוקא בנס שלא ע\"י הטבע דוקא כמו יורדי הים כו' שנצולו מרוח סערה ע\"י שיקם סערה לדממה שהטבע דרוח סערה נתבטל ועלה למעלה מן הטבע בשם הוי' שנגלה שם כו' וכה\"ג ולכך נק' נס כנ\"ל וכל ד' שצריכין להודות הכל באופן זה דוקא וד\"ל:\n(קמ) <b>וזהו</b> דעו כי ה' הוא האלקים וכן כתיב וידעת היום והשבות כו' כי הוי' כו' ולכאורה אינו מובן איך שייך בזה ענין ידיעה והשגה מאחר שכל עיקר ענין הוי' ואלקים הוא כמו שמש ומגן שזהו התלבשות שם הוי' שלמעלה מן הטבע המוסתר בתוך הטבע דשם אלקים הרי הוא למעלה מן הידיעה והשגה שהרי שם הוי' מוסתר ונעלם ולא נגלה רק בחי' הטבע ואיך ידע וישיג בהוי' שבאלקים ולא עוד אלא שידע דוקא שהוי' הוא אלקים ומכ\"ש בשם הוי' עצמו שלמעלה מן הטבע לגמרי שנק' עלמא דאתכסייא שהוא ודאי למעלה מן ההשגה והידיעה ואם מדבר בענין הנס שאז נגלה שם הוי' עצמו הרי זה שם הוי' עצמו לבדו כי אלהים נכלל בהוי' כנ\"ל ואיך אמר שידעו כי הוי' הוא אלקים דכולא חד ועוד דבזה לא שייך ידיעה רק הודאה שלמעלה מן ההשגה לגמרי כו' ומ\"ש דעו וידעתם משמע דיוכל לבא בידיעה והשגה דוקא אך הנה כ\"ז יובן עפ\"י כל הנ\"ל בפי' כי אל דעות הוי' כו' ב' דעות דמשפיע ומקבל והוא מיש אמיתי לאין ומאין ליש כו' ומבואר למעלה דהוא היינו המחבר הוי' ואלקים כו' ולהיות ידוע דאלקים הוא שרש בחי' יש מאין הבאה בבחי' הגבול ונק' כח הפועל בנפעל שהוא שרש הטבע כו' והוי' הוא בחי' יש האמיתי שממנו נמשך אור וזיו הנק' אין כאור השמש כו' והשפע' משם הוי' נק' מיש לאין דכלא חשיב כו' והוא בחי' דעה דמשפיע שמלמעלה למטה והוא ענין הארת אור שם הוי' כמו שהוא למעלה מן הטבע לגמרי אך הנה מה ששם הוי' מוסתר לגמרי בטבע בבחי' אלקים הרי שם אלקים מלביש בבחי' לבוש יש גמור לאור הוי' ונק' זה השפע שבהעלם במקבל מאין ליש כנ\"ל וזהו דעה דמקבל שלמטה בחי' יש כו' כנ\"ל ודעה זו שמלמעלה למטה מיש האמיתי דהוי' לאין הוא למעלה מדעת המקבלים ואינו בא להם רק בבחי' הודאה שלמעלה מן השגה כמו בהודאה שעל הנס וכה\"ג כנ\"ל אבל מ\"ש דעו כי הוי' כו' שיוכלו המקבלים ג\"כ לידע בשם הוי' אין זה"],[2400650490,"בשם הוי' כמו שהוא במקומו אלא כמו שהוא בא ומאיר בשם אלקים אעפ\"י שהוא מוסתר ונעלם שם לגמרי אך בחי' הוא זה הממוצע בין הוי' לאלקים וע\"י יוכלו לידע ולהשיג דהוי' ואלקים כולא חד מפני ששרשו בבחי' אין של היש האמיתי דהוי' כנ\"ל באריכות (שהוא בחי' הכ' כמ\"ש במ\"א בפי' היש הוי' בקרבנו אם אין) ע\"כ בכחו לחבר להיות שם הוי' בא מאין ליש מוגבל והוא מה שנמשך מאין ליש גמור שזהו ממש כמו בבחי' מאין האמיתי ליש האמיתי כו' מטעם הנ\"ל באריכות ואעפ\"י שבשם הוי' עצמו לא נודע להם בהשגה אבל מה שמוסתר ובא בבחי' אין דוקא ביש מוגבל הנה מצד בחי' היש מוגבל עצמו ששרשו באין של היש האמיתי הזה יבואו לבחי' דעת והשגה שהוי' הוא אלקים והוא בחי' דעת דמקבלים מאין ליש ששרשו למעלה מד\"ע דמיש לאין שאינו בא רק בהודאה וד\"ל (וכמ\"ש במ\"א שמטעם זה בחי' היש מוגבל שרשו גבוה מאין של היש להיותו בא מצד בחי' היש האמיתי שמקבל מאין האמיתי) שהוא בחי' צורה היולית מקור לחומר היולי כנ\"ל כי מה שבא לבחי' יש גמור דוקא שרשו בעצמיות ממש שלמעלה גם מאור השפע שמיש לאין דמשפיע ומכ\"ש מבחי' האין של היש האמיתי וזהו כי הוא צוה ונבראו בבחי' יש גמור וכן הוא עשנו ולו אנחנו מפני שהוי' הוא האלקים וזהו בחי' בינה שלמעלה מן החכ' בשרשה כי החכ' נק' אין והבינה נק' יש ולכך ההודאה בחכ' ולא בבינה כמשי\"ת והדעת וההשגה הוא בבינה כמ\"ש דעו כי הוי' הוא האלקים שהוא בבחי' בינה שנק' אלקים עילאה כידוע ונמצא מובן מזה דהניסים המלובשים בדרכי הטבע כנס דאחשורוש וכה\"ג גבוהים בשרשם מנסים שלמעלה מן הטבע שצריכים הודאה לשם הוי' כנ\"ל וכמ\"ש במ\"א בענין שאל לך אות כו' העמק שאלה שהוא עוצם הירידה בדרכי הטבע או הגבה למעלה מן הטבע כו' והשיב לא אשאל ולא אנסה כו' ע\"כ א' לו הנה העלמה הרה כו' שהן אותיות הטבע דאלקים בלתי מקבלים שפע מעלמא דדכורא כלל והן עצמן יהי' היפך הטבע דהיינו ע\"פ אותיות הטבע עצמן יהי' אותו הנס שצ\"ל שלא ע\"פ הטבע כנס דאחשורוש וכה\"ג וזה יותר נעלה בשרשו מנסי' ונפלאו' דגילוי הוי' באלקי' הנ\"ל מטעם הנ\"ל ולפ\"ז מ\"ש אותותינו לא ראינו כמו בזמן הגלות גבוה בשרשו מניסים ונפלאות שהי' בזמן בהמ\"ק וביצי\"מ וכה\"ג ששרשו בבחי' אין דשם הוי' כמ\"ש היש הוי' בקרבנו אם אין כו' ע\"כ דוקא בא ע\"י הטבע שנק' יש גמור כי אינו נק' מסתיר כלל דקמי' כחשכה כאורה כו' מאחר שהוא למעלה מהוי' ואלקי' ומחברם יחד וז\"ש בני גד אל אלקים הוי' אל זה מחבר אלקים והוי' וכנ\"ל בענין כי אל דעות"],[2400650491,"הוי' שסובל ב' הדעות יחד כו' וד\"ל. ועוד י\"ל בענין דעו כי הוי' כו' וידעת כו' בבחי' דעה עליונה שלמעלה מן המשפיע שמלמעלה למטה שהוא מיש לאין שהוא בא בבחי' הודאה דחכ' בניסים ונפלאות בלבד למעלה מן ההשגה לגמרי ולא בא בהשגה כלל אך בענין תושב\"כ ותושבע\"פ שהוא ג\"כ יחוד הוי' ואלקים כידוע וכן ע\"י המצות מעשיו' שהן ג\"כ יחוד הוי' ואלקים יחוד קוב\"ה ושכינתי' כידוע ה\"ז בא בבחי' השגה ודעת ממש וזהו וידעת היום כו' וכן דעו כי הוי' הוא אלקים בבחי' דעת והשגה ממש והענין הוא כמבואר במ\"א בענין ושמי הוי' לא נודעתי להם שאעפ\"י שהאבות הן הן המרכבה לבחי' חג\"ת דז\"א אבל שם הוי' שהוא בחי' פנימי' מוחין דאבא שבז\"א לא נודע לאבות כלל כי אין זה רק בחכ' שבתורה דוקא כידוע שהמדות העליונ' דז\"א דאצי' אין הארתן לעולמות בי\"ע רק מבחי' קטנות שבהם בלבד והוא קטנות המוחין שבמדות שלצורך הנהגת העולמות בלבד כמו מלך במשפט יעמיד כו' שיושב ודן במדותיו ע\"פ שכל המצומצם במדותיו רק לפי אופן תועלת המדינה וכך הקב\"ה יושב ודן את כל העולם כולו וכו' אך בחי' גדלות המוחין אשר במדותיו הוא בחי' עצמות חכמתו שבמדות שבתורה להבדיל בין טמא לטהור כו' דאורייתא מח\"ע העצמי' נפקת ומלובש במדות ג\"כ אבל בבחי' גדלות המוחין כמארז\"ל ג' שעות ראשונות יושב ועוסק בתורה שהוא המשכת גדלות המוחין שבמדות שבתורה ומשם נמשך קצת הארה בעלמא כשיושב ודן כו' וזהו מלך במשפט יעמיד ארץ במשפט שבתו' דוקא והוא ענין במשפט דשם הוי' עצמו שנק' יש האמיתי כמ\"ש והחכ' מאין תמצא ליש מאין האמיתי כו' דאור הוי' זה דח\"ע דתו' כלי לגילוי עצמי' אא\"ס הנק' אין האמיתי כו' ואור השפע נמשך מיש בחי' הוי' דתושב\"כ לתושבע\"פ מל' קרינן לה (ולפעמים תושבע\"פ נק' אלקים עילאה בבחי' בינה וזהו ספר וסיפור שהן בחי' חו\"ב תושב\"כ ותושבע\"פ כידוע או אלקים תתאה בחי' מל' (שתושב\"כ בבחי' ז\"א ותושבע\"פ בבחי' מל'). אבל מה שהחכ' נק' אין ובינה יש וההודאה בבחי' החכ' דוקא ובינה נכללת בחכ' כמשי\"ת בסמוך אין זה רק לגילוי אור שפע חיצוני' חכ' בבינה אבל בחי' פנימי' ח\"ע הרי החכ' מאין תמצא בחי' יש מאין והוא ענין תושב\"כ שהוא פנימי' אבא וגם לגבי תושבע\"פ נמשך בפנימי' דבינה שהוא מיש ליש כנ\"ל ולכך אין זה כשאר יחוד דחו\"ב מאין דהוי' דחכ' מוסתר באלקים דבינה שהוא בחי' יש מוגבל ומסתיר להיות השפע מאין ליש משא\"כ תושבע\"פ אינו בחי' הסתר כלל לתושב\"כ ואינו נק' יש מסתיר כלל מפני שהיחוד הוא בבחי' פנימי' דאו\"א וכמו שהם מקבלים מבחיד הכ' עצמו כידוע בענין הכל תלוי במזל אפי' ס\"ת בהיכל שהוא פנימי' אבא דתושב\"כ בהיכל דאי' בבחי' פנימי' בינה וע\"ז נא' להנחיל אוהבי יש ב\"פ יש גי' תר\"ך אותיו' כת\"ר וב\"פ קנ\"ה"],[2400650492,"גי' יש והוא ענין קנה חכ' קנה בינה כו' וכן אאלפך חכ' אאלפך בינה שהוא יחוד ב' מזלו' ונוצר ונקה התלוים במזל א' כמ\"ש הכל תלוי במזל כו' וכן בתושב\"כ ותושבע\"פ בחי' זו\"נ דתושבע\"פ מל' קרינן לה אלקי' תתאה אינו בבחי' יש מסתיר כלל ע\"ש הוי' דתושב\"כ וכמ\"ש במ\"א בענין תו' צוה לנו משה שהוא תושבע\"פ דשכינה מדברת מתוך גרונו כו' ולכך מי שתורתו אומנתו פטור מן התפלה כו' וזהו דעו כי הוי' הוא האלקים שאין זה כשם הוי' ואלקים לצורך שפע העולמות שהוי' מוסתר באלקים ולא נודע כמ\"ש ושמי הוי' לא נודעתי להם אלא נודע ומושג לכל בעסקם בתושבע\"פ ג\"כ בדבר ה' זו הלכה דוקא כו' וד\"ל:\n(קמא) <b>וזהו</b> מזמור לתודה הריעו לה' כל הארץ ר\"ת הלכה בהיות דקרבן תודה מצד עצמו הרי הוא בבחי' שם הוי' עצמו כמו שהוא במקומו למעלה משם אלקים כענין ההודאה על הנס שבא בגילוי אור הוי' באלקים מלמעלה מן הטבע בהיפך הטבע שלא כמו ששם הוי' מוסתר ונעלם בטבע ולכך צריך להודות על הנס להוי' כנ\"ל באריכות אבל ה\"ז למעלה מן ההשגה לגמרי רק בבחי' ביטול שלמעלה מן הטעם וזהו הריעו לה' כו' כי הריעו זה כמו תרועם כו' ענין ביטול היש לאין ולשון תרועה הרמת קול לפי שבא על דבר נס פלא ונורא מאוד שלמעלה מן השכל כו' וכל הארץ הוא בחי' אלקים בגימט' הטבע שמתבטלת ועולה למעלה בשם הוי' כנ\"ל בענין הנס שהוא ענין לשון הרמה והגבהה למעלה כו' והיינו הריעו לה' דוקא כל הארץ בענין התודה שהוא בחכ' כח מ\"ה בחי' אין שלמעלה מן היש כו' אבל בהלכה בתושבע\"פ הרי זה בא בבחי' דעת והשגה מפני שאינו בבחי' מסתיר כלל לשם הוי' כו' ולכך ר\"ת דהריעו לה' כל הארץ הלכה דהיינו שבחי' הודאה שבעולם הנפרד באה בהלכה בתושבע\"פ בבחי' דעת והשגה כמ\"ש דעו כי הוי' הוא אלקים מטעם הנ\"ל וד\"ל (וכידוע דהלכ\"ה אותיות הכלה ואדרבה עיקר הגילוי בפרט הרצון הוא בתושבע\"פ דוקא וכנ\"ל וכמשל הולד בעיבור ט\"ח שנתגדל ברמ\"ח איברים פו\"ח וזהו חתום תורה בלימודי כו' ולכך הלכות אינן בטלין לעתיד אף למ\"ד מצות בטילין לעתיד דהגם שמצות מעשיות הוא ג\"כ יחוד זו\"נ בפנימי' שנק' יחוד קוב\"ה ושכינתי' אבל מ\"מ המצות מלובשים בענינים גשמים דנוגה ומצוה בא\"ת ב\"ש מ' וצ' במקום י\"ה כידוע בענין ולא יכנף עוד מוריך כו' ולכך המצות בטילות לעתיד שיתגלה שם הוי' עצמו בלא לבוש דמצות כו' אבל בחי' תושבע\"פ שהוא הלכה לא תתבטל גם לעתיד להיותה עיקר גילוי פנימי' הרצון מקור החכ' דתושב\"כ וז\"ש א\"ח עט\"ב כו' וכמ\"ש במ\"א בפ' ומגיד לאדם מה שיחו דקאי בתושבע\"פ שהוא בחי' שיחה דתושב\"כ לבאר ולפרש כו' ונק' פנים מסבירות כו' וכנ\"ל בפי' עדותיך נאמנו כו' והיינו דעו וכן וידעת כו' וד\"ל. ולהבין מ\"ש בסידור"],[2400650493,"בכוונת דמזמור לתודה זה שהוא בבחי' או\"א דיצירה דוקא ולכאורה אינו מובן מ\"ש בחי' או\"א הרי עיקר בחי' ההודאה הוא בבחי' החכ' דוקא שלמעלה מן השגה דבינה כידוע דהחכ' נק' אין והבינה נק' יש והיחוד דחו\"ב ה\"ז בבחי' ההשפעה מאין ליש ונק' תרין רעין כו' דזיווגייהו תדיר כידוע שהוא יחוד תמידי דחו\"ב מאין ליש כמו בראשית ברא אלקים כו' בראשית בחוכמתא ברא אלקים בינה פי' דאבא א' לאימא כו' כמ\"ש בזוהר ואיך אמר בפי' מזמור לתודה או\"א דיצירה שהוא היפוך בחי' הודאה שלמעלה מן ההשגה דוקא כנ\"ל באריכות אך הנה באמת ענין מזמור לתודה זה הוא באותו ענין ומדריגה דמזמור שיר ליום השבת שאו' בשבת רק שבחול הוא בבחי' או\"א דיצירה ובשבת הוא באו\"א דאצי' וכמבואר שם באריכות בענין או\"א דאצי' שבמזמור שיר ליום השבת היינו באופן ההיפוך מיחוד או\"א בחול שאור החכ' נמשך מאין ליש בבינה כמו בענין מע\"ב דאבא א' לאימא כנ\"ל אלא אדרבה היחוד הוא בבחי' ביטול והתכללות דבינה בחכ' (כאותיות מ\"י וי\"ם כמבואר שם וכמ\"ש במ\"א בענין מקרא קודש) והענין הוא בהיות דמה שהחכ' נק' אין ובינה יש היינו כשאור ושפע דחכ' מבחי' חיצוני' שבה שנק' הארה בעלמא דכאין וכלא חשיב לגבי העצם כנ\"ל בענין השפע מאין ליש כו' ואז נק' החכ' בחי' אין לגבי יש שהוא השגה דבינה כלומר בבחי' ההעלם ומקיף למעלה מן ההשגה ותפיסא דבינה ונקרא כח מ\"ה כלומר מה פשפשת שנעלם מן השגה עדיין כו' אבל במהות ועצם החכ' כמו שהוא טרם שמשפיע אור בבינה אדרבה הוא בבחי' יש בעצם ועד\"מ הידוע מעצם כח השכל באדם שבכוחו להשכיל כל שכל בגילוי אור התחכמות כו' ונק' מוח החכ' חכ' מוחא דעצם המוח דאבא בפנימי' ועצמות שבו כו' והנה ידוע דבשבת החכ' הוא בבחי' פנימי' ועצמות שבה שנק' קדש מלה בגרמי' וממילא בחי' יחוד דחו\"ב היינו שבינה שנק' יש דהשגה נכללת במהות ועצם החכ' שנק' קודש ואינה אז בבחי' התפשטות השגה כלל (דהיינו בבחי' פנימי' בינה שנק' עצם כח המשיג שנק' מוח הבינה עצמו ע\"כ מיחוד זה דחו\"ב פנימי' ועצמיות בשבת נמשך תולדות הנשמות דזו\"נ כו') וזהו ענין מזמור שיר ליום השבת שהוא ביחוד פנימי' דחו\"ב דאצי' שבינה נכללת בעצם פנימי' החכ' (ולכך טוב להודות לה' כו' והיינו דגם יום השבת שהוא מוח אבא עצמו עולה למעלה כמ\"ש שם) ועד\"ז הוא ענין מזמור לתודה בחול רק שהוא בבחי' או\"א דיצירה והוא כמו ענין ההודאה על הנס שזהו בחי' גילוי אור הוי' דחכ' כמו שהוא ובחי' היש דשם אלקים בטל ונכלל בו כנ\"ל כי בחול יורדין או\"א דאצי' בבריאה שהוא המח' דמדות עליונות וממח' לדיבור שהוא עלמא דאתגלי' עד בחי' צירופי אותיות הטבע גימ' אלקים כידוע ואז בחי' החכ'"],[2400650494,"דעולם היצירה שנק' אבא דיצירה מלובש ומוסתר בבינה דיצי' כי שמש ומגן ה\"א כו' רק בנס וכן בקרבן תודה אז היחוד דחו\"ב דיצירה באופן היחוד פנימי' ועצמיות דחו\"ב דאצי' בשבת הנ\"ל שהוא בפנימי' חכ' ויש דבינה נכלל בו (וכנ\"ל בענין מזמור שיר ליום כו') ולזאת לא יוכלו הנבראים בעולם הנפרד שמקבלים מאותיות הדבור דיצירה להשיג במהות ועצמיות דבחי' אור זה שהוא עצמי' חכ' דיצי' רק בא להם בבחי' הודאה וביטול שלמעלה מן הטעם והשגה כהודאה על הנס כנ\"ל (והיינו שיודו בהודאה בלבד כדעה עליונה כיש האמיתי דעצמי' החכמה כו' ולא כדעה דמקבלים שהוא מאין ליש שלמטה היש כו' שזהו דוקא בבחי' יחוד חיצוני דחו\"ב שהחכמה שנקרא אין מוסתר ביש דבינה לגמרי) וע\"כ כל הודאה הוא בבחי' החכמה דוקא ולא בבינה שהוא בהשגה כו' כנ\"ל וזהו שמזמור לתודה הוא בבחי' או\"א דיצירה שבינה נכלל בחכ' כמו בשבת רק שהוא בחו\"ב דיצירה שבחול הרי בא בחי' גדלות המוחין דאו\"א דאצי' בירידה למטה בוי\"ו יומין דחול בהתלבשות בעולמות כמו בענין הנסים או קרבן תודה שמ\"מ גם הנס מלובש באותיות הטבע כמו מקום שנעשה בו הנס כו' משא\"כ בשבת שנקרא קדש מלה בגרמי' כו' ואמנם הנה בענין יחוד הוי' ואלקים דתושב\"כ ותושבע\"פ יותר גבוה גם מיחוד פנימית דאו\"א בשבת או בקרבן תודה דחול דהנה מבואר למעלה בענין הכל תלוי במזל כו' דח\"ע שבתושב\"כ מאין תמצא מאין האמיתי כו' ממזל ונוצר וגם תושבע\"פ בבחי' מזל ונקה ויחוד ב' מזלות היינו ב\"פ י\"ש גי' תר\"ך כו' הענין הוא דהשפעה זו היא השפעת כל עצמותו ממש שנקרא יש האמיתי כמ\"ש במ\"א ולא נשאר כ\"א גוויתו כו' דכל אשר לאיש בתושב\"כ הכל נתן בתושבע\"פ ולא נשאר כ\"א האותיות שנקרא גופא בלא נקודות כו' וכמו ויתפשט יהונתן ממעילו עד חגורו משום דאהבת נפשו אהבו כו' דהמשפיע נותן כל עצמותו להמקבל וז\"ש אתם אפי' שוגגים כו' שיש כח בתושבע\"פ יותר מתושב\"כ ואין משגיחין בב\"ק כו'. וזהו מיש העצמי' דמשפיע ליש העצמי דמקבל משא\"כ ביחוד פנימי' ועצמיות דחו\"ב דאצי' בשבת להוליד נשמות אעפ\"י שהוא מן העצמות ג\"כ כמו כל יחוד זו\"נ שמולידין מבחי' עצמותן לכח המוליד כו' מ\"מ אין זה כל העצמו' רק חלק מעצמותו ובדומה לו ממש והיינו ס\"ר נש\"י דמתקשראן בס\"ר אותיו' התו' דתושב\"כ (וכן ע\"י המצות נק' ישראל קדושים ואורייתא קדישא אבל אין קדוש כה' קדושתי למעלה כו') ונמצא ג' מדריגות יש כאן א' יחוד חיצוני דאו\"א לצורך העולמות כמו במע\"ב בראשית ברא אלקי' כו' ששם הוי' מוסתר באלקים לגמרי. והב' יחוד פנימי דאו\"א להוליד נשמות כמ\"ש כי אתה אבינו כמו בשבת וכמו בבחי' הודאה על הנס וקרבן תודה שנאמר הריעו לה' כל הארץ כו' כנ\"ל והג' יחוד"],[2400650495,"כל העצמיות כמו בתושב\"כ ותושבע\"פ כו' וזהו כמו ענין הנ\"ל בנסים שמלובשים בדרך הטבע דוקא כמו נס דאחשורוש כו' שאין היש דטבע גימט' אלקים מסתיר כלל כי הוא בא מיש האמיתי ליש ולא מאין ליש כו' וכמ\"ש למע' בענין הנה העלמה הרה כו' שהן אותיות דאלקים לעצמן שאינם מקבלים מעלמא דדכורא שנקרא עלמות בלא יחוד משפיע ומקבל כו' כך הלכות דתושבע\"פ נקרא עלמות וכמ\"ש במ\"א בענין ועלמות אין מספר ששרשן ביש האמיתי כמו שמקבל מאין האמיתי וכמ\"ש והחכמה מאין כו' כנ\"ל וזהו ר\"ת דהריעו כו' הלכה דוקא שנקרא עלמה כמו הלכות ודינים שאין להם ראי' מן המקרא אלא הן מתושבע\"פ עצמן ונקרא הללמ\"מ כו' והוא למעלה גם מיחוד עצמי ממש שתושב\"כ משפיע לתושבע\"פ מאחר שאינו מקבל כלל מתושב\"כ אלא כמו לע\"ל שיהי' שווין בקומתן כו' ולמעלה מזה דמל' יתעלה למעלה בפנימית הכ' כמ\"ש א\"ח עט\"ב וכענין דוד הקים על עולה של תורה וכמ\"ש במ\"א בענין דוד מלך ישראל חי וקיים:"],[2400650496,"<h3>הריעו לה' כל הארץ</h3>\n(קמב) <b>הריעו</b> לה' כל הארץ. הנה י\"ל מה שייך הענין דהריעו לה' כו' ר\"ת הלכה לענין מזמור לתודה. והנה תחלה י\"ל בתוס' ביאור זה הפסוק דהריעו לה' כל הארץ כל ריבוי' כו' ואיך יתפרש על ענין ההלכה דוקא בהיות ידוע בשרש ענין התור' שהוא רק לברר בירורי' דעה\"ד טו\"ר משום דבחכ' דוקא אתברירו רפ\"ח ניצוצין שנפלו בשבירת הכלים כו' וכמ\"ש להבדיל בין טמא לטהור כו' (וכאשר יושלם הבירור דעה\"ד טו\"ר שלא יהי' פסול וטמא כמו ואת רוח הטומאה אעביר כו' לא יהי' נצרך להלכה לפי\"ד הר\"מ. אך מבואר במ\"א ביאור המאמר דר\"מ זה דאין הכוונה שיבוטל ההלכות כו' וכדעת מ\"ד דהלכות אינן בטלות לע\"ל כו' ומטעם הנ\"ל) והנה כתיב פיה פתחה בחכ' ותורת חסד כו' וכי יש תור' חסד ותורה שאינה של חסד אלא הענין הוא דמה דבחכ' שבתורה אתברירו יש בזה בחי' חסד ובחי' דין (ולכך אמרו המקובלים הראשונים שהחכ' הוא בחי' דין כו' וכמ\"ש במ\"א) ובחי' החסד שבחכ' נק' תורת חסד דוקא וביאור הדברים הנה תחלה י\"ל בגוף ענין הבירור דעה\"ד טו\"ר בהיות ידוע עד\"מ מתערובות נקי ופסולת הנגלה ונראה לעין מיד לא נק' בירור שצריך לזה חכ' מאחר שניכר הפסולת והסיג מובדל בפני עצמו ואין צריך רק לזרוק אותו (ונק' בורר פסולת מתוך אוכל אבל א\"צ חכ' ושכל כלל לזה ומ\"מ בשבת בורר אסור דמלאכה הוא ממלאכת החול) וכך יובן במ\"ש להבדיל בין טמא לטהור כו' שאין הבדלה זו בין טמא ממש לטהור ממש נק' בירור שבחכ' כלל כמו בין בהמה טמאה כחזיר לטהורה ממש וכה\"ג בין דם נדה ממש לדם טוהר כירוק וכה\"ג וכן בין כשר לפסול ואסור ומותר"],[2400650497,"וחייב וזכאי שמוחלט דינם בתור' שהרי א\"א להפוך ולמצוא כלל איזה משמעות דרש לטהר את הטמא ממש או להתיר את האסור ממש וכנ\"ל ומה שייכות לחכ' כאן בהבדלה זו הנבדל מכבר ונודע לכל אך בדינים והלכות שבהלכות טומאה וטהרה ואיסור והיתר כו' שאינן מפורשין בתו' לטמא ואיסור גמור ויש בו משמעות דורשין לטמא או לטהר בזה שייך עיקר ענין הבירור שבחכ' דוקא והיינו עד\"מ תערובות סיג ופסולת המעורבים בתכלית הדקות בלתי נגלה לעין כו' ויכול להיות שידמה האדם הכל לטוב וצריך עיון רב בהשגחה טובה בעין לבררו ולהוציאו כמו ע\"י הריקוד בנפה עד שמבדיל גם הפסולת היותר דק ובזה יש ב' אופנים הא' הבירור לתכלית הבדלת הפסולת גם הדק שבדקות עד שלא ישאר רק היותר נקי והשאר הכל יוזרק חוץ או להיפוך שיבררו לפסולת הראשון ויוציאו ממנו המובחר והנשאר יבוררו עוד עד כמה פעמים ירקד בנפה עד שלא ישאר רק הפסולת היותר גס שא\"א להוציא ממנו כלום והוא בלבד יוזרק חוץ והשאר הכל יעלה לטוב וזהו היפך בירור הראשון שמבררים הנקי וזורקין הכל עד שלא ישאר רק היותר נקי שאין בו תערובות אפי' בתכלית הדקות והרי ענין השגחת העין בבירורי' האלה אין הפרש כלל בין השגחה הטובה לברר בתכלית את הנקי ובין השגחת העין לברר לתכלית את כל הפסולת למצוא בו כל מה שיכול לעלות ממנו בחלק הטוב כי כמו שימצא תכלית דקות הסיג גם בנקי מאד עד שבטוב ההשגחה דוקא יוסר ומובדל גם הוא כך ימצא בסיג הגס יותר ג\"כ מן הנקי וטוב רק שהוא בתכלית הדקות והעלם בלתי ניכר (ואמנם הטוב הזה שבהעלם הוא בהגשמה וגסות היפך הרע הנמצא בטוב שהוא דק באמת וראי' מרע שבצדיק וטוב שברשע כמשי\"ת) אך הרי ההפרש הגדול הזה שמן הקצה אל הקצה עד שהמה מתחלפין מטוב לרע ומרע לטוב דלפי השגחה זו לברר הנקי גם תכלית הטוב לרע יחשב ולפי השגחה הפכי' לברר הפסולת גם הרע ביותר לטוב יחשב זה אינו רק מצד גודל ההיפוך שבין בחי' החסד שבחכ' לבחי' דין שבחכ' והוא בהשגחת העין לתכלית העיון בדין וריבוי הדקדוק הרי ימצא רע גם ביותר טוב ובהשגחת העיון להיפוך למצוא טוב ברע שהוא בבחינת החסד הרי יורד למטה מטה גם למצוא טוב ברע יותר וכמו שאנו רואים שימצא רע בדקות גדול גם בצדיקים ונק' צדיק ורע לו כו' וכן להיפוך ימצא טוב ברשעים ונק' רשע וטוב לו ולא נבדלו לגמרי רק רשע ורע לו וצדיק וטוב לו שזה כולו טוב וזה כולו רע ולא ימצא בכ\"א בהיפוכו כלל כנקי גמור ופסולת גמור וז\"ש ושבתם וראיתם בין צדיק לרשע כו' (וכמ\"ש במ\"א שלכך אמרו אין בן דוד בא אלא בדור שכולו זכאי או כולו חייב שזהו תכלית ההבדלה בעה\"ד טו\"ר כו') וכמ\"ש במ\"א ע\"פ ארדה נא ואראה כו'"],[2400650498,"אשכחן ראי' לטב כו' (ומבואר במ\"א שהן ב' עניינים שתלוים ברצון ובמקור הרצון שמחלק השכל לחו\"ג להטות השכל כלפי זכות לזכות גם את החייב הגמור ולהיפך להטות השכל לדין להרשיע גם את הצדיק כו' ע\"ש באורך) והנה עד\"מ מב' בירורי' הנ\"ל ששניהם בעומק העיון השכל ביותר רק שזה מעיין לתכלית הדין והדקדוק וזה תכלית עיונו לתכלית החסד כו' כך יובן בדוגמא זו בבחי' הבירורי' שבחכ' שבתורה שיש תורה של חסד ותורה של דין ושניהם בעומק החכ' דוקא דהנה אנו רואים בדינים ודקדוקים דהלכות טו\"ט ואו\"ה וכה\"ג שיוכל להיות הרבה דברים שנראים לכאורה ע\"פ החכ' בבירור ופשיטות שהן טהורים ומותרין עד שצריך עיון רב בעומק החכ' בפלפול להבין בדקדוקי הדיני' הרבה עד שימצא אמיתית הלכה שהן טמאין ואסורים ונמצא הי' תחלה התערובות בהם בתכלית הדקות וההעלם וע\"פ עומק עיון החכ' בפלפול שהוא בבחי' עומק השגחת עיון שבה וכח עומק הדין שבחכ' שגם הנראה טהור ומותר יטמא ויאסור והוא כמו הדק שבדקות סיג שנמצא בנקי מצד עיון הטוב וכמו דקות רע שבצדיק כנ\"ל שהרי כל עיקר חכ' זו רק לעיין ולעמוד היטב על עומק הדבר עד שיבין היטב לברר כל דברים דקים בדקות הענינים הפרטי' בבירור אחר בירור כמה פעמים עד שיוציא לאור משפט זה שהוא להיות הטמא טמא ולא לטהר את הטמא בדבר החכ' הנראה בתחלת השקפה ראשונה וזהו הנק' תורה של דין שבחכ' לטמא גם את הטהור לכאורה ולא לטהר את הטמא גם שהוא בתכלית הדקות ונראה כטהור ממש ונמצא זהו כמו בירור הנקי עד שיזרוק הכל לבד היותר נקי כך יטמא ויאסור הכל לבד מדבר הברור בתכלי' לטהר ולהתיר. והנה כמו\"כ יש להיפך מכח בחי' החסד שבחכ' נקרא תורה של חסד והוא למצוא שכל בעיון רב מאד לטהר גם את הנראה פשוט וברור שהוא טמא ואסור ע\"פ פלפול רב ועצום כדוגמא שמצינו בגמרא בתלמיד א' שהיה יודע לטהר את השרץ בק\"ן טעמים וכן מי שדן על הנחש שהוא טהור ואע\"פ שהוא לנגד אמיתי' הדין שבתור' מ\"מ עכ\"פ הרי יש בכחה של החכ' שבתורה לטהר גם את הטמא ממש ע\"פ הדין ומכש\"כ שיוכל כח החסד שבחכ' למצוא היתר וזכות גם למה שנראה חייב ואיסור עפ\"י השכל והדרש שבכתובים כידוע לכל מעיין בתלמוד בפלפול שיש בכח רוב הפלפול ב' הפכים הללו לטהר את הטמא ולטמא את הטהור (וכמ\"ש על המפלפלים לדין ולאיסור חכמים המה להרע ולהיטיב לא ידעו ולהיפך במפלפלים לזכות נק' חכ' להיטיב כמו עדה שופטת ועדה מצלת בסנהדרין ב\"ש אוסרין וב\"ה מתירין כו'. אך מ\"ש בגמ' על ר\"מ שהי' אומר על טמא טהור ומראה לו פנים וטעם לדבר ולהיפך ג\"כ אמר על טהור טמא"],[2400650499,"ומראה לו פנים כו' שהוא מצד שרשו למעלה מהתחלקות הקווין דחו\"ג שבחכ' שהן מ\"ט פנים טמא ומ\"ט פנים טהור כמ\"ש במ\"א באריכות) וזהו ותורת חסד על לשונה דוקא וד\"ל:\n(קמג) <b>והנה</b> הדוגמא מכל הנ\"ל בבחי' החכ' שבתורה שירדה לברר בירורין בעה\"ד טו\"ר כו' שיש תורה של חסד שמתברר הכל גם היותר תחתון דתערובות רע וטמא ופסול וחייב כנ\"ל כך יובן בבחי' ח\"ע דאצי' שע\"ז אמרו בחכ' אתברירו רפ\"ח ניצוצין למטה בבחי' נוגה דבי\"ע מתברר הכל ועולה למעלה מעולם הפירוד לעולם היחוד דהיינו בחי' אתהפכא חשוכא לנהורא ומרירא למיתקא כו' וההיפוך זה היינו בתערובות דק שאינו ניכר ולא בתערובות טו\"ר הניכר שאין צריך בירור בחכ' כנ\"ל והענין למעלה כידוע שיש בבחי' נוגה ב' מדרגות הא' ג' קליפות הטמאות לגמרי ונק' רע שבנוגה שנקרא טמא ופסול ואסור ממש ולא יוכלו לעלות לעולם בסט' דקדוש' כמ\"ש לא יגורך רע כו' טהור עינים מראות ברע וכה\"ג והיפוך מזה בתכלית הטוב שלאחר הבירור מכל סיג אפי' בדקו' מאד היינו בחי' סט' דקדושה שבבחי' האצי' ששם לאחר הבירור אין שם אפי' שרש לשרש המצי' דרע אפי' בתכלי' הדקות כו' משום דלא יגורך רע כלל הרי בכל דברים הללו לא שייך ענין בירור בחכ' כלל דבאצי' לא צריך בירור כלל ובחי' הבדלה ובירור להבחין ולהבדיל מן סט' דקדושה דכולו טוב לסט' דקליפה דרע דנוגה הנ\"ל שכולו רע ג\"כ לא נק' בירור הנ\"ל בחכ' שבתורה שא\"צ הבדלה בחכ' להבדיל בין טמא ממש לטהור ממש. אך עיקר הבירור שבחכ' הוא בא בעה\"ד טו\"ר שתערובתו בדקות והיינו בבחי' ומדרגה הב' שמעורב טו\"ר ואינו רע גמור לגמרי כמו נוג' דברי' שרובו טוב ומיעוטו רע ונוגה דיצירה שמעורב טו\"ר בחציו ונוגה דעשי' שרובו רע ומיעוטו טוב ועד\"ז יש הרבה חילוקי מדרגות שונות באופני התערובות עד שיוכל להתחלף רע בטוב לעוצם דקותם וכן יש להיפך שיוכל להתחלף הטוב ברע ולזה צריך בירור שבחכ' ועיון גדול כנ\"ל. ויש בזה ב' אופנים לעיין בבחי' הדין שבחכ' שלא יוכשר גם היותר טוב כנ\"ל ולהיפך בבחי' כח החסד שבחכ' יוכשר הכל כו' רק הפסולת היותר גס לא יעלה שהוא הרע הגמור ולפי\"ז מה שבכח הח\"ע דאצי' לברר למטה זהו מכח החסד שבה היינו להעלות הכל לקדושה גם לתערובות טו\"ר דנוגה היותר תחתון כמו נוגה דעשי' שרובו רע ומיעוטו טוב והרי גם המיעוט טוב דנוגה דעשי' היותר מצומצם יוכל לעלות הכל לקדושה והוא כמו הטוב שנמצא גם ברשעים שחוזרים בתשובה שנהפך הרע לטוב זהו אתהפכא כו' (ואע\"פ שרע גמור אין לו בירור לעולם כנ\"ל היינו שיעלה כמו שהוא אבל"],[2400650500,"באיבודו וכליון שלו זהו עלייתו ותיקונו כמ\"ש במ\"א בענין פי' באבוד רשעים רינה ודוגמא לדבר הבכיה מעומקא דליבא כראב\"ד עד שיצאה נשמתו ממש שבכה רבי ואמר יש קונה עולמו בשעה א' כו' הרי נהפך הרע לטוב ע\"י איבוד והתכללות במה שיצאה נפשו בבכי' וכה\"ג). וזהו כמו בחי' תורת חסד הנ\"ל שיוכל לברר בחכ' לטהר גם את הטמא ע\"ד הנ\"ל בענין כח הפלפול בחכ' לטהר את השרץ בק\"ן טעמים אעפ\"י שאינו כפי הדין כו' אבל בלתי גילוי אור ירידת החכ' למטה כ\"כ לא הי' הטמא עולה מטמאתו וזהו מי יתן טהור מטמא לא אחד כו' וכמ\"ש במ\"א וד\"ל. וזהו פיה פתחה בחכ' ותורת חסד כו' פי' בחי' ח\"ת שבמל' שמברר הכל שרשו בח\"ע דאור אבא דאצי' כידוע בענין חכמות בחוץ תרונה ח\"ע דאתמשיך בח\"ת הנק' חכ' בראש וחכ' בסוף וידוע דקמץ בכתר בקמיצות וסתימות השפתים והפתח בחכ' לפי שהחכ' שרשה ברב חסד דבי' אחיד אבא שיורד מגבוה לנמוך ע\"כ הוא בפתח דוקא שמורה בחי' הפתיחה שהיא התגלות חוץ כמו פתיחת השפתיים שבנקודות הפתח וכמ\"ש שפתי תפתח כו' פתיחת השפתיים להשפיע אור החכ' עד למטה מטה לעלות הכל בדבור שבפה דוקא לגזור אומר גם על הפסול וטמא שיוכשר ויטהר עפ\"י עומק החכ' והיינו בתושבע\"פ דוקא מל' קרינן לה כו' מתניתא מלכתא כידוע וזהו פיה פתחה בחכמה פה שדובר שפותח בגילוי אור לחוץ לבער גם כל התערובות טו\"ר דנוגה היותר חוץ שרשו בח\"ע בחסד שבה דוקא והיינו ותורת חסד על לשונה דהיינו ברב חסד דח\"ע בתושב\"כ כו' וד\"ל. וזהו הריעו לה' כל הארץ ר\"ת הלכה דתושבע\"פ דוקא דהנה מבואר למעלה דבחכ' שבתושבע\"פ דוקא ע\"י פלפול הרב בכח החסד דוקא יוכל לברר ולהעלות הכל גם מי שאינו ראוי לכאורה כך למעלה הרי יוכלו להעלות וליכלל בקדושה האלקי' גם מי שאינו ראוי לעלות כמו הבירור מעה\"ד טו\"ר שיוכל גם הטמא לטהר כנ\"ל וזהו הריעו לה' כל הארץ כל זה ריבוי לרבות הכל דהיינו לרבות גם לכל בחי' נוגה היותר קשה גם שלא הי' עולה ומתברר לעולם בלתי החכ' ובחכ' אתברירו הכל דהיינו בחכ' בסוף תושבע\"פ דוקא פיה פתחה כו' ותורת חסד על לשונה כנ\"ל וד\"ל. והנה פי' הריעו לה' לשון תרועה ושיר כפשוטו והפי' הב' לשון שבירה ופירור כמו תרועם כו' וכה\"ג שניהם עולין לסגנון א' דהנה פי' תרועה ושיר היינו פי' העלאה שלהם בקול תרועה דוקא לפי שהם ירדו למטה מאד ולא היו עולין לעולם ונק' מ\"ת בחי' מי בוכין מ\"ת בוכין אנן בעינן למהוי קדם מלכא לפי שקודם השבירה הי' למעלה ולא למטה ובשה\"כ נפלו למטה מטה מאד והן בחי' נוגה דסוף העשי' ולכך כשעולין ע\"י החכ' ונטהרין מטומאתן כו' אזי יריעו בקול תרועה דוקא כמו שידוע מעיקר ענין התרועה שהוא רק ענין"],[2400650501,"ההצלה וריוח מן השפלות ורע בלבד כו' וד\"ל. והפי' הב' לשון תרועם כו' הוא ענין בירור שלהם בחכ' שהוא בא בדרך שבירה ופירור כמ\"ש אתה פוררת בעזך כו' עד\"מ הרוצה לברר לדבר מה מגסותו בהכרח שצריך תחלה לשבור אותו ולפררו בפירורי' דקים ביותר כדי שיוכל להפריד ממנו הטוב שהי' גנוז ונעלם מתחילה ואז גם בחלק הרע ימצא טוב הרבה ודוקא ע\"י שבירה ופירור (והוא הנק' ג\"כ המתקת הגבורות קשות במלילה וריכוך לדבר קשה ביותר כמבואר במקום אחר פי' הזוה\"ק ע\"פ מי ימלל גבורות ה' כנ\"ל באריכות) וזהו תרועם ענין השבירה לברר הטוב הגנוז ולהוציא הפסולת הגס ביותר וזהו עיקר תיקונו ותכליתו ועלייתו כו' ושני הפי' עולין בקנה א' שהוא רק תכלית שלימות הבירור מכל אשר יוכל להתעלות מרפ\"ח ניצוצין שנפלו בנוגה עד הפסולת היותר גס שיפול לאיבוד גמור (וכמארז\"ל לע\"ל ישחוט ליצה\"ר כו') כמו לע\"ל דכ' אז אהפוך אל עמים שפה ברורה כו' כמו ונהרו אליו כל הגוים כו' וראו כ\"ב כו' ויהי' עלי' לכל וזהו כל הארץ ריבוי לרבות הכל. (ודוגמא לזה הרי אמרו עתיד חזיר ליטהר שנאמר יכרסמנה חזיר מיער ע' תלוי' ע\"ש דנוגה דעשי' כמבואר במ\"א). וזהו ר\"ת דהריעו כו' הלכה דווקא כמו א\"ח עט\"ב ובחכ' בסוף בתושבע\"פ בהלכות דווקא יתברר הכל (ודווקא בהלכות טומאה וטהרה כמ\"ש במ\"א בענין והי' אמונת כו'. ודעת זהו סדר טהרות משום דלפתח חטאת רובץ וע\"כ בסדר טהר' דווקא יבורר הכל עד חטאת שבפתח שהוא נחש על עקבו כו') ומ\"ש לה' דווקא היינו לבחי' החכ' שהוא בשם הוי' דח' (כי חסד גי' ע\"ב והוא שם ע\"ב דח\"כ והיינו תורת חסד דווקא כו') משום דה' בחכ' יסד כמ\"ש ה' בחכ' יסד ארץ שבחכ' ג\"כ איתברירו הכל כל מה שאפשר להתברר ואח\"כ אמרו דמשחרב בהמ\"ק אין לו להקב\"ה בעולמו אלא ד\"א של הלכה בלבד כו' (דהלכה לשון הילוך שהוא הילוך מלמעלה למטה כמ\"ש הליכות עולם לו וכן הליכות אלי כו' והילוך מלמט' למעלה שהוא הבירור והעלי' שעולין ומתבררין והולכין הכל מלמטה למעלה כנ\"ל וד\"ל):\n(קמד) <b>ומעתה</b> י\"ל מה שייכות יש להריעו לה' כו' עם תחלת המזמור שא' מזמור לתודה מה ענין קרבן תודה עם ענין הבירור שבחכ' הנ\"ל. אך הנה לפי כל הנ\"ל בביאור הריעו כו' ר\"ת הלכה שבחכ' שבתו' שנק' תורת חסד מתברר ועולה הכל כנ\"ל. כך יובן בענין קרבן תודה שנבדלו בזה מכל הקרבנו' שהרי מברר הכל כדוגמת בירור שבחכ' שמברר הכל כנ\"ל. ולז\"א מזמור לתודה הריעו לה' כו' ששניהם ענין א' דכמו בהלכה הריעו לה' כל הארץ כל ריבוי לרבות הכל כך הוא ע\"י קרבן תודה דווקא ולזאת מזמור לתודה"],[2400650502,"דווקא. ולהבין זה הנה יש להקדי' ביאור ענין המשנה הידועה דכל המנחו' באות מצה חוץ מתודה ושתי הלחם דבשתי הלחם כ' חמץ תאפינה ובקרבן תודה הי' יו\"ד חלות של חמץ כידוע. ובאמת זהו כדבר פלא לכאורה למה נבדלו ב' קרבנות הללו דווקא דתודה ושתי הלחם במנחתם ושאר כל המנחו' שבאות מצה דווקא ונאסר בהם כל שאור ומחמצת כידוע רק בב' מנחות הללו שצוה להביאם מחמץ. אך הנה תחלה י\"ל שרש ענין ההפרש בין חמץ למצה בהיות מבואר בר\"מ פ' פינחס דעיקר ההפרש בין חמץ למצה אינו רק באות א' שהוא בין חי\"ת לה\"א דחמץ אות הראשון שבו הוא החי\"ת ובמצה אות האחרון הוא ה\"א וההפרש שבין תמונת אות החי\"ת לאות הה\"א זהו עיקר ענין ההפרש בין חמץ למצה וההפרש בין החי\"ת לה\"א אינו רק ברגל השמאלי כי בגגו וקו הימיני שניה' תמונת' שווים כתמונ' אות הד' רק בקו ורגל השמאלי הוא שיש הפרש שבחי\"ת הקו השמאלי נמשך מראש הגג ונמשך למטה כמו קו הימני ממש כצורת הפתח במשקוף וב' מזוזות ובה\"א רגל וקו השמאלי מופסק מגגו כי יש חלל הפסק מעט בין הגג להרגל כידוע ובזה ההפסק חלל ריקן המועט שהוא כמו פתיחה לחוץ מתוך וחלל האות הוא שיש הפרש ביניהם והוא עיקר ההפרש כידוע. ונמצא שעיקר ענין ההפרש אינו רק שבחי\"ת סתום מג' רוחות שלו למע' ושני צדדי' ובה\"א יש פתיחה סמוך לגג ברגל השמאלי שמפסיק ובחי\"ת סתום במקום זה ונמצא זה סתום למעלה וזה פתוח למעלה ופתיחה דלצד מטה בשניהם שוין. ויובן כ\"ז בענין ההפרש שבין חמץ למצה. אך תחלה י\"ל בשורש ענין האותיות שיש בהם בחי' ראש תוך סוף שהוא בחי' חב\"ד חג\"ת נה\"י בכל אות לפי מדרגתו כמו אות א הרי אות יו\"ד שבראשו הוא בחי' חב\"ד והקו האמצעי חג\"ת ויו\"ד שתחתיו נה\"י כו' וכן באות הב' גגו חב\"ד וקו האורך חג\"ת וקו שתחתיו נה\"י כו'. אמנם בח' וה' שהן ג' קוין העליון חב\"ד וקו הימיני חג\"ת וקו השמאלי נה\"י כי אין בו למטה כלום וביאור הדברים ידוע שכל אות הוא בחי' המשכה מיוחדת ובהכרח שכל המשכה יש בו ג' מדריגות הללו חב\"ד חג\"ת נה\"י כו' שהוא בחי' רת\"ס ולפי\"ז גם באות החי\"ת או הה\"א יש בו ג' מדריגות הללו בג' הקוין שבו קו העליון הוא בחי' חב\"ד כו' וקו הימין שנמשך באורך מלמעלה למטה הוא בחי' חג\"ת והקו השמאל הוא בחי' נה\"י והוא סוף ההשפעה של האור כאשר יוצא מן האור שפע למקבלים ובו הוא עיקר ההפרש בין החי\"ת וה\"א שבחי\"ת אור הקו השמאלי סתום ג\"כ כמו קו הימין מבלתי ימצא בו שום פתח פתוח לחוץ כלל לא למעלה ולא לשום צד אך ורק בתחתית החי\"ת פתוח למט' בכל החלל של האות לצד מטה דווקא משא\"כ באות הה\"א שימצא בו פתח מצד השמאלי למעלה דווקא והוא באותו חלל ריקן שהוא המפסיק בינו לגג האות שהוא ראשו"],[2400650503,"העליון ונמצא הפסק פתיחה זו הוא בין ראש העליון של האות לרגלי' וסופו שהוא רגל הקצר המופסק שזהו הפסק בין ראשו לסופו שזהו בין חב\"ד לנה\"י כו' ולא יש הפסק בין ראש לאמצע שהוא קוץ הימין כו'. אך בפתח זה שבין הגג לרגל הקצר נק' פתח העליון שבו יוצא מכללות חללה של אות שבין קו העליון ואורך קו הימין לרגל הקצר זה כו' ופתיחה זו מצד השמאל למעלה ולא למטה בפתח התחתון שבתחתית האות כו'. והנה הדוגמא מכל הנ\"ל יובן למעלה בבחי' אות חי\"ת וה\"א בהפרש שבשניהם בתמונתם למעלה בהיות ידוע שהמל' נק' פתח כמ\"ש בזוהר ע\"פ ותשב בפתח עינים כו' וכן והוא יושב פתח האוהל כו' וכה\"ג וכמ\"ש ופסח ה' על הפתח כו' כידוע והוא בחי' ג' קוין שבמל' כצורת הפתח במשקוף וב' מזוזות כו' הקו העליון הוא בחי' חב\"ד והקו האמצעי שהוא הימני בחי' חג\"ת שבמל' וקו רגל השמאל הוא בחי' נה\"י שבמל' שהוא בחי' השפעה למקבלי' בג' עולמות בי\"ע כו'. וידוע הענין שהפתח הוא מקום כניסה ויציאה שהכל נכנסין ויוצאין בו ע\"כ נמשל המל' לצורת הפתח שהוא בחי' פתיחה בהתגלות אלקות מאין ליש מאצי' לבי\"ע (וכמו שהפה מגלה הכל מן העלם שבמח' ומדות ושכל ורצון כו') וכמו\"כ הכל נכנסין ועולין שם כמ\"ש זה השער להוי' כו' וכמבואר במ\"א. והנה בחי' ג' הקוין שבצורת הפתח דבחי' המל' הוא הכל המשכות אלקות בבחי' ג' מדריגות דרת\"ס כו' ובחי' המוחין המקור למדות הוא קו העליון ובחי' חג\"ת שבו הוא הוא\"ו שנמשך מגגו באורך מלמע' למט' ובחי' נה\"י שבו הוא בחי' רגל השמאלי וענין הפתח הפתוח מלמטה בתחתית חלל האות הוא ענין מ\"ש לפתח חטאת רובץ כמ\"ש בזוה\"ק והוא שפע חיצוני' והפסולת שנמשך למטה להיכלות דנוגה שעומדים באסקופת הפתח התחתון שבחי\"ת וה\"א להיות שאין החיצוני' יכולים לקבל מפנימי' ותוך חלל האות ולא מעצמות הקוין שבו רק מחלל הנפתח בסופו למטה דווקא כדוגמת רה\"ר שמתחיל מחלל הפתח שלמט' ולחוץ מפתח של רה\"י כו' (כמו תרעין דג\"ע דאסתימו כו' ומבחוץ לפתח בסוף האסקופה של צד חוץ דוקא שם להט החרב כו' ושם נא' לפתח חטאת כו' שיש שרש יניקה משם להיכלות דנוג' שנק' רה\"ר טורי דפרודא כידוע) והיינו גם למט' מבחי' נה\"י שבמל' שהוא רגל השמאלי דחי\"ת רק בחלק היוצא לחוץ מחלל התחתון שבחי\"ת שם עומדים החיצוני' שנק' חטאת וזהו לפתח חטאת כו' לפתח ולא בתוך הפתח כלל וכלל משום שנא' וכבודי לאחר לא אתן כו' כבוד הוא ל\"ב נ\"ח שבמל' שמאיר גם מבחי' נה\"י שבנה\"י כו' וגם בבחי' המל' שבמל' שהוא כמו האסקופה שבפתח אינם מקבלים רק מצד החיצון דווקא כו'. ונמצא מובן עכ\"פ שבציור תמונת אות החי\"ת שנק' פתח העליון דבחי' המל' אין שום יניקה לחיצוני' מכל צדדי הקוין שבו"],[2400650504,"רק בחלל היוצא למטה ששם הכל יכולי' לקבל מטעם הנ\"ל. וזהו ענין החי\"ת דחמץ שעכ\"פ יש שרש ומקור ליניקת החיצוני' שנק' שאור וחמץ כידוע בפתח היוצא למטה בתחתיתו אך לא למעלה גם לא בקו השמאלי כי סתום שם עד גגו שלא יקבלו החיצוני' שם כלל וכלל וד\"ל:\n(קמה) <b>ואמנם</b> הנה בזאת מעל' יתרון הה\"א על החי\"ת במה שיש בקו השמאל פתח חלל בין הגג לרגל הקצר כו' וזהו עיקר ההפרש בין חמץ למצה שהוא ההפרש שבין הה\"א לחי\"ת כו'. וביאור הדברים הנה כמו הפה באדם הוא בחי' גילוי אור השכל שבמוח בפתיחת חלל שפתים דפה וא\"א להיות שום גילוי אור החכ' ושכל לחוץ למקבלים רק ע\"י אמצעות כלי הפה והוא כפתיחת הפה בשפתים ששם נגלה אור החכ' כמו פתח פיך ויאירו דבריך וכן א' כמה פעמים בדבור בד\"ת לא ימוש כו' מפיך למען תהי' כו' בפיך וכ' פיה פתחה בחכ' שכל פתיחה בחכ' שהוא גילוי אור לחוץ למקבלים דווקא ואינו אלא בפה ולכך א' פיה פתחה כו' וחכ' שבראש הוא עצם כח השכל שמשכיל לעצמו וכך הוא נמשך ובא בגילוי במדות ומח' וכה\"ג. אך אין זה נק' גילוי לחוץ כמו בדיבור שבפה שמקבל השומע שהוא בא בבחי' דבר נבדל לגמרי משא\"כ במדו' ומח' שאינם נבדלי' מן העצם ולא נק' גילוי לחוץ ממש רק בפה בדבור וזהו טעם פתיחת הפה דווקא כמ\"ש פיה פתחה וכו' וכן אד' שפתי תפתח וכה\"ג (ומבואר במ\"א שמטעם אחר הפה למעלה מהלב אעפ\"י שלפי סדר ההמשכה צריך להיות הפה למטה מן הלב כי מן המדות נמשך לדבור אך לפי שנפש השכלי' נק' נפש המדברת דווקא והוא עיקר בחי' אדם שהוא בחי' מדבר בפה דווקא כמ\"ש מי שם פה לאדם כו' ולזאת עיקר יתרון מעלת אדם הוא בפה שהוא עיקר בחי' אדם מ\"ה דחכ' שבראש יותר ממדה שבלב וז\"ש פיה פתחה בחכ' כו' אעפ\"י שאינו רק גילוי לחוץ אבל זהו עיקר בחי' אדם מ\"ה דחכ' ולכך פיה פתחה בחכ' כו' הנ\"ל הוא יותר תחלה לכל כי מתאחד עם עצם כח השכל ממש ונק' נפש המדברת וכידוע דפי' ופה בבחי' יסודות דאו\"א כו'). והנה בציור הה\"א הרי בפתח חלל ונקב זה שבין הגג לרגל הקצר זהו ענין פיה פתחה בחכ' הנ\"ל להיו' מבואר למעלה דקוין דה\"א וחי\"ת הן ג' מדריגות חב\"ד כו' וקו העליון ואורך הקו כדלי\"ת הוא חב\"ד וחג\"ת וקו השמאלי נה\"י ונמצא בפתח וחלל קטן זה שבין הגג לרגל הקצר הרי נמשך בחי' המוחין דחב\"ד שבקו העליון מיד בפתיחה קטנה זו וממילא עולה ונכלל ג\"כ קו הימין והשמאל דהיינו שעולים ונכללים בקו העליון לצאת עמו בגילוי אור החכ' שבפה זה וכמ\"ש פיה פתחה בחכ' שהוא גילוי לחוץ ממש (וגם יש בו יתרון מעלה שמתאחד עם עצם פנימי' כ\"ח מ\"ה דחכ' שבראש מטעם הנ\"ל כמ\"ש מי שם פה לאדם כו') כמו שבאה\"ת הוא פתח לגילוי"],[2400650505,"אור החכ' שבראש כך באות ה' דבה\"א בראם הרי בחי' פנימ' חכ' שבראש שהוא בחי' פנימי' חכ' דאה\"ע דאצי' (שהוא בחי' פנימי' מוחין דאבא שבז\"א) יוצא בחלל פתח קטן זה שבין גג הה\"א לרגל הקצר וכמ\"ש חכמות בחוץ תרונה ח\"ע דאתמשיך בח\"ת חכ' שבפה בדבור שבחכ' שבמל' דאצילות אך אין זה הגילוי לחוץ דומה לגילוי פתח התחתון בחלל היוצא למטה בחי\"ת וה\"א כנ\"ל ששם יוצא לחוץ בהיכלות דנוגה בבחי' אחורים וחצוניו' כנ\"ל. אבל זה הפתח הוא להיפוך שבו יוצא גילוי או\"פ חכ' שבראש כאדם חכם גדול שמדבר דברי חכ' עמוקה למקבלי' השומעי' חכמתו וכך למעלה הוא פנימית חכמה שבדבור העליון כדברי ח\"ע שלמעלה הרבה מעצם החכ' המצומצמת בדבור ביו\"ד מאמרות כמו יהי אור שנק' שיחה בלבד כידוע. לכך במאמרות הללו יש שרש לאזלע\"ז כו' בק\"ך צירופי' דאלקי' כו' אבל פיה פתחה בחכ' כו' הוא בחכ' עליונה שלמעל' מחכ' זו שבמאמרות ואין שם שרש יניקה לחיצונים כלל וכלל כי א\"א להיות מקור למקור ליניקת החיצוני' רק מבחי' המדות שנפלו בשבירה כו' והוא בחי' חיצוני' ואחוריי' שבמדות הקדושה שבאו בגילוי אותיות הדבור כו'. אבל בעצם פנימי' החכ' שלמעל' מן המדו' גם בקדושה אין שם שרש לחיצוני' כלל כידוע בענין ימותו ולא בחכ' שאין בחכ' עצמה שום שרש אחיזה לחיצוני' שנק' מות ורע לפי שבחכ' לא הי' בחי' שבירה כלל (רק חיצוני' דאו\"א נפלו למטה). ולזאת גם באור החכ' למטה כמו בפתיחה והתגלות אור החכ' בפתח העליון דאות ה\"א הנ\"ל כמ\"ש פיה פתחה בחכ' כו' אדרבה מלבד שא\"א לחיצוני' לקבל משם שהרי נא' וכבודי לאחר לא אתן כו' כבודי ל\"ב נ\"ח עילאה שבח\"ת דמל' כו' אלא שמברר ומגרש יניקת החיצוני' גם בעמידת' למט' מטה בחלל ופתח התחתון שבחלל הה\"א כנ\"ל בענין לפתח חטאת רובץ כו' ואין החיצוני' יכולין לקרב א\"ע שם לקבל יניקה שהרי מפני הארת אור החכ' דפה העליון דפיה פתחה כו' שמאיר בפתח העליון הרי כל הג' קוין נכללים שם ואינן מאירין למטה בחלל התחתון כלל כמשל אדם שמדבר דברי חכמה עצמי' הפנימי' העמוקה ביותר שלא יקרב זר אז לקבל גם מפסולת וחיצוני' הנופל מנובלות חכמתו כי גם בחי' נובלו' שלו חכמה גדולה ופנימי' יחשב וכדוגמא שא' ועליהו לא יבול אפי' שיחת ת\"ח כו' (ולמעלה ג\"כ אמר ע\"ז וכבודי לאחר לא אתן כו') ומלבד זה הרי אמרו בחכ' אתברירו להבדיל בין טמא לטהור כו' שמצד אור פנימי' חכ' דפה העליון דה\"א הנ\"ל הרי מאיר אור זה בדרך ירידה גם בפתח התחתון להבדיל גם שם בין טמא כו' וטמא וזר לא יקרב שם לקבל כלל (ואעפ\"י שמבואר למעלה בפיה פתחה בחכמה ותורת חסד שיכולים הכל לעלות ולהתברר כו' זהו דווקא בקרבן תודה ושתי הלחם שבאות חמץ שגם החמץ יוכל לעלות כמשי\"ת בסמוך). ועוד מפני"],[2400650506,"שלא יחפוץ כסיל בתבונה כו' (וכמ\"ש בזוהר הק' כאשר מכריזין מאן בעי למחמי ולאסתכלא ביקרא דמלכא החיצוני' שנק' אלקים אחרים שעומדים חוץ יוצאי' והולכי' להם משום דלא יחפוץ כסיל כו'). וזהו עיקר ההפרש בין חי\"ת לה\"א דבחי\"ת הרי קו השמאל סתום גם הוא לגגו ואין מבחי' החכ' ומוחין שבקו העליון דחי\"ת שום פתיחה וגילוי כלל ולא עוד אלא מסבת הסתימה שנסתם הפה למעלה בין גג העליון דחי\"ת עד קו השמאל שבו הרי נתצמצם אור המוחין בהעלם וסתימות לבוא ולירד מטה מטה לבחי' נה\"י דקו השמאל שבו לצד התחתון שזהו כענין רגליה יורדות מות שהוא להתמשך מטה מטה להיכלות דנוגה ששם חטאת רובץ כו'. וזהו ענין החי\"ת דחמץ כו' משא\"כ בה\"א שהפתח העליון פתוח וגלוי מאו\"פ החכ' שבגג העליון כו' שאין שם יניקה לחיצונים כלל מטעם הנ\"ל. הרי גם למטה מטה מאיר בגילוי אור וגם שם לא יקבלו החיצוני' וזהו ה\"א דמצה בסוף התיבה וד\"ל. וזהו שרש ענין ההפרש בין חמץ למצה שהוא בין חי\"ת לה\"א שבחמץ החי\"ת בראש התיבה ובמצה ה\"א בסוף התיבה. אך זה גופא י\"ל למה בחמץ החי\"ת בראש ובמצה הה\"א בסוף הרי שניהם לחם דחטה (שהוא בבחי' החכ' כידוע בענין לחם גי' מזלא כו'). אך הנה ידוע בשרש ענין ההפרש שבין חמץ למצה ובטעם שנאסר החמץ בפסח להיות שהחמץ הוא ענין ההגבהה וההתנשאות היש בגסות כו' כדוגמת העיסה שנתחמצה בשאור וחמץ הרי ע\"י השאור שבעיסה זו נחמץ ותתפח ותעלה למעלה בעילוי לגובה וגם תתפשט ותתפח לצדדין בגסות ועובי הנפוח כידוע ונמצא השאור טבעו לעשות התפשטות והגבהה ונפוח זה הוא ברוח בחלל העיסה זהו אינו רק למראית עין ולא שנתוסף שום ממשות בעיסה זו כלל וכך יובן בענין הגבהה והתנשאות שנק' חוצפה וגסו' הרוח בבחי' יש גדול שנק' מלכותא בלא תגא וזהו שורש הקליפות שהוא בחי' יש נפרד בחוצפה והתנשאות בלי יש ממש בהן רק בלי טעם וכמו שבאדם יגבה לבבו בהתנשאות וחוצפה בלי טעם להעיז לגדול ממנו כעזי פנים כו' ולכך השאור והחמץ נאסר בפסח להיות שיצאו ממצרים בהיפוך מזה והוא בבחי' השפלות והביטול בעצמו בתכלית העדר הרגשת עצמו וה\"ז כמו עיסת המצה שהוא בלא שאור שלא תתפח כלל ולא יתוסף בה מאומה אלא כמו שהיתה בלילתה במידתה ושיעורה כן אחר האפיה ולא תגבה ותתוסף בה כלל כמ\"ש במ\"א שזהו הטעם שנקרא לחמא עניא כו' בבחינת שפלות הרוח ובבחינת ביטול היש בתכלית היפוך היש דגסות והגבהת הרוח ממש מן הקצה כו' וזהו עיקר ההפרש בין סט' דקדושה לסט' דקליפה כי בחינת הביטול הוא בבחי' החכ' כ\"ח מ\"ה כו' וביטול זה שבבחינת"],[2400650507,"השפלות הוא כלי לבחי' כ\"ח מ\"ה דח\"ע כמ\"ש במ\"א בענין ביטול היש דמצה כו' שהוא כלי לבחינת ביטול העצמות כו' לפי שנגלה עליהם עצמות אא\"ס שאינו שורה רק בבחי' מ\"ה בעצם הוצרך להיות בבחינת ביטול היש בתכלית והוא לחמא עניא דמצה וזהו הענין ה\"א דמצה שבסוף התיבה שהוא בחי' הביטול דחכמה שמאיר בפתח העליון דפה שבין גג הה\"א לרגל הקצר וכנ\"ל בענין פיה פתחה בחכמה ומזה אין יניקה לחיצוני' כלל כי שרשם רק בבחי' יש וגסות והוא ההיפוך ממש מן הקצה כו' ולכך גם בפתח התחתון דה\"א ששם עומדים החיצונים ג\"כ אינם יכולין לקבל כי מצד אור החכמה כ\"ח מ\"ה דפה שבה\"א גם למטה בפתח התחתון נמצא עכ\"פ בחינת ביטול היש בתכלית וכידוע בענין יהיב חכמתא לחכימין דוקא שהוא ביטול היש כו' ואמנם בהיפוך מזה בחמץ שהוא בבחינת יש וגסות והגבהה כנ\"ל ע\"כ ציור החי\"ת בלא פה פתוח למעלה אדרבה סתום להיות בחינת יניקה לחיצונים למטה כמ\"ש ומשם יפרד כו' ולזה הטעם החי\"ת הוא בא בראש התיבה דחמץ כי הוא שרשו ומקורו וכו' והה\"א בסוף התיבה דמצה כי הוא בחינת ה\"א תתאה דמל' והמילוי שבו ה\"א עילאה שזהו מ\"ש פיה פתחה בחכמה כו' ונתב\"ס וע\"כ הה\"א בסוף התיבה כו' וד\"ל. (והמ\"ם וצדי\"ק הוא בחילוף י\"ה בא\"ת ב\"ש כידוע בענין מצה בחילוף שם הוי' כו' ומ\"ם וצדי\"ק דמצה הוא י\"ה קודם לה\"א ומצה הוא מצוה חסר ווא\"ו כי בא המוחין בדילוג ובחמץ להיפוך דחי\"ת קודם לי\"ה שהן מ\"ם וצדיק כמ\"ש במ\"א בענין בה\"ם אותיות במ\"ה כו' וד\"ל):\n(קמו) <b>וזהו</b> שאמרו כל המנחות באות מצה חוץ מתודה ושתי הלחם דהנה מבואר למעלה בשרש ענין ההפרש שבין חמץ למצה שהחמץ הוא ענין גבהות והתנשאות הלב בבחינת יש דגסות כו' שא\"א לעלות וליכלל בקדושה להיותה בחינת היפוך המנגד לקדושה האלקי' כמו תועבת ה' כל גבה לב וכמ\"ש גבה עינים אותו לא אוכל כו' ומלבד שלא יוכל לעלות וליכלל בקדושה שאינה עולה שם רק בחינת הביטול והשפלות לגמרי היפוך היש וגסות כנ\"ל אלא שנאסר החמץ לקרבן מטעם זה כמ\"ש כל שאור ומחמצת לא תקטירו כו' שהוא כמו דבר זר ושנאוי וצריך לרחקו ולא לקרבו בקרבן והעלאה כי יפסול את הקרבן ובפרט המנחה שהיא הדורון לרצות כמו ירח מנחה כמשל המעלה מנחה לאדון ושר שצ\"ל בתכלית העילוי ולא ימצא בה שום שמץ דבר מכוער ובפרט בדבר המנגד לעיקר ענין המנחה שהוא השפלות והביטול המעלה מ\"ן לרצות את הכעס וכה\"ג ואם כן ההתנשאות וגסות החמץ הרי הוא פוסל לעיקר ענין העלאת מ\"ן דמנחה ולזאת נאסר החמץ בכל המנחות"],[2400650508,"ואינן באות רק מן המצה דוקא וכמ\"ש כל המנחות באות מצה לפי שבהעלאת המנחה בחינת אזכרתה ע\"ג המזבח להיות לריח ניחוח לא יהי' בה תערובות אחיזה לחיצונים אשר שנא ה' והוא הגסות והחוצפה כו' אלא מצה דוקא שהוא היפוך הישות וגסות רק בחינת ביטול ושפלות אמיתי שאין מזה שום צד יניקה לחיצונים כלל ומצד בחינת הביטול והשפלות יכולה לעלות לקדושה וליכלל שם בבחינת העלאת מ\"ן ביותר וכמו וערבה לה' מנחחת יהודה כו' וכן שאו מנחה ובואו לפניו כו' וכה\"ג ולכך כל המנחות דוקא באות מצה ולא חמץ לבד מנחה דקרבן תודה שהי' בה יו\"ד חלות של חמץ ושלשים חלות של מצה כידוע בארבעים חלות דתודה ושתי הלחם כתיב בהו חמץ תאפנה דוקא. וי\"ל למה במנחה דתודה צוה ה' לעשות יו\"ד חלות מחמץ לבד ובשתי הלחם כולו חמץ תאפנה כו' והנה תחילה י\"ל מהו הטעם שנבדל מנחת תודה ושתי הלחם מכל המנחות שמלבד שלא נאסרו בחמץ אלא שמצוה להקריבם מחמץ שהוא ודאי היפוך ענין המנחה כנ\"ל. והענין יובן בהקדים תחלה בענין ובחינת המל' שנקרא כסא וכמ\"ש והוכן בחסד כסא ויש כסא של ג' רגלים וכסא המל' של ד' רגלים והוא בחינת כסא דוד שנקרא רגלא רביעאה הרי כסא של ג' רגלים היינו בחינת חג\"ת שהן האבות שהן המרכבה לחג\"ת דז\"א כידוע. וביאור הדברים ידוע שמדות דאצי' הוא בחינת מקור להשפיע כל שפע מאצי' לבי\"ע והן חסד דין ורחמים וידוע שיש ב' מדריגות במדות פו\"ח פנימית המדות הוא בהארת גדלות המוחין שבהן כו' שהוא למעלה מהחזה כו' ואין שם שרש לעה\"ד טו\"ר כלל ונקרא עץ חיים כו' שמשם אין שרש יניקה לנוגה דבי\"ע כלל אבל מ\"ש וישב ה' מלך לעולם כמו יושב ודן את כל העולם כולו כו' וכן מלך במשפט יעמיד ארץ כו' שנקרא כסא המלוכה הוא בחינת חיצוני' המדות דז\"א בחינת נה\"י שמתצמצמי' ובאין בבחינת התפשטות המלוכה לשפוט העם שהן נשמות ומלאכים דבי\"ע שהן בחינת המדות שבמל' ומשם יש שרש לבחינת עה\"ד כו' כי אזלעו\"ז עשה אלקים כו' וכתיב מלך אלקים על גוים ג\"כ וכידוע (והוא למטה מהחזה שמשם מקבלת המל' כו') והוא ענין כסא של ד' רגלים כי בחי' חג\"ת דאצי' עצמן דשם איהו וחיוהי חד כו' למעלה מעה\"ד כו' נקרא כסא הוי' דז\"א אבל כסא המלוכה הוא בבחינת המל' דאצי' שנעשה מקור לעולמות הנפרדים מאין ליש כו' וז\"ש והוכן בחסד כסא שכלול ג\"כ מג' מדריגות דחג\"ת דאצי' והן י\"ס דחסד דאברהם שהוא מרכבה לחסד דז\"א וי\"ס של גבו' דיצחק כו' ורגלי רביעאה הוא בחי' מל' שבמל' שכלול ג\"כ מי\"ס והוא בחי' דוד שהוא בחי' מלך על עם נפרד ומשם יש אחיזה ויניקה לנוגה דבי\"ע ג\"כ וכמו מלך אלקים על גוים כו' מאחר"],[2400650509,"ששרש בנין המל' מבחינת חיצונית המדות ששם מתחיל עה\"ד כנ\"ל ע\"כ ברגל רביעי דוקא יש שרש יניקה ג\"כ לנוגה והוא ענין יו\"ד חלות של חמץ שבארבעים חלות דתודה נגד י\"ס דמל' שבמל' שנקרא רגל רביעאה שנאחזים בה י\"ס דנוגה דבי\"ע שהן מבחינת חמץ שהוא יש נפרד (כנ\"ל בפי' החי\"ת דחמץ שהחיצונים מקבלים למטה מתחת הג' קוין כו') אבל שלשים חלות הן של מצה דוקא לפי שבחינת חג\"ת שבמל' ששרשם בחג\"ת דז\"א דאצי' שלמע' מעלה מעה\"ד טו\"ר כנ\"ל א\"א להיות שם יניקה ואחיזה לחיצוני' כלל ע\"כ באות מצה דוקא שהוא בחי' הביטול היפך היש דוקא כמו האבות שהן המרכבה כו' אבל בי' חלות בלבד שהן לנגד מל' שבמל' שיש מהן אחיזה לנוגה הן של חמץ דוקא מטעם הנ\"ל וד\"ל. אך זה גופא י\"ל איך יקריבו חלות של חמץ במנחה דקרבן תודה מאחר שהוא היפך בחינת המנחה ממש כנ\"ל. דהנה מבואר למע' בענין הריעו לה' כל הארץ שע\"י בחי' הבירור שבחכ' יוכל לברר ולהעלות את הכל מעה\"ד טו\"ר גם לטהר את הטמא כנ\"ל וא\"כ הרי גם בחי' החמץ שהוא היש וגסות הנפרד יוכל להתהפך ולהתקרב ע\"י בחי' הבירור שבחכ' והוא מפני שהחכ' נקרא כ\"ח מ\"ה בעצם דוקא שהוא בחינת הביטול בעצם שיש בכחו לעשות בחינת ביטול היש וגסות דנוגה דחמץ ג\"כ להיות ג\"כ בחינת הביטול היש הגס לאין האלקי כנ\"ל עד\"מ מחמת אימה של מלך או מחמת עוצם גילוי חכ' של חכם גדול יתבטל במציאות גם הגיאות והגסות הרי מפני שנעשה בו בחינת ביטול גדול (וכה\"ג היו בבצקת של אבותינו שלא הספיק להחמיץ להיות בחינת יש מצד גילוי שכינה מורא גדול כמ\"ש במ\"א). אך בכאן הרי הכוונה שהחמץ עצמו יוקטר למעלה במנחה ע\"ג המזבח להיות כמו שהוא בבחי' הקדוש' ה\"ז כענין התלהבות יש בולט דקדושה שבא לכלל ביטול והעדר הרגשת עצמותו כענין התמימות המופלגת כמבואר במ\"א וכך בבחי' כח מ\"ה דחכמה שבו גילוי אלקות יוכל להעלות גם החמץ הן יו\"ד חלות דחמץ שעולין במנחה דקרבן תודה דוקא ולא בשאר המנחות זולתה לפי שקרבן תודה הוא בבחי' ההודאה שהוא בבחי' החכמה דוקא ובחכמה אין שום צד יניקה לחיצוני' כנ\"ל בענין ימותו ולא בחכ' ולא עוד אלא שבחכ' אתברירו להעלות מעה\"ד טו\"ר גם הטמא יטהר כנ\"ל. ולזאת בקרבן תודה דוקא מצוה להיות יו\"ד חלות של חמץ דנוגה שי\"ס דנוגה שנאחזים במל' שבמל' עולין גם הם ונכללי' בקדושה האלקי' ולא בכל המנחות זולתה שאין באות אלא מצה דוקא כנ\"ל ולא חמץ מטעם שאינו בבחי' ההודאה דחכ' כקרבן תודה וד\"ל. וזהו הריעו לה' כל הארץ שא' בקרבן תודה דוקא דהיינו לרבות גם יו\"ד חלות של חמץ שהן לנגד ע\"ס דנוגה דבי\"ע שמקבל ממל' דמל' שנקרא רגלא רביעאה דכסא המל' כנ\"ל וזהו"],[2400650510,"כל הארץ כל זה ריבוי לרבות הכל משום דבחכ' בחי' כ\"ח מ\"ה שבהודאה וביטול דקרבן תודה אתברירו הכל גם בחי' החמץ דנוגה מטעם הנ\"ל משא\"כ כל הקרבנות במנחות שלהם זולתה שנאסר בהן החמץ לגמרי כמ\"ש כל שאור כו' לפי שאין ביכולתם וכחם לברר ולהעלות גם את החמץ שיוכלל בקדושה רק בחי' החכמה שבבחי' הודאה בלבד ולכך סמך זל\"ז באמרו מזמור לתודה דוקא אז הריעו לה' כל הארץ משום דבתודה דוקא יעלה ויתקרב הכל גם החמץ לא בזולתה וד\"ל:\n(קמז) <b>ומעתה</b> י\"ל מ\"ש בשתי הלחם חמץ תאפינה שכל השתי לחם היו של חמץ ובקרבן תודה לא הי' רק י' חלות של חמץ כי הנה מבואר למעלה בבחי' ההודאה דקרבן תודה שהוא כמו ההודאה על הנס שהוא בחי' גילוי שם הוי' דוקא באלקים מלמעלה מן הטבע בטבע כו' והוא בחי' אין דכ\"ח מ\"ה דחכמה שבא בגילוי ואין מסתיר לו שם אלקים המצמצם כשמש ומגן כו' כנ\"ל באורך ואין זה רק בחי' גילוי חיצוני' הוי' בלבד כניצוצי אור הבוקעי' בנקבי המסך (כמו ך\"ו כל\"ח דשם הוי' מאיר בשם אלקים כו' כנ\"ל) אבל אין זה אור עצמי ממש דבחי' הוי' דחכ' עצמה כמו שהוא למעלה בעצמותו מאחר שאינו נתפס בהשג' רק בבחי' הודאה וביטול שלמעלה מן השגה בדבר פלא אבל מ\"ש כי הוי' הוא אלקים שהוי' עצמו בא בבחי' השגה ודע' באלקי' ואין שם אלקים בטל ונכלל כמו בהודאה דבינה נכלל בחכ' אלא אדרבה בחי' היש דשם אלקים כמו שהוא אינו מסתיר כלל (וכמו הניסי' שבאו בהתלבשות דרך הטבע מפני שאין הטבע מסתיר כלל כנ\"ל באורך) וזהו ר\"ת הריעו לה' כו' הלכה דתושבע\"פ שיחוד הוי' אלקים דתושב\"כ ותושבע\"פ שהוא יחוד כל פנימיות ועצמיות דחו\"ב (שהוא למעלה גם מיחוד פנימי' דאו\"א להוליד נשמות בשבת כנ\"ל בסוף אות קמ\"א) להיותו מיש האמיתי ליש דמקבל בבחי' כל עצמותו ולא מאין ליש כו' וזהו ענין שתי הלחם שהן תושב\"כ ותושבע\"פ שנקרא שתי הלחם כידוע בענין לכו לחמו בלחמי ומבואר במ\"א ע\"כ נאמר בהם חמץ תאפינה שאין בחי' החמץ יש נפרד כלל כו' כמו שאין בחי' הטבע מסתיר כלל אלא אדרבה הוא בחי' יש מקבל מיש האמיתי שזהו ענין יחוד כל פנימי' ועצמיות דתושב\"כ בתושבע\"פ מל' קרינן לה שלזה הטעם נקרא הלכה בר\"ת ולא כמו הריעו לה' כל בריבוי בלבד משום דקרבן תודה הגם שזהו ג\"כ בבחי' חכ' אבל אין זה בפנימי' ועצמי' שלה לכך הי' ל' חלות של מצה דוקא בחי' הביטול דאין שלמעלה מן ההשגה ורק י' חלות של חמץ שהי' מקריבי' עם השלשים חלות של מצה משום דבחכ' אתברירו בכ\"ח מ\"ה שעושה בחי' ביטול היש שזהו כמו ענין ההודאה על הנס כו' משא\"כ בשתי הלחם שלא הי' צריך לבחי' בירור וביטול"],[2400650511,"היש אלא חמץ תאפינה משום שהיש עצמי אינו מסתיר כלל (וזהו מצד שרש עצמיות התורה בעה\"ח שלמעלה מעה\"ד לגמרי כו' כמו שיהי' לעתיד בתשלום הבירורים אבל עכשיו אוריי' מח\"ע נפקת לברר בירורי' בעה\"ד טו\"ר כו') וכמו\"כ ענין ל' חלות דמצה שמבררים ליו\"ד חלות דחמץ כמו לטהר גם את הטמא וכן ענין שלשים מעלות דמל' כידוע בענין שלשים הגבורים אשר לדוד שעוזרים לבחי' המל' שהן בחי' ל' כלים דנה\"י דז\"א שמהן בנין המל' כו' וכך ל' חלות דמצה שבבחי' הביטול דחכמה מעלין גם י' חלות דחמץ דנוגה כו' וד\"ל ובזה יתורץ הקושי' דלעיל (באות קמ\"ה) בענין פיה פתחה בחכ' ותורת חסד כו' שיכולים הכל להתברר כו' ה\"ז בבחי' ה\"א דוקא דפיה פתוח למעלה בין הגג לרגל הקצר כו' ואז גם החמץ יוכל לעלות כיו\"ד חלות של חמץ שעולין במנחת תודה לפי ששרש חכמה זו שבפתח הפתוח למעלה הוא בחכ' עילאה שלמעלה מחכ' שבמדות שבעה\"ד טו\"ר ע\"כ יש בכחה דוקא לברר גם לחמץ כמו התורה ששרשה בעה\"ח ע\"כ יש ביכולתה לברר לעה\"ד טו\"ר כנ\"ל. ולהבין ענין שרש התורה כמו שהיא למעלה מבחי' הבירורים שמבררת בעה\"ד כנ\"ל שזהו ענין שתי הלחם דשבועות כנ\"ל הנה אנו מוצאי' כדוגמא זו בשעת מ\"ת שהי' כענין מדריגה דלעתיד בביעור הרע מכל וכל שהרי א' ישראל שעמדו עה\"ס פסקה זוהמתן כו' לולי חטא העגל שחזרו לטומאת נחש הקדמוני כו' וכמ\"ש חרות על הלוחות חירות ממה\"מ כו' שזהו כמו לאחר תשלום כל הבירורים דעה\"ד טו\"ר דכתיב ואת רוח הטומאה אעביר כו' והיינו לפי שבחי' פב\"פ דבר ה' כו' ביו\"ד הדברות כשאמר אנכי ה' כו' אנכי מי שאנכי בחי' פנימי' ועצמו' אוא\"ס שבחכמה שבי' הדברות וכמ\"ש וירד ה' על ה\"ס כו' וירידה זו הי' מבחי' עצמיות שהוא מאיר למטה כמו למעלה ממש בלתי הסתר ולבוש כלל וכמו לע\"ל דכ' עין בעין יראו כו' למטה כמו למעלה ממש בהשוואה א' וא\"כ אין בחי' היש דנוגה מסתיר כלל ולכך גם בכל חג השבועות בזמן מ\"ת מאיר מאותה המדריגה כי דבריו חיים וקיימים ולזאת מצוה בשתי הלחם שהן תושב\"כ ותושבע\"פ שיהיו נקרבין מחמץ שגם החמץ דבחי' נוגה אינו מסתיר כלל וכלל וד\"ל (וסימן לדבר ממה שאין ד\"ת מקבלין טומאה ובעלי קריין מותרי' בד\"ת). אך עדיין י\"ל למה יהי' החיוב והמצוה לאפות' חמץ ולא מצה כמ\"ש חמץ תאפנה דאם מפני שאין שהחמץ פוסל ומזיק למה יהי' החמץ מצוה וחובה דלכאורה בחי' החמץ בחי' יש עכ\"פ והתירוץ מובן ע\"פ הנ\"ל ביחוד פנימי' ועצמו' דתושב\"כ ותושבע\"פ שכל אשר לאיש כו' שזהו מיש העצמי' ליש עצמי דמקבל עצמיות בעצמיות כו' וכמו לע\"ל דכתי' להנחיל אוהבי י\"ש יש האמיתי כו' וכמ\"ש במ\"א בענין ששרש היש גמור מבחי' היש האמיתי שלמע' מבחי'"],[2400650512,"האין של היש וכנ\"ל בענין דעו כי ה' כו' וכמו יש דהטבע שהוא בחי' כלי גמור לעצמיות אלקות (בלי בחי' אמצעי ביניהן כלל וכניסים שנעשו דרך טבע ממש וכנ\"ל בענין הנה העלמ' הרה כו') אורות בלתי מוגבלים כו' וכך ועלמות אין מספר אלו הלכות דוקא וכך יובן הטעם בשתי הלחם שמצוה בחמץ דוקא שהוא בחי' יש נפרד דחמץ שהוא נעשה בחי' כלי ויש גמור לקבל יש האמיתי מקור' דכולא ואינו בחי' יש נפרד כלל אדרבא ביש שלו דוקא שורה בחי' יש אמיתי ממש ויובן זה ע\"ד דוגמא ממה שמצינו בבחי' התנשאות היש דקדושה האלקי' כמו התנשאות דוד במלכותו שהי' מרכבה לבחי' מל' דאצי' בתכלית הביטול וכמ\"ש ונקלותי עוד כו' וכן א' כי עני ואביון אני כו' וא\"כ ההתנשאות ויש שלו הי' שורה ביש והתנשאות זו בחי' התנשאות ויש האמיתי דבחי' מל' דאצי' שז\"ש ה' מלך גאות לבש כו' וכמ\"ש רשב\"י אנא סימנא בעלמא כו' שהגביה א\"ע מאד ואין זה בחי' פירוד בגבהות הלב דחמץ הנ\"ל אלא אדרבה בגבהות הלב זה שורה גאות ה' והתנשאות העליונה האלקי' ממש ולא כמה שכתוב ביהושפט ויגבה לבו בדרכי ה' שהרי דוד א' לא גבה לבי כו' אלא אדרבה כל מה שגבה לבו לא הי' רק בחי' גבהות ה' והתנשאות האלקי' ממש ואמנם מלובש בהתנשאות וישות שלו הטבעי' ממש וא\"כ מובן מזה שהיש שלו הוא יש דאלקי' באין אמצעי ביניהם כו' וזה השלימו' לתכליתו יהי' במשיח שהוא למעלה מבחי' משה כמבואר במ\"א בענין ויתהלך חנוך ואיננו אבל גופו של משה לא עלה למעלה אבל גופו של משיח למעלה מזה כי ישרה עצמות אלקות בגופו ולא יבוטל גם בנשמתו ולא כמו משה שהי' בחי' ביטול בנשמתו גם שדבר עמו פא\"פ ולא נתבטל גופו כשאר הנביאים וזה האות שבחי' יש האמיתי שורש ביש שלו כמו שהוא בגופו ונשמתו בלי ביטול כלל וכלל כו' וכך הי' בלוחות הראשונו' שבחי' יש שלהם קיבל מיש האמתי העצמי' ממש פב\"פ ולכך שלט עה\"ר כו' (ועכשיו אין ת\"ח שאין בו חלק שמיני שבשמינית אבל לא יותר שנק' גס אותיות ס\"ג ולע\"ל גס וס\"ג יתאחדו והוא יש דבינה בחי' ס\"ג ויש מוגבל לאחר הבירור וזהו אותיות סוס גימט' ב\"פ ס\"ג כמ\"ש במ\"א בענין וסוס אשר רכב עליו כו') ובכ\"ז יובן ענין המצוה בשתי הלחם חמץ דוקא שהוא יש נפרד בבחי' יש דקדושה ממש כו' ולכך חמץ תאפינה ולא מצה שהוא ביטול היש כו' וד\"ל. (ועוד דוגמא לדבר ממ\"ש ויחזו את אלקים ויאכלו כו' וכן ממ\"ש שעוה\"ב אין בו אכילה כו' וגילוי זה העונג האלקי' נכנס בכלי הגוף גשמי בבחי' מזון גשמי ממש כו' כמבואר במ\"א):"],[2400650513,"<h3>עבדו את ה' בשמחה</h3>\n(קמח) <b>עבדו</b> את ה' בשמחה כו'. הנה אחר שדבר במזמור לתודה בבחי' ההודאה שבחכ' דוקא כנ\"ל אח\"כ מתחיל לדבר בבחי' שמחה שהוא בבחי' השגה דבינה דוקא וז\"ש עבדו את ה' בשמחה והוא היפך"],[2400650514,"ההודאה שהוא למעלה מן ההשגה לגמרי רק בבחי' ביטול שלמעלה מן הטעם כנ\"ל באריכות והעבודה בהתפעלות השמחה באה מצד ההשגה והתבוננות דוקא כידוע בפי' אם הבנים שמחה כו'. ולכאורה י\"ל זה איך אמר דבר והיפוכו מזמור לתודה בחכמה שלמע' מהשגה ולעבוד בשמחה שמצד ההשגה דוקא. ואמנם באמת מבואר למעלה במזמור לתודה שהוא בחי' יחוד או\"א דיצי' שהוא יחוד חו\"ב ואיך יתכן היחוד בב' הפכים הללו ומזה יובן ג\"כ ענין עבדו את ה' בשמחה אחר מזמור לתודה דוקא. והנה תחיל' י\"ל ההפרש בין חכ' לבינה שנק' אין ויש שמהם נולדו ב' מיני התפעלות הפכים שהוא התפעלות הביטול והתפעלות השמחה כו' דהנה ידוע שזהו ענין שבת ויו\"ט ששבת הוא נק' קודש מלה בגרמי' ויו\"ט נקרא מקרא קודש דנפיק מקודש כו' והיינו שהשבת הוא בחי' מוחין דאבא עצמו ובינה נכלל בו ויו\"ט להיפך שהוא בבחי' אור אימא ואור אבא שנק' קודש בהעלם בו כו' וזהו הטעם שבשבת עיקר המצוה בעונג כמ\"ש וקראת לשבת עונג כו' וביו\"ט עיקר המצוה בשמחה כמ\"ש ושמחת בחגך מועדים לשמחה כו' והעונג והשמחה ב' הפכים שזה בהעלם וזה בגילוי כו' והענין הוא דמשום דמכח החכ' שהוא בבחי' העלם ואין כח מ\"ה כו' נולד מזה בחי' התפעלות הביטול דוקא שהוא בחי' העדר הרגשת עצמו וכל שיתפעל יותר יותר יבוטל ויהי' ניזוז ממקומו (בל\"א צו רירט פון ארט) והוא מצד החכ' כ\"ח מ\"ה שלמעלה מן השגה וטעם ע\"כ מוליד התפעלות הביטול שאינו בהשגה וטעם (והוא ענין התפעלות שאינו מרגיש כלל וכלל שהתפעלות זו עמוקה ביותר היינו שלא ירגיש כלום כי נתבטל יותר וניזוז ממקומו וזה אינו אלא בהתפעלות העונג דוקא) (הנקרא בל\"א איין קוועל אין תענוג כו') וזהו ענין עונג שבשבת כמ\"ש אז תתענג כו' אבל ההשג' וההסבר בטוב טעם בהתבוננות יוליד התפעלות השמחה בלב בהתגלות ובמורגש התלהבות אור כידוע וכל מי שיתפעל יותר בהתבוננות היינו שיותר יהי' האור והשמחה גלוי בלב במורגש יותר בבחי' יש כידוע. והנה ביו\"ט שהוא התגלות אור הבינה במדות חג\"ת כידוע בענין ג' רגלים שנק' מקראי קודש כו' ע\"כ מצוה בשמחה בהתגלות ואור החכ' בחי' אין שלמעלה מהשגה נכלל בו בהעלם אבל בשבת נהפוך הוא שבחי' בינה נכלל בחכ' והוא השגה דבינה שנכלל בכח מ\"ה דחכ' ולפי\"ז השמחה נכלל בגילוי התפעלות העונג בשבת והעונג נכלל בגילוי התפעלות השמחה ביו\"ט כו'. אך הנה בחי' יחוד חו\"ב היינו שבחי' התפעלות העונג דחכ' שבהעלם באה לידי גילוי בהתפעלות השמחה והי' לאחדים וזהו ענין מזמור לתודה שבחול שאע\"פ שבחול אינו רק בחי' המדות בקטנות לצורך שפע העולמות אבל כתיב ישמח ה' במעשיו בבחי' שמחה שמתלבשת בקטנות דעשי' עכ\"פ כאדם"],[2400650515,"ששמח מטוב פעולת ידיו כמו כי שמחתני ה' בפעליך כו' והגם שאינה בערך לגבי שמחה עליונה שלמע' מבחי' העשי' כמו בשמחה שבדבור ומח' ומדות ושכל וכו' מ\"מ נק' שמחה במעשה עכ\"פ ובשמחה זאת נגלה גם העונג שבעשי' זו בגילוי גמור וזהו בחי' או\"א דיצירה שמקבלים שמחה מהסתעפות טוב העשי' מדבור שביצירה וז\"ש ישמח ה' גם בחכ' במעשיו דהיינו שמחה שבמעשה כו' ולכך אמר עבדו את ה' בשמחה כי השמחה שמצד השגה נק' עבודה אבל העונג שבחכ' שבהעלם הוא נעשה ממילא ומאיליו (דמוח החכ' קר ולח כו' שעונג רוחני שבמוח החכ' בחי' עצמיות הוא משא\"כ מוח הבינה חם ויבש בבחי' גבורות ה\"ז בא ביגיעה בתולדות גילוי התלהבות בינה ליבא כו') ובעבודה זו דשמחה דבינה באה ג\"כ בחי' ההודאה דחכ' שאמר תחלה מזמור לתודה דהיינו שגם בחי' ההודאה דחכ' שלמעלה מן השגה בא ונמשך בגילוי בהתפעלות השמחה שמצד השגה כו' וד\"ל. וכ\"ז בחול אבל בשבת ויו\"ט הוא בחי' חו\"ב דאצי' כמו שהן בעצמן ולא כמו שהן יורדין למטה במל' דאצי' בבי\"ע שנק' או\"א דבריאה או או\"א דיצירה כו' והענין הוא שהוא בחי' העונג והשמחה דהוי' דאצי' שזהו למע' הרבה מענין ישמח ה' במעשיו אלא הוא בחי' עונג ושמחה שמצד בחי' חו\"ב דאצי' עצמו כמשל אדם שמתענג ושמח בעצמו שלא מצד פעולותיו (רק שטוב הצלחתו בפעולתו גרם לו שמחה ותענוג זה בעצמו כמו ויכולו השמים כו' כי הוטב בעיניו כו' כמו דכתיב כי שמחתני ה' בפעליך כו'). ובזה יש הפרש בין שבת ליו\"ט דבשבת הוא גילוי התפעלות העונג והתפעלות השמחה דבינה נכלל בו בהעלם (והיינו כמו ונהרותם כשמן אוליך שגם ההשגה דבינה בבחי' ביטול החכ' נכללים בו כנ\"ל בענין ש' דשבת דביטול שמצד השגה דבינה נכלל בביטול דחכ') וביו\"ט להיפוך שהגילוי בהתפעלות השמחה והעונג בהעלם ונק' יחוד או\"א דאצי' עכ\"פ ולא שייך שם בחי' עבודה משא\"כ בחול או' עבדו את ה' בשמחה כו' שהשמחה בהשגה של עבודה להוליד המעשה כו' להיות שלמע' ג\"כ השמחה מלובשת בעשי' אבל שמחה דיו\"ט למע' הוא משמחה עליונה שבבינה שא' אם הבנים שמחה כו' וכן למטה וישמחו בך ישראל מקדשי שמך כו' כמ\"ש במ\"א (והטעם דמזמור לתודה בחול בא גם עונג דחכ' בגילוי משום דדוקא בחכ' עשית והעונג עיקר קיום כל העשי' שבחכ' כמשל המעיין בשכלו איך לצייר ולעשות שהעיקר של קיום השכל שבעשי' הוא גילוי העונג שבמעשה זו כו' ובשבת בא לידי גילוי עונג זה בעצמותו כמ\"ש וקראת לשבת עונג כו') ובמ\"א מבואר שהשמחה אינו רק גילוי עונג שבהעלם כמו שהשגה דבינה הוא גילוי ההעלם דחכ' והוא ענין עדן וגן כו'. ואינם ב' הפכים כי מהתפעלות הביטול יבא לגילוי התפעלות השמחה ובשבת עולין הנשמות לקבל מאור הנעלם דעדן שבחכ' וביו\"ט"],[2400650516,"להיפך שבא לידי גילוי בשמחה וכך יובן בחול באו\"א דיצירה רק שהוא בבחי' הקטנות דדבור שביצירה בשביל העשי' והיינו מזמור לתודה שבחול כו' וד\"ל. באו לפניו ברננה הנה מבואר במ\"א דשמחה בצפרא ורננה ברמשא כו' שהעבודה בשמחה הוא בהתחלת היום בעבודה שבלב בתפלה ובשמחה של מצוה כל היום כו' ולאחר תשלום העבודה בכלות היום דהיינו בלילה נק' רינה שהוא למעלה מן השמחה שבצפרא כי זהו שלימות השמחה לאחר תשלום כל העבודה כמשל אדם ששמח בכלות מעשיהו בכי טוב שאז מרנן דוקא בקול רינה כמו בא יבא ברינה כו' והוא הנק' שיר שעולה מעלה מעלה דהיינו בפנימי' ועצמי' התענוג שלמע' גם מעונג שבחכ' כו' וזהו באו לפניו ברננה לפניו ממש בפנימית הכת' שהוא פנימית עונה\"ע הפשוט כו' כמבואר במ\"א בפי' ביום השלישי יקימנו ונחי' לפניו ממש כו' ואחר העבודה בשמח' באו לפניו ברננה דוקא לפני שם הוי' דחכ' כו' וזה שייך בחול דוקא שאז זמן העבודה בבירורין דרפ\"ח דל\"ט מלאכות כו' כמ\"ש ששת ימים תעשה מלאכה כו' אבל במזמור שיר דיום השבת לא הזכיר רק הודאה ולא שמחה שהרי א' טוב להודות כו' ולא הזכיר עבודה בשמחה כלל כי אז רק בחי' עונג שבפנימי' ועצמו' כמ\"ש אז תתענג על הוי' כו' (והוא בבחי' פנימי' אבא שהוא פנימית ע\"י) והשמחה נכלל בו כנ\"ל אך להיות שהעונג שבשבת בא מסיבת העבודה בשמחה שבחול כמשל אדם ששובת ונח ממלאכתו שמתענג מטוב מלאכתו שעשה בשמחה דוקא וז\"ש כי שמחתני ה' בפעליך במעשי ידיך ארנן וקאי זה על ימוהמ\"ש שאז נא' עבדו את ה' בשמחה באו לפניו ברננה ושמחה ורננה זו שבחול מפעליך ומעשיך ע\"כ טוב להודות לה' בשבת וה\"ז כמו נתינת טעם לדבר למה טוב להודות כו' כי שמחתני כו' בחול וד\"ל. דעו כי ה' הוא האלקים מבואר למע' שהוא היחוד מיש האמיתי דהוי' ליש דאלקי' גימט' הטבע שבא בדעת והשגה כו' והיינו בחול דוקא וזהו הוא עשנו ולא אנחנו ול\"ו קרי להעלם עצמי' יש האמיתי ולא כ' שלא אנחנו היש והוא ההודאה שמודים אנחנו כו' כדעה עליונה שמיש לאין דכלא חשיב והיינו עמו וצאן מרעיתו כעבדים ביטול היש לאין כו' אבל בשבת טוב להודות לה' כו' בחי' עצמיות כבנים שאז יחוד פנימית דאו\"א להוליד נשמות כו' וכמ\"ש אות היא ביני ובין בני ישראל כו' וזהו טוב להודות בהודאה עצמיות מעצמיות התענוג כו' והוא בחי' נשמה יתירה שנק' נשמת כל חי כו' כמ\"ש בענין צדיק כתמר יפרח כו' למעלה וד\"ל:"],[2400650517,"<h3>באו שעריו בתודה</h3>\n(קמט) <b>באו</b> שעריו בתודה חצירותיו בתהלה. הנה תחלה אמר מזמור לתודה בבחי' הודאה דחכ' שנק' בחי' הוד דאבא והודאה זאת שא' בואו שעריו בתודה הוא בבחי' הוד דאימא שלמטה מבחי' הוד דאבא וזהו באו שעריו שהוא מלמט' למעלה שנכנסי' תחלה"],[2400650518,"בשערי הוד דבינה כו' וקאי אדסמיך לי' מ\"ש עבדו הוי' דחכ' בשמחה בגילוי התפעלות דשמחה כו' ואח\"כ באו שעריו פי' שעריו דבינה בהוד דאימא וזהו בתודה אבל מזמור לתודה דברישא דקרא מדבר בהודאה עליונה שבבחי' החכ' והוא מלמעלה למטה כו'. והנה להבין ביאור הדברי' הללו יש להקדי' תחלה בשרש ענין נו\"ן שערים דבינה למה הן מספר נו\"ן דווקא ומה הוא עיקר ענין נו\"ן שערים הללו דבינה בהיות ידוע שטעם מספר נו\"ן שערים היינו לפי שבחי' ה\"ח דאימא מתפשטין בחמשה מדות דבינה חג\"ת ונו\"ה שנק' מדות שבשכל והשגה עצמה כמו התפעלות אה' שבמוח הבינה בעודנה כלולה בעצם המושג שמשיג בטוב טעם הדבר שמיד באה התפעלות במוח ונק' שער כשער שיוצא בו ונפתח לחוץ כך התפעלות השכל במדות אהוי\"ר שבה עצמה נק' שערים דבינה כמ\"ש במ\"א. והעיקר של המדות בעצם הן חמשה חג\"ת ונו\"ה והיינו כמאמר דבינה עד הוד אתפשטת שנק' הוד דאימא ולא יותר כי בחי' יסוד שבבינה אינה מהות מדה עצמה רק בחי' גילוי שפע דמדות הללו מן המוח ללב כו' (והפי' האמיתי דבינה עד הוד אתפשטת היינו עד בחי' הוד דז\"א ולא עד יסוד ז\"א ולכך נק' יתום מאמו כמבואר במ\"א). והחמשה מדות הללו שבבינה כלולים כ\"א מי\"ס ע\"כ הן מספר חמשי' יו\"ד שערים דמדת חס' שבשכל והשג' עצמה ויו\"ד שערים דמד' גבו' וי\"ש דת\"ת וי\"ש דנצח עד י\"ש דהוד (והן חמשה חומשי תורה כידוע וס' דברים הוא בי\"ש דהוד שניתן למשה כו' וכמ\"ש במ\"א). והנה מבואר במ\"א בענין לך ה' הגדולה כו' עד כי כל כו' שכל ולך הן ג\"כ נש\"ב ובבחי' עליו' המדו' דבינה בחכ' שהוא בחי' אין של היש דהשגה דבינה כידוע אמר לך ה' הגדולה עד וההוד י\"ש דהוד דאימא ואח\"כ בירידת השפע מנש\"ב הללו במדות שבלב דז\"א דאצי' א' כי כל שהוא דרך בחי' יסוד דאימא שבו גילוי אור השפע דנש\"ב שכלולים בה\"ח עד יסוד שהוא מה' מדו' הללו וע\"כ נק' כל כו' דאחיד בשמי' וארעא שע\"י נמשך לגילוי מן ההעלם דבינה שנק' עלמא דאתכסייא כו' וכך יובן במ\"ש שאו שערים ראשיכם שהן חב\"ד דכל מדה ממדת שבבינה הנ\"ל. והנשאו כו' ויבא מלך הכבוד שהוא בחי' המשכ' גילוי אור אבא שנק' מלכא עילאה וכמבואר במ\"א באורך וגם כאן יובן בענין בואו שעריו כו' שביאה זו מלמטה למע' היינו עליות המדות שבלב למדו' שבשכל עד\"מ כמו התפעלות הלב שעולה ונכלל בהתפעלו' המוח וזהו הנק' ביאה וכניסה בשערים דבינה מלמטה למעלה כמו ע\"ד שעולין המדו' דבינ' בחכ' שנק' אין כנ\"ל דכך יתפרש לך ה' הגדולה כו' גם במדות שבלב שעולין למדות שבבינה שהן בהעלם כידוע וד\"ל. והנה זהו ההפרש בין עליות המדות מלמטה למעלה שפוגעין תחלה"],[2400650519,"בי\"ש האחרוני' דהוד דאימא וכנראה בחוש שתחילת עליות התפעלות המדות שבלב בשכל יכנסו תחלה בבחי' הודאה שמצד השכל והשגה כמשי\"ת ואח\"כ יכנסו במדות הגבוהי' ממנו דהיינו בנצח וחג\"ת דאימא כו' (ומכש\"כ בדרך ירידה והמשכה למטה דהיינו כשנש\"ב נמשכים מלמעלה שתחילה יומשך התפעלות הודאה שבמוח בלב ואח\"כ התפעלות אהוי\"ר שבמוח בלב). אבל בהמשכת אור אבא מלמע' למט' נכנס תחלה בי\"ש דחסד דבינה ואח\"כ בי\"ש דגבו' עד שבא בי\"ש דהוד דבינה באחרונה (וכמו ס' דברים שהוא בי\"ש דהוד בא באחרונה להיות תושב\"כ מח\"ע נפקת דאור אבא באימא שפוגע ונכנס בי\"ש דחסד תחלה שהוא ס' בראשית ואח\"כ ס' שמות כו' וכן מ\"ש ויבא מלך הכבוד הרי בא תחלה בי\"ש דחסד דבינה ובי\"ש דהוד בא באחרונה כדרך ההולך מלמעלה למטה וכן משה שזכה לבינה הרי שרשו בחכ' ונכנס בשע\"ב מלמע' למט' וזהו ההוד שניתן למשה כו' (ומ\"ש במ\"א בענין ולא ידע איש כו' דשער הנו\"ן זכה במותו אע\"פ ששער הנו\"ן ראשית כניסתו הוא מלמע' למט' כמ\"ש בזוה\"ק שנק' שביל דקיק דבי' עייל אבא לאימא כו' היינו משום דשרשו בדעת עליון דמזווג חכ' ובינה והוא שרש שעה\"נ שכולל כל השערים כו' ולמטה הוא בחי' דע\"ת וז\"ש ותחסרהו מעט מאלקים בחייו שלא זכה לשער הנו\"ן כו' וז\"ש משה זכה לבינה וממילא הרי הוא בדעת עליון שלמעלה מחו\"ב כמבוא' במ\"א). וזהו בואו שעריו בתודה פי' באו ממטה למעלה שיבואו ויכנסו בשער ההוד תחלה והיינו שא' בתודה דווקא שהוא בחי' הוד דאימא ואח\"כ נכנסין בשערי' דנצח וחג\"ת כו'. אבל מזמור לתודה הוא בבחי' הוד דאבא שהוא מלמעלה למטה כו'. וביאור ענין ההפרש שבין בחי' הוד דאימא ובין בחי' הוד דאבא הנה יובן מענין הנ\"ל במזמור לתודה בהודאה על הנס וכה\"ג שזהו בחי' ההודאה שנק' ביטול שלמעלה מן ההשגה וטעם לגמרי דהיינו בדבר מופלא מהשגתו שאין השכל מודה לזה כלל וכלל ואדרבה הוא נגד השכל דווקא רק אעפ\"כ מודה בהודאה שכן הוא ודאי כמו הודאה על הנס שהנס הוא היפך הטבע שהוא היפך השכל והשגה אנושית לגמרי ולא יודה כלל מצד ההשגה כי הרי הוא המנגד להשגה הטבעי' ועכ\"ז יודה באמת על הפלאה זו שנעשה מלמעלה מן הטבע שהאמת כן הוא כי כשהוא רואה הנס בעיניו יודה בע\"כ דגם שהשגחה אלקי' מופלא מן השכל וההשגה אבל ודאי יש מנהיג ומושל לשנות הטבע מהיפך להיפך כנראה לעין וזהו הנק' הודאה וביטול שלמעלה מן הטעם והשגה והוא בחי' הוד דאבא דהיינו בחי' הוד שבחכ' שהוא בבחי' אין שלמעלה מהשגה שנק' יש כנ\"ל. אבל"],[2400650520,"בחי' הוד דאימא הוא רק בחי' הודאה שלא באה רק מצד השכל והשגה וטעם דווקא כמו ההודאה במוח על היות התהוות הבריאה מאין ליש שבא בשכל וטוב טעם גם שאינו רואה בעיניו כמו שמשיג בחיי נפשו בגופו שנתאמת אצלו בשכל שהרוחני' דנפש הוא המחיה הגוף כך נתאמת אור החיות האלקי' בכל הנבראים בהשגת שכל ונק' הודאה במוח כידוע בענין מודים אנחנו לך כו' איך דכולא קמי' כלא וכאין כו' כמו אדם שיודה לחבירו בדבר ויכוח איזה סברא שהאמת אתו שהודאה זאת היא ע\"פ הכרת דעת ושכל הבא במושג דהיינו ששכלו נוטה לדעתו וסברת חבירו שהכיר בשכלו והשגתו דווקא שהאמת כדברי זולתו וא\"ל הי' שכלו ודעתו מכיר לא הי' מודה לו כלל וזהו הנק' הוד דאימא (והוד שבהוד הוא הודאה שבהודאה שיודה שצריך להודות כמו ע\"ה שיודה על ת\"ח מופלג כמבואר במ\"א שזהו הנק' מודים דרבנן ויש בו יותר ביטול מביטול הודאה דחכ' כו'). וזהו ההפרש בין הוד דאבא להוד דאימא. ואמנם באור החכ' הנק' אין וכח מ\"ה בעצם הרי בחי' הודאה שבחכ' אינו רק בחי' האחרונה מאחר שמתפעל ומתבטל בהודאה כמו על הנס וכה\"ג שהוא מפני הריחוק מעצם האין כו' ע\"כ יפול בו ענין הביטול כמו הנכנס בהיכל מלך מפני שלא ראה מעולם יפלא מחידוש הענין וכמ\"ש במ\"א ואעפ\"כ הוא למעלה מכל שערים דבינה שאינם רק התפעלות שמצד השגה שנק' יש וזהו ענין האור והגילוי מהעלם דחכ' בבינה מלמעלה למטה שבא בשערי דהוד דאימא באחרונה כנ\"ל. אבל מ\"ש באו שעריו כו' היינו ממטה למעלה ממדות שבלב להשגה שפוגע ונכנס בהוד דאימא תחלה מטעם הנ\"ל. וז\"ש באו שעריו בתודה בבחי' הוד דאימא ואח\"כ הודו לו בהוד דאבא (והוד שבמשיח כמבואר במ\"א) והוד דמשה בהוד דאבא לפי ששרשו של משה בנצח דאבא כו':"],[2400650521,"<h3>חצרותיו בתהלה</h3>\n(קנ) <b>חצרותיו</b> בתהלה. הנה ההפרש בין שעריו בתודה לחצרותיו בתהלה הנה ידוע שיש הפרש בין היכל לחצר שההיכל סגור בשערי' לא יכנוס רק ברשות והחצר פתוח לכל שיכולים הכל ליכנס שם ולעמוד ונק' שערי ההיכל פנימי' ושערי החצר חיצוני' ולזה כאשר אמר באו שעריו ר\"ל על שערי היכל הפנימי וחצירותיו בתהלה ר\"ל על שערי חצר חיצוני' וההפרש ביניהן למעלה הוא מובן עפ\"י הנ\"ל בענין שעריו בתודה שהן נש\"ב שכלולים בה\"ח דאימא כו' והן ה' מדות שבהשגה דבינה עצמה כנ\"ל. ונק' שעריו לשון נסתר דקאי בשערי בינה עצמו כמו שהמדות המה בבחי' העלם עומק המושג עצמו. אבל בחי' חצר הוא במדריגה שלמטה מנו\"ן ש\"ב והוא בבחי' מל' דבינה או מל' דתבונה שזהו רק בחי' אותיות ההשגה של המושכל כאשר מתצמצם"],[2400650522,"בכלי המוח באופן מוגבל ומיוחד בפרטי חלקים במח' שבמוח (הגם שנק' מחשבת שכל עדיין שלמעלה ממח' סתם באותיות המח' הנק' הרהור סתם שנק' בחי' לאה שמקבלת מאחוריי' דאימא שהוא מל' דתבונה או מל' דבינה דהיינו הנק' מח' עיוני' או מח' שכל כידוע הנה מ\"מ נק' גם הוא בשם מח' עכ\"פ רק שחושב במושכל זה והרי בא אור רוחני' השגת השכל זה במח' זו בגשם אותיות מח' הנתפס בכלי המוח (בל\"א וויא עס לייגט זיך דער שכל אין מוח און וויא עס פאר נעמט אין מוח כו'). ולמעלה יובן זה בהפרש שבין בינה לתבונה בכלל והוא ההפרש בין נש\"ב לבחי' מל' דבינה ותבונה והוא ההפרש בין שערי היכלו' דבינה לשערי החצר שהוא במל' דתבונה ששם יכולין הכל ליכנס כנ\"ל. וביאור ענין ההפרש הזה יובן מענין ההפרש שבין תודה לתהלה דבשערי בינ' הזכיר לשון תודה דווקא כמ\"ש באו שעריו בתודה אבל בבחי' חצרותיו שהוא בתבונה אמר חצרותיו בתהלה ולא בתודה והענין הוא כי הנה התהלה שהוא השבח הוא בא מצד כלי ההשגה המגבלת אופן השבח לכוון אל עצם הדבר כמו שהוא ממש בלי תוס' ובלי מגרעת שאם יגרע או יוסיף בשבח יפסיד יותר ממה שהשביח כי כאשר ישבחנו לאדון ומלך בדבר שאין בו גנאי יחשב לו אלא צריך שישבחנו באופן מוגבל לכווין מאד כפי אמיתתו בעצם לא יטה ימין ושמאל בסיפור שבחיו מכמו שהוא וא\"כ בהכרח שידע וישיג בכי טוב בהגבלת חלקיו שלא יטעה בו אפי' כקוש\"י בתוס' או במגרעת וזהו מצד כלי ההשגה הקולטין במוגבל ותפיסה והגשמה (כמו אור השכל הרוחני כשבא באותיות כלי המוח יוגבל באופניו לאמתתו יותר וכשבא לאותיות הדבור יוגבל לאמתתו יותר וכשבא באותיות הכתב יוגבל יותר ובזה יתרון מעלות הכלי המגביל יותר אך בתנאי שמיד שמאיר אור השכל יביאנו בכתב משא\"כ לאח\"ז לא יכווין לאמיתתו כמו שאין דנין בע\"ש משום אובנתא דליבא כמ\"ש במ\"א) אבל בפנימי' ההשגה כמו שהוא במופלא ממנו קצת עדיין מכלי הגבלת השגה שבמוח לא יוכל לכוון בפרטי אופני השבח כלל להיות כי הדבר מופלא קצת מערך כלי השגתו לא יוכל לכוון בשבח ותהלה כמו שהוא לאמתתו ע\"כ וודאי בהכרח שישתוק אז מלשבח ולהלל בדרך פרטי פרטיות רק יכלול כל פרטי השבח בהלל ושבח כללי דוקא בתכלית הקיצור לא בשבח ותהלה פרטי' כלל כענין לך דומיה תהלה פי' לך דומי' התהלה בפרט מצד קוצר המשיג בגדולותיו ונפלאותיו כי נבדל בערך מכלי השגה בשבחיו דרך פרט רק בדרך כלל לכלול כל התהלות (ואין הכוונה דומי' לגמרי שהרי נאמר יזמרך כבוד ולא ידום כו' רק שנסתם הפה וידום לספר באריכות כמו אגידה כו' עצמו מספר וכן מי ימלל גבורות ה' לגודל"],[2400650523,"עומקו וכו'). ובכ\"ז יובן למעלה בהפרש שבין שע\"ב שהן בעומק ההפלאה מכלי השגה במוגבל שם אינו רק בחי' ההודאה שהוא בא דרך כלל כאדם המודה על הפלאת ערך הגדול ממנו שהוא דרך כלל מפני שלא יוכל לבוא דרך פרט מקוצר המושג אך ורק בכללות המעלה בהפלאת ערכו יודה ע\"ז וזהו ההפרש בין הודאה לשבח שההודאה באה בכללי' עומק ההשגה היות הדבר נפלא מערכו (הגם שנק' הוד דאימא שהוא הודאה שמצד השגה דבינה דווקא כנ\"ל בהפרש שבין הוד דאימא להוד דאבא מ\"מ היא באה בכללות ההשגה שהוא תמצי' המכוון העולה מכל פרטי ההשגה שהוא עליון ורם ונשגב כו' רק שנלקח זה מן השגה דבינה ולא כהוד דאבא שנקרא הודא' וביטול שלמעלה מן ההשגה לגמרי כהודא' על הנס כנ\"ל) וכמו הפעם אודה את ה' אבל בבחי' מל' דתבונה הוא בבחינת השבח שבא דרך פרט לפי אופן הגבלת כלי ההשגה לכוון בכל חלקי פרטיו לא יוסיף ולא יגרע וז\"ש שעריו בתודה ולא תהלה ששם נאמר לך דומי' תהלה רק הודא' בלבד כנ\"ל. אבל חצרותיו במל' דתבונה ובינה בתהלה ושבח דרך פרט דוקא וד\"ל. ובזה יובן מ\"ש בזוה\"ק ע\"פ נודע בשערים בעלה באינון תרעין כו' כ\"ח לפום מה דמשער בלבי' כו' דאית תרעין עילאין שהן נש\"ב וע\"ז נאמר שאו שערים ראשיכם כו' שהן בבחינת ההעלם דבינה בפתחי שערי היכל פנימה שלא יכנסו הכל רק רואי פני המלך כו' ושם אין התהלה ושבח מגיע בפרט כנ\"ל רק ההודא' בלבד כמ\"ש באו שעריו בתוד' דוקא כנ\"ל ואי' תרעין תתאין שהן שערי החצר החיצונה דמל' דבינה ותבונה הנ\"ל ששם השבח והתהלה מגיע כמ\"ש חצרותיו בתהלה דוקא עז\"א נודע בשערים בעלה פי' נודע בגילוי הגבלת כלי ההשגה דרך פרטי פרטיות בכ\"ח לפום מה דמשער ממש במוחו ולבו וכמ\"ש בזוהר פ' אמור ע\"פ ובט\"ו יום כו' דבי' מלכא בתרעא יתיב כלו' כשהמלך רוצה לבוא בגילוי לעין כל הולך לחצר גינת הביתן ונקרא חצר החיצונה ועומד או יושב בשער החצר החיצונה שיראוהו כל ההמון כך למעל' גילוי אוא\"ס בחו\"ב דאצי' עדיין הוא בהעלם כו' גם בנש\"ב כנ\"ל רק במל' דבינה ותבונה שם בא לידי גילוי בכל חד לפום שיעורא דמשער כו' וזהו נודע בשערים בעלה בחי' ז\"א שבו מוחין דאו\"א דאצי' נודע בתרעין תתאין במל' דאצי' שמקבלת ממל' דתבונה כידוע בענין ד' רבתי דאחד שהוא ענין קשר של תפילין של ראש בחי' לאה שמקבלת ממל' דתבונה כמבואר במ\"א וד\"ל. והיינו ההפרש ג\"כ בשאו שערים ראשיכם הראשון שאמר מי זה מלך הכבוד משום דאוא\"ס שבאו\"א שנקרא מלך הכבוד גנוז בהיכלא דאימא כו' אבל בשאו שערים ראשיכם הב' אמר ה' צבאות הוא מלך הכבוד כו' שהוא בחינת אוא\"ס"],[2400650524,"שבחו\"ב דאצי' שבא במל' דתבונה עד מל' דאצי' שנקרא תרעין תתאין כו' כמ\"ש ברוך הוי' כו' מן העולם ועד העולם מבחינת עלמא דאתכסייא דבינה לעלמא דאתגליי' למל' והיינו ב' ההי\"ן דשם הוי' כידוע בפי' לך ה' הגדולה והיינו שעריו בתוד' חצרותיו בתהלה ונקרא תהלה לדוד דוקא שהוא בחינת המל' מטעם הנ\"ל וד\"ל:"],[2400650525,"<h3>הודו לו ברכו שמו</h3>\n(קנא) <b>הודו</b> לו ברכו שמו הנה אחר שדיבר בב' מיני הוד דאו\"א הנ\"ל שזהו מלמעל' למטה בהוד דאבא ומלמטה למעלה בהוד דאימא כנ\"ל בפי' באו שעריו בתודה מלמט' למעל' ומ\"ש מזמור לתודה הוא מלמע' למטה עתה מדבר בהוד העליון הכולל שניהם יחד וכנ\"ל בפי' אל דעות ה' שיש ב' דעות ד\"ע וד\"ת דמשפיע ומקבל ואל דעות כוללן יחד כו' כך יובן בבחי' ההודא' ששרש ההודא' הוא הביטול ויש ביטול הבא מצד השגה דוקא כענין מודים אנחנו לך כו' בהשגה מלמטה למעל' דקמי' כלא כו' כד\"ע ביש האמיתי לאין כו' ויש ביטול והודא' דחכ' שלמעלה מן ההשגה לגמרי כו' שזהו מצד גילוי אור המשפיע כמו שהוא מלמעלה למטה ולא מצד ההשגה כו' אך כ\"ז רק בבחי' ההשפעה דמשפיע ומקבל אבל בבחי' העצמות ממש כמו שהוא טרם שנקרא משפיע מיש לאין ג\"כ כו' הוא מ\"ש הודו לו לעצמותו ממש והודאה זו היא למעלה גם מבחי' הודאה וביטול דחכ' כח מ\"ה שיש מי שבטל עכ\"פ כו' ויש בו שיעור ומדה לפ\"ע ושיעור הכח מ\"ה שאינו שוה בכולם (כמו הביטול דחכמ' דעשי' למטה מביטול חכ' דיצירה כו' כמשל בבחי' חכ' דאדם חכם גדול שמתבטל בעצמו יותר כמשה שאמר ונחנו מ\"ה וגם מי שאינו רק בבחי' נפש דעשי' מחיצוני' הכלים דנה\"י דז\"א ג\"כ יש בו בחי' מ\"ה דחכ' כמ\"ש כי אתה אבינו וכתיב ת\"ר אלף רגלי העם אשר אנכי בקרבו שכוללם יחד וכמ\"ש במ\"א) אבל ביטול והודאה העצמי' דרצון ותענוג העצמי הוא הנק' ביטול העצמות ממש מצד בחי' עצמות הנפש דוקא ולא מצד בחי' כח מ\"ה שבנפש כמו על כל דיבור פ\"נ כו' וכמו ביטול העצמי דבע\"ת בחילא יתיר כו' מצד בחי' יחידה העצמי' כמו בר\"ה ויו\"כ וכמו\"כ בצדיקי' הגדולים כרשב\"י שא' בחד קטירא כו' (וכמו שמבואר במ\"א שזהו בחי' הוד דע\"י שהוא בחינת חוטמא כמ\"ש במשיח והריחו ביראת כו' וכמ\"ש ותהלתי אחטם לך וכמו שנאמר לך דומי' תהלה לגמרי בדומי' ושתיקה להיותו למעלה גם מבחי' מ\"ה דחכ' רק ביטול העצמי) ולמעלה הרי מגיע בזה לבחי' העצמיות ממש שהוא עצם הרצון שבעצמות שלמע' מהרצון והתענוג שבחכ' כו' וז\"ש הודו לו ממש בהודא' שלמעלה מן הטעם שברצון ג\"כ אלא ביטול והודאה עצמי' מבחי' כל העצמות וזהו ברכו שמו סתם שהוא שמו"],[2400650526,"הגדול בחי' רדכ\"ר בחי' הרצון והתעה\"פ העצמי' שבעצמותו ממש שיתברך מלמעלה למטה כו' שלא מצד אתעדל\"ת והעלא' מ\"ן דשבח ותהלה או הודאה דחו\"ב כלל וזהו ענין הודו לו שכולל לב' הודאות דאו\"א דהודו ב' הודאות משמע והם ב' מיני הוד דאו\"א מלמעלה למטה ומלמטה למעלה שזהו רק הכנה לבחי' הודאה העצמי' כדי שיתברך שמו העצמי בחי' מל' דא\"ס שבפנימי' הכ' כו' וד\"ל. כי טוב ה' לעולם חסדו כו' פי' כי דרך כלל נחלק ענין ההודאה בב' ענינים הא' ההודאה שמתיחסת עם ענין השבח והתהלה בלבד כי השבח והתהלה באין דרך פרט והודאה עם השבח כמו הפעם אודה כו' וטוב להודות כו' וכה\"ג והוא הכולל כל מיני שבח בפרט והוא תמצית העולה מכל השבחים ונק' הודאה להודות לעצם הכולל כל השבחים באדם שיודה בהודאה על שבח מעלת חכ' אדם ושבח מעלת מדותיו בד\"פ וכה\"ג וזהו רוב ענין ההודאה הנזכר בכתובים כמו גם אני אודך כו' וכן להודות ולזמר כו' ששייך הכל לענין השיר והשבח דוקא אך ענין הב' בהודאה הוא שאינו שייך לשבח ומעלה בעצם כלל רק בחי' ההודאה על הטוב והחסד שעשה עמו כמו ד' צריכין להודות על טוב וחסד שעשה ה' עמהם בהצלתם מן המות וכה\"ג על אודות הטוב וחסד ברב שפע וברכה והצלחה שלא כדרך הטבע כלל שמברך ומודה על הטוב הזה בבחי' הודאה דוקא כידוע שזהו הנקרא הודאה וברכה והצלחה שמתייחסת בחי' הודאה זו עם הברכה שמברך לבעל השפע המשפיע הטוב הזה ולא שייך הודאה זו לענין השבח ונמצא שיש ב' מיני הודאה הא' ההודאה והשבח והב' הודאה וברכה (ומבואר במ\"א בענין הלל ברכה והודאה שבסדר התפילה הלל בשבחי' דפסד\"ז וברכה בברכות ק\"ש עד ש\"ע ובש\"ע בחי' הודאה עליונה מפסוד\"ז והרי הודאה שבש\"ע הוא בחי' הודאה עצמי' הנ\"ל שמזה מסתעף ברכה דש\"ע כמ\"ש במ\"א בפי' הודאה בחולם שתמיד יודו דהגם שזהו הודאה ושבח אבל תמידית ההודאה מורה על בחי' ביטול והודאה עצמית הנ\"ל וכן ענין הפעם אודה כו' שבש\"ע נמצא הודאה עצמית הנ\"ל שכולל ב' מיני הודאה ושבח הודא' וברכ' כו' וד\"ל) וזהו הודו לו ברכו שמו שמהודאה עליונה העצמי' שלמעלה מהשבח ותהלה בפרט כנ\"ל נמשך הברכ' ממקור הראשון והוא בחי' הודא' הב' כמו ההודא' על הטוב וחסד שנקרא הודא' וברכ' כנ\"ל וז\"ש הודו לו ברכו שמו אחר הודא' זו שייך הברכה דוקא וזהו שמפרש בנתינת טעם בפסוק זה שלאחריו כי טוב ה' לעולם חסדו. פי' למה הודו לו בהודאה עליונה הנ\"ל משום כי טוב ה' ברוב טובו העצמי' ע\"כ בחי' ההודאה זו על עצם רב טובו אשר לעולם חסדו בלי הפסק כלל שזהו מורה על"],[2400650527,"בחי' עצם הטוב שהוא בלתי מוגבל בעצם ע\"כ רב טובו בלי שינוי כלל שלא באמצעות אתעדל\"ת כלל (והוא ההפרש בין הודאה עצמה שעל הטוב בין על הטוב והחסד הבא בפרט להודאה על עצם הטוב כי חפץ חסד וטוב כמו בבחי' טבע הטוב להטיב כידוע וד\"ל). ועד דור ודור אמונתו. דהנה כתי' חדשים לבקרים רבה אמונתך והיינו ע\"י בחי' חסד דאברהם שמאיר בכל יום (כמ\"ש למעלה בפי' אמונתך בלילות) אבל זה רק בוקר דאברהם שאינו רק כפי אתעדל\"ת כמ\"ש יהי חסדך ה' עלינו כאשר יחלנו לך אבל בוקר דיוסף שהוא רק החסד מצד עצם הטוב להיטיב אין לו שיעור והפסק מדור דור וז\"ש עד דור ודור אמונתו שאין בה שינוי מצד אתעדל\"ת אלא בכדו\"ד אמונתו והוא משום דטוב ה' לעולם חסדו בלי הפסק מטעם הנ\"ל ע\"כ עדו\"ד אמונתו דאמונה הוא בחי' מל' כשאין הפסק בשפע וביטול אור האלקי בבי\"ע כידוע בפי' דאמת ואמונה דאיהו אמת ואיהי אמונה אך כתי' וצדיק באמונתו יחי' קאי על בחי' צ\"ע בחי' יסוד דז\"א בחי' בוקר דיוסף הנ\"ל באמונתו יחי' היינו בבחינת כתר שנקרא נאמן כידוע בענין האל הנאמן מפני שהוא בבחי' קו האמצעי דת\"י שעולה עד פנימי' הכתר שלמעלה מהתחלקות קווין כו' ששם נאמר וגם נצח ישראל כו' לא אדם הוא להנחם וכמבואר במ\"א בענין רמה קרני כו'. וזהו באמונתו יחי' ומשם משפיע למל' ונק' אמונה לשון נוק' כמבו' במ\"א בפי' עצות מרחוק דוקא אמונה אומן וכמו ויהי אומן את הדסה וזהו ג\"כ עד דו\"ד שבבחי' המל' אמונתו דצ\"ע והיינו בבחי' אמת ראש תוך סוף כענין פועל אמת שפעולתו אמת וזהו אמת ואמונה כ\"ז וקיים כו' וד\"ל:"],[2400650528,"<h3>יהי כבוד</h3>\n(קנב) <b>יהי</b> כבוד ה' לעולם כו'. הנה מבואר בספרי האריז\"ל דמזמור לתודה בבחי' או\"א דיצירה ויהי כבוד הוא בבחי' ז\"א דיצירה ותהלה לדוד הוא בבחי' כתר מל' דיצירה וארז\"ל דיהי כבוד שרו של עולם אמרו שהוא בחי' מט\"ט דיצי' שהוא מרכבה לבחי' ז\"א דיצירה כו' ולכך יש בפסוקים דיהי כבוד מספר ח\"י פסוקים ובכל פסוק מוזכר שם הוי' שהן ח\"י הויות נגד ח\"י עלמין גימט' ט\"ט דמט\"ט שכלול מט\"ס דאו\"י ואו\"ח ט\"ס פנימי' ומקיפים להשפיע למל' שנקרא חקל תפוחין ולכך יש בו קל\"ז תיבות וקל\"ח עם הכולל וכ\"ב אתוון דתהלה לדוד שהוא בחי' כתר דנוק' דיציר' כלולים בו ולכך תהלה לדוד מיד אחר יהי כבוד ואין לשנות נוסח זה דיהי כבוד בין בחול בין בשבת ואין הפסק ביניהם גם בשבת וגם יש לכוון בח\"י פסוקים הללו נגד וי\"ו צירופים דשם שד\"י שבבחי' כלים אמצעיים דז\"א דיצירה שהן ח\"י אותיות נגד ח\"י עלמין דיסוד ז\"א דיצירה וכו' ע\"ש. והנה להבין כללות הענין יש להבין תחלה ביאור ענין דבחי' מט\"ט"],[2400650529,"שנק' שרו של עולם בכלל והוא כמבואר במ\"א מארז\"ל ע\"פ רכב אלקים רבותיים אלפי שנאן כו' שהקב\"ה בלילה רוכב על כרוב קל שלו ושט בח\"י אלף עלמין כו' וחסר ב' אלפים מרבותיים כו' וזה שנאן אל תקרי שנאן אלא שאינן כי הנה ידוע בי\"ב שעות היום הן י\"ב צירופי הוי' דז\"א דאצי' וז\"ש י\"ב שעות הוי היום שהוא בחי' החסדים דז\"א כמ\"ש יומם יצוה ה' חסדו כי חסד אל כל היום כידוע ג\"ש ראשונות יושב ועוסק בתורה כו' עד ג' שעות יושב וזן היינו בחי' חב\"ד חג\"ת נה\"י דז\"א ובלילה מאי עביד רוכב כו' דבלילה הוא בחי' י\"ב צירופי אד' בחי' המל' כידוע והקב\"ה שהוא בחי' ז\"א דאצי' רוכב על כרוב קל שהוא בחי' מט\"ט דיצי' שהוא אנפי זוטרי שנקרא כרוב כרביא שהוא בחי' קטנות המוחין שבבחי' שם שדי יסוד ז\"א דאצי' ושט בח\"י אלף עולמות שהן ח\"י עלמין וכלול כל א' מאלף וזהו רכב אלקים רבותיים פי' אלקים הוא בחי' קטנות דשם הוי' שהוא ז\"א דאצי' ורכב אלקים רבותיים הוא כרוב קל בחי' דקטנות דיסוד ז\"א דאצי' ששט בו. וביאור כל זה הנה י\"ל בשרש ענין קטנות וגדלות דז\"א דאצי' בהיות ידוע בבחי' ז\"א דאצי' שהוא בבחי' המדות דאצי' חג\"ת נה\"י שמאיר בהן המוחין דחו\"ב בגילוי כמו מדות שבלב האדם למטה שמאיר בהן מבחי' השכל והטעם שבמוחין דחו\"ב באהבה בלב שמאיר בה גילוי השכל נקרא מושכל חב\"ד שבמדות ועצם המדות הוא חג\"ת הוא בחי' מורגש ובחי' השפעתם למקבל נקרא נה\"י בחי' מוטבע והוא בחי' הקטנות של המוחין במדות כמבואר במ\"א וכ\"ז הוא למעלה באדם העליון דאצי' שהוא שם הוי' דז\"א והיינו מ\"ש י\"ב שעות הוי היום כנ\"ל עד יושב וזן שהוא בחי' נה\"י דז\"א דאצי' (ובשעה הד' יושב ומשחק עם לויתן כו' וכמבואר במ\"א) אך בלילה שהוא בחי' המל' י\"ב צירופי אד' הוא המקבל ממדות שבלב דז\"א כמשל המדות שבלב שנמשך למחדו\"מ שהן ג' עולמות דבי\"ע שכלולים במל' והיינו שא' רוכב על כרוב קל שלו כו' שהוא בחי' מט\"ט כנ\"ל. והענין הוא דבחי' מדות דאצי' כשבאין לבחינת מחשבה שהוא נבדל מעצם המדות שבלב נקרא ז\"א דבריא' וכשיורדי' המדות שבמח' לדיבור בפה נקרא ז\"א דיצירה כידוע ע\"כ יש ב' מדריגות גם במט\"ט שהוא עומד בחיצוני' הכלים דז\"א דבריאה ויצירה (ומט\"ט דבריאה נקרא מיט\"ט ביו\"ד מפני הארות אור אבא בגדלות המוחין דחו\"ב שבא קצה הארתו במח' ממל' דתבונה כידוע בבחי' ד' רבתי דאחד כו') וזהו הנני שולח מלאכי שהוא מט\"ט דבריאה כי שם הוי' דאצי' בקרבו בקטנות דמח' ומפני שהדיני' גוברים בו בקפידא דמח' בחי' לאה ע\"כ הזהיר אל תמר בו כו' וזהו ששמו כשם רבו ממש וכמ\"ש במ\"א. והנה בלילה הוא בחי' עליות המל' שעולה עד"],[2400650530,"בחי' ז\"א שהוא בחי' המדות ולכך הקב\"ה שהוא ז\"א דאצילות שמלובש בקטנות במחו\"ד רוכב על כרוב קל שהוא חיצוני' הכלים דמדות דמח' כו' והוא בחי' מט\"ט דבריאה ויצי' כמשל הישן שמחשבתו עולה עם המדות שבלב למעלה בשכל והשכל עולה ברצון שלמעלה מן השכל עד בחי' עצמות הנפש שכל הכוחות כלולים בה כו' וזהו ששט בח\"י אלף עלמין שבבחי' הכתר שהן בבחי' אלפי\"ם כמ\"ש במ\"א באריכות וזהו בבחי' העלאה מלמטה למעלה עד\"מ מי שטרוד בענין עמוק שעולה צמצום כלי מחשבתו עם המדות שבלב למעלה מעלה עד מקור הראשון ההיולי העצמי ומחמת זה חוזר ונמשך אור חדש בבחי' מוחין חדשים ממקור הא' בכח\"ב ומשם למדות שבלב כו' כך ע\"י מדת לילה בעליות המדות שהוא מ\"ש רוכב על כרוב קל דקטנות דמדות שבמחשבה ולב כו' מזה נמשך אח\"כ בי\"ב שעות היום ממקור הא' בג\"ר דז\"א וזהו בחי' ג' מדריגות דחב\"ד חג\"ת כו' שביום נמשך בבחי' החסדים מגבוה לנמוך כמ\"ש כי חסד אל כל היום דרוח אייתי רוח ואמשיך רוח כו' (וכמארז\"ל גבי עסק התורה בלילה ע\"פ ובלילה שירה עמי דחוט של חסד נמשך ביום וכמ\"ש במ\"א ע\"פ השמיעני את קולך כו' דלא אברי ליליא אלא לגירסא כו') והנה במזמור זה דיהי כבוד מדבר בבחי' ההמשכה דמדות דז\"א דאצי' מלמעל' למט' בבחי' המל' והוא ע\"י זקן ביתו בחי' מט\"ט שנק' שרו של עולם הבריאה בכלל והוא בחי' כלים החיצוני' דמדות (כי ג' מיני כלים הן פנימי' ואמצעי וחיצון נגד ט\"ס חב\"ד חג\"ת כו' והן ג' מיני אותיות דמחודו\"מ וחיצוני' הכלים בחי' מט\"ט שהן אותיות דמעשה שבמדות דבמח' הנק' ז\"א דבריאה שבו שם הוי' דז\"א כנ\"ל) וז\"ש נער הייתי גם זקנתי שרו של עולם אמרו נער בקטנות דמדות דאצי' וזקנתי וכן עבדו זקן ביתו שנעשה שרו של עולם הבריאה בבחי' גדלות המוחין לגבי בחי' המל' דבריאה כו' שכולל למלך מלך ימלוך דבריאה ויצי' כו' אבל קמי' דקוב\"ה ממש שהוא בחי' ז\"א דאצי' שמתאחד במח' עצמה עדיין ואינו נבדל לחוץ לבחי' המל' מי איכא זקנה קמי' דצופה ומביט במחשבה א' כו' כמ\"ש במ\"א ולהיות כי יש ב' מדרגות במט\"ט בב' מיני מדות במח' ודבור ועיקר הגילוי לחוץ מן העצמות הוא ממח' לדבר דוקא כמשל דבר מלך שגוזר ואומר בדבור ממדות שבמח' ולבו כו' לזה א' בסידור דיהי כבוד הוי' דמדות דאצי' שבאין לגילוי גמור לעולם הנפרד הוא בבחי' ז\"א דיצי' דוקא שמתלבש בחיצוני' הכלי' דדבור שהוא בחי' האותיות דמעשה שבדבור שמצוה לעשות דוקא כמו ויאמר אלקים יהי רקיע כמ\"ש במ\"א וזהו בחי' מט\"ט דיצירה שהוא בחיצוני' הכלים דז\"א דיצירה ולכך יש לסמוך מזמור זה דיהי כבוד מיד אחר מזמור לתודה שהוא בבחי' או\"א"],[2400650531,"דיצירה כנ\"ל הטעם וד\"ל. ומעתה יש להבין במ\"ש בסידור בפי' מט\"ט ב' טתי\"ן ב\"פ ט\"ט מתתא לעילא ומעילא לתתא שהן ח\"י עלמין דבחי' צדיק יסוד ז\"א דקטנות שהוא שם שדי כידוע כי הנה בחי' הקטנות שבמדות שבלב יש בו מעלה וחסרון החסרון מה שהוא בתכלית קטנות המוחין ע\"כ מסתעף בו הדינים והצמצומים מאד (כמ\"ש במ\"א בענין נחש הנחושת דמשה כו' שנק' חויא דרבנן כו') ומבואר במ\"א בענין חש\"ן אותיות נח\"ש שהוא קטנות דיסוד כו' שמזה נמשך גבורות קשות דנחש הקדמוני כו' והיינו בא נחש על חוה בחי' אחוריים דשם שדי כו' כמשל התינוק שמפני קטנות דעתו במדותיו מאד יקפיד בקל עד שיהי' כמו אכזרי כו' וכל שהמוחין בהרחבה במדות יסתעף ריבוי החסדים כמ\"ש במ\"א וזהו שנקרא כרוב כרביא אנפי זוטרי כו' וזהו ונתתי נערים שריהם כו' וכן אי לך ארץ שמלכך נער כו' והמעלה הוא מה שמבחי' קטנות וצמצום ומיצר זה יבא לכלל בחי' תכלית גדלות בהרחבה גם בכח\"ב שבמדות כו'. ויובן זה ממה שאנו רואים למטה באדם התחתון כאשר לבו ומחשבתו מתצמצם מאד בתכלי' המיצר והדוחק עד כלות אורם הפנימי' לגמרי ולא נשאר רק בחי' היותר מצומצם שהוא תכלית הקטנות שבהם אז דוקא יגרום להמשיך ממקור השכל תוס' אור חדש בעילוי רב שלא הי' נמשך כלל כפי ערך עצם המדרגה בחי' כח ואור שכלו רק דוקא ע\"י צמצום ודוחק כלי מחשבתו ולבו כמו בהתקשרותו מאד מאד במחשבתו ולבו באיזה דבר עיון שלא יכיל כלי חכ' מעצמו להשיגו כתלמיד היושב ושומע דבר עמוק מאד מרבו שמתצמצם אז כל פנימי' כלי מחשבתו מפני שכל לבבו מתקשר היטב ונעשה אז בחי' המדות שבלב ומוח בתכלית הקטנות והצמצום והמיצר (והוא נק' קטנות דיסוד ז\"א) עי\"ז יבא לבחי' עמקות ומרחב המח' שבאותו עיון בגדלות אח\"כ כי דוקא המיצר שבתחלה הוא שגורם המרחב לפ\"ע (כמשל הזורק לגובה שתלוי לפ\"ע השפלתו לאחור בקלע שבידו שנק' עומק תחת שעולה לעומק רום כמ\"ש במ\"א) וזהו לקנות חכמה ולב אין דהיינו ע\"י התקשרות וצמצום הלב ומוח שגורם לקנות חכ' ממקור החכ' כמשל זקן שקנה חכ' קנה חכ' כו' מאור הכתר וכמ\"ש והחכ' מאין תמצא כידוע (וכמ\"ש אין אדם עומד על דבר הלכה אא\"כ נכשל בה בבלתי הבנה תחלה שנק' קשה ההבנה ביותר שמצמצם כלי הקרום של מוחו בקשיות שבו דוקא יבא להמשיך תוס' אור ממקור החכ' שלמע' מן הקרום שבמוח כו') וזהו כל תלמיד שאין שפתותיו נוטפות מור כו' וכמ\"ש במ\"א. ולהיות שהעלאה זו רק בשביל ההמשכה וירידה אח\"כ על כן בחי' קטנות זו בבחי' התכללות דאו\"י ואו\"ח כי מיד הרי נמשך ממקור הראשון בבחי' או\"י רק שבא מכחו של או\"ח שהוא בחי'"],[2400650532,"הצמצום והמיצר דהעלאה בהתקשרות וצמצום כלי המוח והלב כנ\"ל. והנמשל מזה יובן למע' בבחי' קטנות דיסוד ז\"א דיצירה עם בחי' קטנות דיסוד ז\"א דבריאה שהיא עולה בבחי' העלאה במיצר אע\"פ שיש בו חסרון אז לגבי המקבלים מצד ריבוי הדיני' מטעם הנ\"ל. אבל יש בו מעלה יתירה בבחי' ההעלאה מהמיצר כזה שגורם בחי' תוס' אורות ומוחין חדשים ממקור הראשון דפנימי' הכתר בחו\"ב שבמדות כו' והיינו בכלל רוכב על כרוב קל שלו בלילה בחי' קטנות דז\"א דבריאה ויצירה כנ\"ל שגורם ריבוי הארת מוחין בג\"ר דז\"א דאצי' אח\"כ כנ\"ל ובדרך פרט הרי לטעם זה נק' מט\"ט נגד ב\"פ ט\"ס דאו\"י ואו\"ח מתתא לעילא בחי' העלאה דמיצר שגורם המשכה מעילא לתתא לפ\"ע כנ\"ל והוא בחי' ח\"י עלמין דבחי' יסוד ז\"א דקטנות שהוא בבחי' שם שדי וזהו שמבואר בסידור בכללות ענין דח\"י פסוקים דיהי כבוד שהן וי\"ו צירופים דשד\"י דקטנות שהן ח\"י אותיות ובכל א' יש שם הוי' דגדלות דז\"א לפי שמ\"ש יהי כבוד לשון עתיד ר\"ל שעתיד להגלות מלמעל' למטה כמשי\"ת בסמוך. ואמנם מ\"ש יהי לשון ציווי וגם לשון ברכה שיהי' כבוד הוי' בגילוי לעולם שהרי בא כח גילוי אור זה מצד בחינת ההעלאה דבחי' ז\"א דקטנות שהוא שם שדי כו' ולכך בדידי' תלי' מלתא וז\"ש יהי כבוד כו' והיינו בש\"ע בח\"י ברכאן דהיינו בחי' גילוי אורות דהוי' דז\"א דאצי' במל' כידוע. וז\"ש דיהי כבוד שרו של עולם אמרו להיות כבוד הוי' דז\"א מאיר בבחי' ההמשכה לעולם כו' והוא מ\"ש בסידור דתהלה לדוד כולל כ\"ב אתוון דמל' שהוא מל' דבריאה ויצירה הוא בחי' מל' דוד. וזהו תהלה לדוד שאחר יהי כבוד מיד ואין להפסיק ביניהם משום דמז\"א נמשך כתר דנוק' וכמ\"ש בע\"ח ע\"פ לעולם ה' דברך נצב בשמים דכתר דנוק' מקבל מחזה דז\"א ששם הוא קטנות דיסוד ז\"א כו' ומ\"ש עוד דלכך אין לשנות בנוסח זה דיהי כבוד בין בשבת ובין בחול היינו משום דגם בשבת צריך העלאה דמיצר הזה בשביל בחי' גדלות המוחין דפנימי' ג\"ר במדות כמו בחול בשביל מוחין דקטנות דחו\"ב שבמדות כו' וד\"ל:\n(קנג) <b>ומעתה</b> יש להבין בביאור פרטי פי' המלות דיהי כבוד כו'. דהנה מבואר בסידור בכללות המכוון בח\"י פסוקים הללו והוא להאיר בבחי' הכתר דמל' דיצירה שהוא ענין כ\"ב אתוון דתהלה לדוד שאח\"כ ולכך אמר יהי כבוד לשון צווי או בקשה על זולתו דהיינו מ\"ש יהי כבוד הוי' דז\"א במל' שנק' עולם בכלל ואם לא הארת כבוד הוי' דז\"א אינו נק' מלך לעולם שזהו בחי' כתר מל' וז\"ש יהי כבוד כו' וע\"ד המבואר במ\"א בענין יברכך הוי' כו' שהוא ענין ציווי וכמו ויתן לך האלקים כאן או' ל' בקשה כו' וגם הוא ענין בקשת ברכה ג\"כ"],[2400650533,"שמברך שיהי' כבוד הוי' לעולם כמו יברכך ה' ברוך ה' כו' ומ\"ש בסמוך יהי שם ה' מבורך קאי ע\"ש הוי' עצמו שיהי' מבורך (כמשי\"ת). והענין ידוע דבחי' ת\"ת דז\"א נעשה כתר למל' והוא הנק' כבוד ה' דוקא דשם הוי' בת\"ת והוא ענין הרצון שבמדות שבלב לבחי' המלוכה שהרצון הבא בגילוי למדת המלוכה נק' כתר מל' (כידוע בענין עלה במח' תחלה אנא אמלוך שהוא הרצון כו') ובחי' מקור לרצון גילוי זה במדות שבלב הוא בבחי' ת\"ת דז\"א ודוקא בשליש האחרון דת\"ת בחי' נה\"י דחזה כו' שזהו נק' כבוד כידוע דהת\"ת בעצם הוא בת\"ת שכלול מחו\"ג מצ\"ע וכאשר הוא מפואר בבחי' התפשטות לזולתו הוא נק' יקרא דמלכא שהוא תרגום דכבוד ומזה נעשה כתר מל' ואין זה רק חלק נבדל מעצם מדת הת\"ת והוא רק מה שמאיר לבחי' ת\"ת שבמדת המל' שמחמתו נעשה הרצון למלוכה וזהו בחי' נה\"י שבו בלבד הוא שנק' כבוד הוי' לעולם (וכמ\"ש במ\"א בענין מפואר במלופו\"ם ומפואר בחול\"ם עד שאמר כל שתפארת לעושיה ותפארת לו מן האדם הרי יש ב' מיני ת\"ת ת\"ת שבעצם שמאיר להיות רצון בת\"ת שבבחי' המל' ותפארת לו מן האדם שנקרא כבוד מל' הרי הוא בחי' התנשאות על זולתו שנק' כתר מל' כמו ותלבש אסתר מל' וכן ה' מלך גאות לבש כידוע וזהו דבחי' ת\"ת דז\"א שנק' תפארת לעושיה נעשה כתר מל' שנק' תפארת לו מן האדם) וז\"ש יהי כבוד ה' לעולם פי' שיתגלה זיו כבוד ה' הנק' יקרא דמלכא והוא חיצוני' כלי הת\"ת לעולם שהוא לבחי' מלך עולם בכבוד התחתון דכתר מלכות וזהו מי הוא זה מלך הכבוד ה' צבאות כו' שהוא כבוד עליון דז\"א שמאיר בכבוד התחתון דמלכות וכמ\"ש למען יזמרך כבוד כו' וכמ\"ש בזהר והיינו ענין כבוד אלקים הסתר דבר שהוא כבוד דמל' שנק' אלקים שהוא מלך מרומם ומתנשא בהסתר בחי' סובב כו' וכבוד מלכים כבוד עליון דז\"א חקור דבר שבא בגילוי להיות שרשו בבחי' חסדים דשם הוי' להמתיק לגבורות דמל' שנק' אלקים וכידוע בענין כ\"ו כל\"ח שהוא ניצוצי החסדים דהוי' דז\"א שמאירים במל' שנק' אלקים וכמו לע\"ל דכתיב ונגלה כבוד הוי' כו' ולכך אנו אומרים ברוך כבוד הוי' ממקומו דוקא וכן ברוך ה' מן העולם וכה\"ג אמר יעקב והי' הוי' לי לאלקים כו' ולכך כבוד מלכים חקור דבר שיבא מן ההעלם לגילוי דוקא וז\"ש מי הוא זה מלך הכבוד ה' צבאות נו\"ה דז\"א (ובמ\"א מבואר באופן אחר דבחי' כבוד אלקים הוא בחי' כבוד עליון דאבא שנעלם בהיכל דבינה עלמא דאתכסי'. וזהו מי הוא זה מלך הכבוד מלכא עילאה כו' וכבוד מלכים ת\"ת דאימא שנעשה כתר לזו\"נ חקור דבר כו' וד\"ל). ועד\"ז יתפרש כאן יהי כבוד הוי' דאור אבא לעולם שיצא מן ההעלם דבינה לגילוי בזו\"נ. וזהו ברוך כבוד הוי' ממקומו הנעלם בהיכל דאימא"],[2400650534,"כו'. וז\"ש יהי כבוד כו' דיו\"ד שבחכ' יאיר בגילוי כמו הנה ה' יוצא ממקומו כו' וזהו שאמר שאו שערים ראשיכם כו' שערים דבינה חסדים הסתומים יאירו בבחי' גילוי כדי שיבוא לגילוי מלך הכבוד כו' מאחר שמצוה או שמבקש שיהי' כבוד ה' לעולם בהכרח שמגיע לשרש ומקור הראשון שלמעלה מעצם ת\"ת דהוי' והוא בחי' נער מט\"ט שיש בו מעלה ע\"י בחי' העלאה שבו שגורם להמשיך ממקור הראשון דכבוד ה' ולכך בדידי' תלוי כו' וד\"ל. ישמח ה' במעשיו הנה מבואר בסידור דבח\"י פסוקים הללו נזכר שם הוי' דז\"א להאיר במל' כנ\"ל. אך בפסוק זה נזכר ב\"פ הוי' ובשאר פסוקים רק פעם א' (ובוהוא רחום לא נזכר כלל) והענין שהוא משום דפסוק זה מדבר בבחי' המשכה שאחר ההעלאה והוא בבחי' הבקשה שמבקש יהי כבוד דשרו של עולם אמרו בחי' מט\"ט שכלול מאו\"ח ואו\"י שהוא המעורר ההמשכה שיהי כבוד ה' כו' והוא ע\"י שישמח ה' במעשיו שיהי' מעשה התחתונים רצויים לפניו וישמח בהם (וכמ\"ש בע\"ח דבתחלה הי' חפץ חסד מעצמו ואח\"כ תלה רק במעשה התחתונים שמעוררים הרצון למלוכה כו') וכדי שיתקבל לפניו מעשה התחתונים אעפ\"י שאין העלאת מ\"ן כו' עז\"א ישמח ה' במעשיו מצד חסדי' העצמי' במקום גדולתו כו' ישפיל א\"ע להיות שמח במעשיו כו' אע\"פ דכלא חשיב וכמו עד\"מ כאשר המלך בטוב לב ורב חסד אז ישמח בעבדיו ועמו ויוכשר בעיניו כל מעשיהם משא\"כ כשאינו בחסד ומה גם ברוממות עצמותו שלא יוכשר הכל כו' כך למעלה הרי אמרו שמים לא זכו בעיניו כו' אך מצד החסדים העצמיים משפיל א\"ע לשמוח במעשיו כו' וזהו שתחלה אמר יהי כבוד הוי' כו' בחי' גילוי החסדים ואז ישמח ממילא במעשיו (או יתפרש ע\"ד המבואר במ\"א שסוף מעשה עבמ\"ת ויתגלה עי\"ז תחלת העונג הנעלם שנק' שמחה והוא לאחר שיהי' כבוד ה' בבחי' המלוכה שזהו שלימות מחשבה הראשונה דאנא אמלוך שהוא בחי' מל' דא\"ס כי נתחב\"ס ע\"כ הא בהא תלי' דכאשר יהי' כבוד ה' לעולם ישמח ה' במעשיו וצריך לשמחה זו המשכה דשם הוי' בפ\"ע כי הרי מה שיש לו עונג במח' הראשונה דמדת המל' הוא מפני שנמלך בנשמות של צדיקים כו'. והוא מ\"ש ישמח ה' במעשיו במעשי הצדיקים שיתאווה להיות לו דירה בתחתונים כו' ומ\"ש במעשיו סתם הוא בחי' עשי' שבדבור שעז\"א אף עשיתיו אף הפסיק כו' והוא רבותא גדולה ואף זה לשון ריבוי כמו גם כו' מטעם דלזה הי' עיקר הכונה ברצון הקדום כידוע ומפני שבחי' מט\"ט זה עומד בחיצוניו' הכלים דו\"ק דז\"א דיצירה כנ\"ל ע\"כ א' ישמח ה' במעשיו דוקא ולכך נזכר ב\"פ שם הוי' וכמ\"ש בסידור בח\"י פסוקים הללו שהן בכלים אמצעיים דז\"א דיצירה שהוא דבור שבדבור ומה שנוגע למעשה"],[2400650535,"נק' עשי' שבדבור וזהו ישמח ה' בדבור כדי שיהי' מקור למעשה כו' בי\"מ ותחלה יהי כבוד ה' מקור לרצון שבבחי' המל' עשי' שבדבור דז\"א כו' ואח\"כ ישמח ה' כו' או להיפוך דיהי כבוד בכלי אמצעי וישמח בעשי' שבדבור שישמח בדבור שנמשך כבר למעשה כמ\"ש וירא את כל אשר עשה כבר בדבור והנה טוב מאד כמ\"ש במ\"א וד\"ל. יהי שם ה' מבורך מעתה ועד עולם הנה ההפרש בין שם הוי' לכבוד הוי' הנ\"ל דבכבוד הוי' אמר בחי' המשכה למטה לעולם דמל' ובשם ה' אמר שיהי' מבורך בעצמו משום שנאמר ברכות לראש צדיק דכאשר כבוד ה' לעולם בחי' משפיע למטה אז ממילא מבורך שם הוי' בעצמו כו'. וביאור הענין הנה תחלה יש להבין מהו ענין שם הוי' ומהו כבוד הוי' כו' להיות מבואר במ\"א בפי' מי כמוך באלים ה' כו' דבזה נבדל בחי' ת\"ת שאין הכלי שלו מסתיר על האור משא\"כ באל ואלקים חו\"ג שהכלי מעלים ומסתיר את האור כו' לפי שהת\"ת כלול מב' הפכים חו\"ג ע\"כ גם הכלי אינו מסתיר אדרבה בכלי שלו בא גילוי האור בחיצוני' שבו כמו בפנימי' כו' (וראי' ממקום ארון שאינו מן המדה או מנסים שמאיר שם מלמעלה מן הכלי דטבע המגביל כו') וזהו הנקרא שם הוי' כלי הת\"ת דז\"א שהוא מבורך מאין האמיתי דפנימי' הכתר הנק' אין הנעלם ובשם הוי' דת\"ת בא בחי' אין זה עצמו בבחי' הגילוי בכלי ממש כמו הנסים וכה\"ג (כמו מקום גשמי שנעשה בו הנס וכמקום ארון כו') והיינו ההפרש בין כבוד ה' שאינו רק בחי' בקיעת אורות ניצוצי החסדים דהוי' דז\"א עד\"מ בקיעת אור השמש דרך עובי הרקיע המבדיל ומעלים כו' כי יש בחי' כלי המסתיר רק שבוקע ועובר קצת הארה כמו הכוכבים ברקיע שנק' כוכבי אור כו' ונק' זיו יקרי' דמלכא שעובר דרך הכלי כו' (וכענין כבוד מלכים חקור כו' שהוא הגלוי מן ההסתר כו') אבל שם הוי' הוא מתאחד בעצם האור דהוי' והוא מבורך עמו ומיוחד בהשוואה א' ממקור הראשון להיות ע\"י הכלי עצמה דוקא בא הגילוי אור כמו שהוא בעצמו (וכמ\"ש לא יהי' לך השמש כו' שמלובש בנרתק דשם אלקים אלא ה' עצמו יהי' לך לאור עולם כו'). וזהו יהי שם ה' מבורך כו' והיינו דוקא ע\"י שיהי' בחי' משפיע תחלה בבחי' כבוד ה' לעולם בבחי' בקיעת אור והוא הנק' צדי\"ק ח\"י עלמין וברכות לראש צדיק עליון ששם ה' מבורך בעצמו עי\"ז והיינו מעתה ועד עולם מעתה דבחי' המל' שכבר נמשך בצמצום עד עולם הא\"ס שבפנימי' הכתר כמו לע\"ל דכתיב וע\"י יתיב כו' ודוקא מעתה דסוף מעשה עבמ\"ת ולכך ברכות לראש צדיק (דאין נותנים לאדם ברכה רק בשביל המקבל כמ\"ש להניח ברכה אל ביתך כו') ובאמת כאשר שם ה' מבורך בעצמו תחלה ממקורא דכולא אז ממילא נבקע בקיעת"],[2400650536,"אור דרך המסך המעלים וכמו מאצי' לבריאה להיות מלך עולם כו'. ומ\"ש תחלה יהי כבוד משום דח\"י פסוקים הללו הם בבחי' וי\"ו צירופים דשם שד\"י שעולה מלמטה למעלה ובפסוק ראשון דיהי כבוד אות השי\"ן כו' וכמ\"ש בסידור בפרטי הכוונות של שמות העולים בגי' כו' ויש ששה מדות בקטנות דיסוד ז\"א שנק' שדי וכל אחד כלול מג' צירופים ויהי כבוד בחי' יסוד שבו להשפיע למל' והוא עיקר שם שדי כמ\"ש וארא אל אברהם כו' באל שדי שא' לעולמו די ושמי הוי' לא נודעתי כו' שזהו בחי' כלי פנימי' דת\"ת דתורה ופסוק זה דיהי שם באות ד' שבו כו' שהוא פרק האמצעי דיסוד שהוא צירוף דהוד שביסוד שע\"ז נאמר הוד והדר לפניו כו':"],[2400650537,"<h3>ממזרח שמש</h3>\n(קנד) <b>ממזרח</b> שמש עד מבואו כו'. הנה מבואר בס' הזוהר בכמה דוכתי בבחי' שמשא וסיהרא שהוא בחי' זו\"נ וכתיב כי שמש ומגן הוי' אלקים דשם אלקים הוא מסתיר ומגן ונרתק לשם הוי' רק לע\"ל כתיב ונגלה כבוד ה' כו' שמוציא חמה מנרתקה כו' אבל עכשיו מוסתר שם הוי' באלקים דוקא ולפי\"ז אינו מובן מ\"ש תחלה יהי כבוד ה' לעולם דמשמע שיתגלה כבוד ה' מהעלמו בשם אלקים כמו לע\"ל. אך הענין הוא דכבוד ה' לעולם הוא בבחי' הארת שם הוי' לבנות בנין כתר מל' להיות לו רצון למלוכה כנ\"ל באריכות. וז\"ש לעולם ה' דברך נצב בשמים שהוא בחי' כתר מל' שמאיר שם גילוי אור הוי' אבל בט\"ס דמל' שם מוסתר שם הוי' בשם אלקים (והוא בחי' [חכמה תתאה] שבדבור שמעלים בצירופי אותיות לאור המדות שבלב אבל הרצון של הדבור שנק' דברך בעצם אורו מאיר בלי לבוש כי מתאחד בעצם אור המדות שבלב כמ\"ש במ\"א. ומ\"ש למעלה בענין כבוד אלקים הסתר דבר על בחי' כתר מל' גם זה אמת שנק' הסתר דבר לגבי בחי' ממכ\"ע שמבחי' חכ' דמל' ושארי הספי' שבבי\"ע וכבוד מלכים חקור דבר היינו בט\"ס דמל' בבי\"ע כאשר בוקעים אורות [החסדים] דהוי' באלקים כמשי\"ת וד\"ל). והנה ידוע דבחי' חו\"ב נק' תרין רעין כו' והחכ' נק' אין בחי' נקודה ובינה נק' יש שהוא ההשגה ותפיסא בבחי' יש כו' ובחי' נקודה דחכמה מוסתר ונעלם בבינה שהיא ההשגה ולפי\"ז גם המדות שמסתעפי' מחו\"ב הרי כאשר נקודת החכ' בהעלם בבינה גם המדות שבחכ' בהעלם ובהשג' דבינה יש ג\"כ התפעלות המדות ונק' מדות שבשכל כידוע. אך הם סתומים ונעלמים שם כי כלולים בעצם המושג כנראה בחוש כאשר יטרד אדם [בטוב] איזה ענין בשכלו יוכלל אור התפעלות האהבה והי' כלא הי' רק אחר הסתלקות אור השגת השכל אז יוצא אור התפעלו' המדות במהות בפ\"ע ואז אור אבא מאיר בגילוי במדות כי הי' בחי' המדות דחכ' סתומים בהשגה ובהסתלקות"],[2400650538,"ההשגה יצאו לאור עם המדות שבלב וז\"ש מה שמו ומה שם בנו שאור שם מ\"ה דאבא יוצא מהעלם הבינה בהוולד המדות שבלב שנק' בן משום דממו\"ס דאבא קאתי משום דיסוד אבא ארוך משל אימא ומסתיים ביסוד ז\"א ולכך נק' [שמשא] יסוד אבא ויסוד ז\"א וזהו ממזרח שמש כו' שהמדות דז\"א נק' שמשא ואור השמש הוא בחי' יסוד [ז\"א] וראשית גילוי אור ממדות הוא לאחר בקיעת יסוד אימא שנגלה אור אבא שהוא שם מ\"ה דחכ' ומאיר בכל הו\"ק דז\"א שהוא שם הוי' בכלל וזהו הנקרא ממזרח שמש ראשית בקיעת אורו הוא זריחתו במזרח שהוא ת\"ת ונבקע יסוד דאימא ששם דוקא נגלה אור דאבא כו' ושם דוקא אין שם אלקים מסתיר לו כי נסתלק אור הבינה שנקרא אלקים עילאה המסתיר להוי' דחכ' כנ\"ל אבל זהו אינו אלא עד מבואו ולא עד בכלל דהנה כתיב וזרח השמש ובא השמש דשקיעתו במערב שהשכינה במערב והוא בבחי' המל' שנק' אלקים המסתיר על שם הוי' וכמ\"ש לעיל והיינו בבחי' ט\"ס דמל' מחכ' ולמטה דאור אבא אינו מאיר שם כלל וכידוע דאור אבא באצי' ואימא בבריאה דהיינו שחכמה באצי' לבד ולא בבריאה שהמסך מפסיק בין אצי' לבריאה והוא ההפסק שבין כתר לחכ' שבמל' ומ\"ש בראשית בחוכמתא הוא ח\"ת שבדבור שנבדל בערך מח\"ע שבראש כו' וזהו עד מבואו ששם מוסתר שם הוי' דז\"א באלקים מפני העלם אור אבא אבל עד מבואו במערב מהולל שם הוי' כמו שהוא בלא לבוש מסתיר כלל מטעם הנ\"ל וד\"ל. ועוד יש לפרש עד מבואו ועד בכלל דגם בהתלבשות שם הוי' באלקים מאיר גם שם הוי' ומהולל שם בנשמות ומלאכים עד גם ע\"ש דכתיב הללו את ה' כל גוים וכה\"ג משום דאין שם אלקים מסתיר גמור כנרתק ממש אלא נצוצי אורות הוי' בוקעים בו וכידוע בענין כ\"ו כל\"ח כו' וזהו כפי פי' הב' דלעיל בויהי כבוד ה' שהוא בקיעת ויציאת אור אבא מהעלמו בהיכל אימא כו' עד גם בט\"ס דמל' וגם בלבושי' [והעלמות] דנוגה דבי\"ע גם שם יאיר כבוד ה' דאור אבא וכמ\"ש במ\"א בענין ומרדכי יצא כו' והוא בחי' הביטול האלקי הנמצא בכל הברוא' עד גם היותר נפרדים וד\"ל. ואמנם לפי\"ז הרי יוכל להיות גילוי [אור] הוי' גם למטה מטה מאד ובאמת אין זה אלא לעתיד דכתיב ונגלה כבוד הוי' וראו כ\"ב ממש כו' ומ\"ש יהי כבוד ה' דאור אבא לעולם הנפרד וישמח ה' במעשיו עד למטה גם בע\"ש (דגם בחי' העלם דבינה יהי' בגילוי ע\"י השמחה דשמחה בבינה כשיצא סוד כו' וכידוע) קאי לע\"ל וקצת הארתו מאיר גם עכשיו כנ\"ל הנה לזה חוזר ומפרש בפסוק שאחר זה ההיפוך מזה (והוא במ\"ש רם על כל גוים הוי' כו' וכמשי\"ת וד\"ל). ואמנם לע\"ל כתיב ולא יבוא עוד שמשך וירחך לא יאסף"],[2400650539,"שגם ביחוד הוי' אלקים יאיר הארת אא\"ס ולא יהי' נק' שקיעה כלל באור השמש מצד התלבשות שלו משום דבחי' זו\"נ שוין בקומתן וכמ\"ש והי' אור הלבנה כאור החמה ולא תקרא מסתיר כלל ועוד א' לא יהי' לך עוד השמש לאור כו' (והוא מ\"ש יחיינו מיומים בחי' יחוד דהוי' אלקים בחי' חו\"ב וזו\"נ בשלימות גדלות המוחין ולמעלה מזה ביום הג' בחי' אא\"ס [שבכתר] יקימנו ונחי' לפניו ממש וד\"ל). רם על כל גוים ה' כו' הנה אחר שאמר ממזרח שמש כו' מהולל שם ה' דמשמע גם למטה מטה [באוה\"ע] והאמת כן הוא כמבואר בכמה כתובים אבל מ\"מ רם על כל גוים ה' דגם שמהללים שם ה' מרחוק הוא נראה להם ולא מקרוב והיינו רם על כו' שהוא מרומם ומתנשא מהשגתם לפי ששרש ע\"ש הוא רק מבחי' אלקים דוקא וגם זה רק מאחוריים דאחוריים והם אחוריים דמ\"ח צירופים האחרונים דשם אלקים וכמ\"ש פרעה לא ידעתי את ה' כו' מי ה' כו' לפי ששם אלקים מסתיר ע\"ש הוי' ולפי שהסתר דצירופים האחרונים בבחי' אחוריים נק' לבוש שק כמ\"ש ושק אשים כו' נעשה הבדלה גמורה ולזה גם כאשר יאיר אור הוי' בשם אלקים לא יגיע להם רק מרחוק מאד כמ\"ש בזהר על בלעם שאמר מחזה שדי כו' כמאן דחזי מבתר כותלא כו' ולכך נראה להם ה' ברוממות והתנשאות לומר על השמים כבודו והארץ נתן לבני אדם עזב ה' את הארץ כו' אבל ישראל חלק הוי' עמו מקבלים משם הוי' עצמו ואין שם אלקים מסתיר כלל להיות שרש נשמתם משם הוי' ע\"כ גם בהתלבשות הוי' באלקים אינו רם עליהם אלא אדרבה מקרוב יאיר בנפשם כמ\"ש אשרי העם שהוי' אלקיו ממש וכן ה' אלקיו עמו כמ\"ש יעקב והי' הוי' לי לאלקים ממש וגם ע\"י תשובה ומע\"ט נגלה בהם שם הוי' כמ\"ש וראו כל עמי הארץ כי שם הוי' נקרא כו' (ומ\"ש וארא כו' באל שדי ושמי הוי' לא נודעתי הרי בכמה דוכתי' אמר שם הוי' לאבות כמו וה' אמר כו' וירא ה' אל אברם רק ההפרש בין קטנות לגדלות מצד אור דתורה שלא ניתנה להם בגשמיות רק ברוחניות כמ\"ש במ\"א) ובעשר מכות דמצרים נגלה שם הוי' באלקים כמ\"ש וידעו מצרים כי אני ה' וכן ובכל אלקי מצרים אעשה שפטים אני ה' דוקא שהראה להם ששם הוי' מושל על שם אלקים כמ\"ש והוא ימשול בך וכמ\"ש במ\"א וד\"ל. ושרש הדברים ידוע דאברהם יצא ממנו ישמעאל כו' שמבחי' חו\"ג דמל' שמלובש בעה\"ד טו\"ר שם יש שרש יניקה לע\"ש אבל בשם הוי' בחי' ת\"ת קו האמצעי הוא בחי' יעקב אין שם יניקה לע\"ש ונקרא סגולה מכל העמים ושם אין הכלי מסתיר על האור כנ\"ל וז\"ש ה' אלקיו עמו וכן אשרי העם שה' אלקיו וכה\"ג ולזה כל יחוד הוי' ואלקים שע\"י תו\"מ [אינו אלא] ע\"י ישראל דוקא וד\"ל. ועוד יתפרש רם"],[2400650540,"על כל גוים ה' גם מצד הוי' עצמו שהוא רם ומתנשא ומתרחק מהם כי לא ירצה להאיר להם בקרוב מפני שהעכו\"ם הם בבחי' יש נפרד בבחי' גיאות כידוע ואא\"ס הוא מבחי' אין האמיתי ולא ישכון רק בבחי' אין ומה שהוא העדר היש והגיאות וכידוע בפי' התרגום כי גאה גאה גיאה על גוותנייא שעל הגאים הוא מתנשא ומסתלק מהם ועל השפלים הוא שוכן ומתקרב כו' וכמ\"ש מרום וקדוש כו' את דכא ושפל רוח כי תועבת ה' כל גבה לב ויובן זה עד\"מ אם המלך רואה איזה רוממות בשריו אז לא יוכל לסבול וישפילם או מתגאה עליהם וכשרואה שפלות וביטול שם הוא משפיל א\"ע מאוד מפני שזהו טבע המרומם ומוגבה בעצם מאוד שישנא מאד כל רוממות והתנשאות ויאהב מאד את השפלים ביותר שזה הוראה גמורה על עצם אמיתית הרוממות משא\"כ מי שאינו מרומם בעצם יאהב הגיאות וישנא השפלות ומזה יובן למעלה בהתנשאות אמיתית דאא\"ס עצמו שנקרא יש אמיתי דלכך גיאה על גיוותנייא ועל ישראל שהם שפלים משפיל א\"ע כו' ועולה בענין א' עם הטעם דבחי' אין האמיתי אינו שורה בבחי' יש והיינו הך כידוע דיש האמיתי הוא אין האמתי כו' וד\"ל. אך א\"כ לא יתכן סיפא דקרא על השמים כבודו כו' דהלא מכה\"כ ותהלתו מלאה הארץ גם בעכו\"ם כמ\"ש ממזרח שמש כו' ולפי' הא' דמצד עכו\"פם רם עליהם יתכן שיאמרו העכו\"ם על השמים כבודו כו' אך באמת מ\"ש מכה\"כ אינו אלא לישראל שאין כבוד אלא תורה ומלאכים בקשו תנה הודך כו' כידוע אבל לגבי הע\"ש על השמים כבודו מפני שרם ומסתלק מהם מטעם הב' הנ\"ל וד\"ל:"],[2400650541,"<h3>ה' שמך לעולם</h3>\n(קנה) <b>ה'</b> שמך לעולם ה' זכרך לדוד ודור כו'. הנה הזכיר כאן ב\"פ הוי' א' בשמך סתם והוא שמו העצמי שמורה על בחי' עצמותו ונקרא שם העצם ואח\"כ ה' זכרך כו' מה שנזכר ונקרא בשם כשיזכירוהו למטה יזכרו אותו בשם זה וכמ\"ש ה' למשה כי ישאלו ישראל מה שמו כו' זה שמי לעלם וזה זכרי לדור כו' וביאור הדברים הנה ידוע מארז\"ל דקודם שנברא העולם הי' הוא ושמו בלבד הרי הי' לו שם קודם שנאצל ונברא העולם ונק' שם העצם שמורה על בחי' עצמותו ונק' שמו הגדול והוא מ\"ש ה' שמך לעולם כו' ששמו בחי' נצחיות דא\"ס בלי שינוי כלל כמו שהוא קודם שנאצל כו' הי' הוא ושמו בלבד כך אחר השתלשלות דאבי\"ע כו' הוא ושמו העצמי בלבד וכמ\"ש אני הוי' לא שניתי כלל ומ\"ש ה' זכרך לדור ודור היינו מה שמבחי' שם זה נעשה מקור להשתלשלות דאבי\"ע והוא בחי' מל' דא\"ס אחר הצמצום שנמשך בבחי' קו להיות מקור לע\"ס דאצי' שנקרא דורות כידוע בענין קורא הדורות מראש [מראש] דא\"ק שזהו מבחי' מקור הרצון הקדום שכולל ע\"ס בבחי' ההעלם לבא לידי גילוי בבחי' האצי' זהו נקרא קריאה שקוראים לדורות ממקור העלם הרצון כו' וזהו הנקרא זכרון שנזכר על העלם הרצון ושם שייך זכרון"],[2400650542,"וקריאת שם מהעלם העצמי (ושרשו הא' הוא מה ששיער בעצמו בכח איך שעתיד להיות רצון וחכ' הכל בהעלם וגילוי כמ\"ש במ\"א בענין גליף גליפו בטה\"ע כו') שיבוא לגילוי והיינו ה' זכרך לדור ודור לכל פרט ופרט שבע\"ס דאבי\"ע שקוראים למקורם בזכרון שם זה ויש בזה שינוי מדריגות חלוקות לפי אופני פרטי המדריגות שהרי בכל דור ודור ממש מאיר בו מהארת העלם העצמי' בע\"ס דאבי\"ע באופן ומדריגה פרטית כמו הוי' של חסד או דין וכמו וי\"ו אלפי שנין אלף הא' של בחי' חסד כו' ודרך פרט בכל דור ודור יש בו אור מיוחד פרטי אשר בא [אז] השפע מהעלם העצמי' לגילוי באבי\"ע כמו והימים ימי בכורי ענבים ואמר בזוהר שביומי' אילין הי' האור מאיר מבחי' גבורות עליונות דבינה כו' ולפי אופן אותו הדור למטה כך מאיר למעלה ונמצא זכרון שם הוי' נמשך באבי\"ע בשינויים בכל דור ודור לפי מה שהוא אך מ\"מ הרי שם זה שרשו הוא בשם העצם כמו שהי' קודם השתלשלו' שהי' הוא ושמו בלבד רק לגבי המקבלים בא בזכרון בשינוי מדריגה אבל לגבי עצמותו אין זה שינוי כלל וכמ\"ש אני ה' לא שניתי ונמצא דה' שמך לעולם ה' זכרך לדור ודור ועד\"מ שמו של אדם כשהוא לעצמו אין בו שינוי כלל רק כשהוא נזכר בשם זה שהוא נתפס בו ונפנה לקוראו להיות נמשך שם בזה יש חילוק מדריגה לפי אופן הקוראו כו' וכך למעלה הרי צופה ומביט עד סוף כל הדורות (דהעלם דא\"ק עד דורות שבאין למטה מאדה\"ר דעשי' שנאמר דור הולך ודור בא כו') וכאשר נמשך לכל דור לקוראו בשמו ע\"ז אמר ה' זכרך לדור ודור בחילוקי מדריגות רבות כו' וד\"ל. וכמ\"ש במ\"א בענין ויקרא ה' ה' ב\"פ כו' דה' הא' בהעלם עצמותו וה' הב' כשנמשך למקבלים והוא עד\"מ המצייר אותיות הללו דשם הוי' במחשבה ולפי אופן ציורם במחשבה יצייר בכתב שהוא בדילוג הערך ואעפ\"כ הן אותם האותיות ממש רק שנבדלים מן העצמות כך השם שכלול בעצם נבדל בערך מאותיות קריאת שמו ומ\"מ בדוגמתו בא בקריאה ולכך זכרך לדור ודור בלי הפסק כמו ששמך לעולם בעצמיות רק שבא מן ההעלם לגילוי כמו מן הכלל לפרט שהכלל כולו מתחלק בפרט כו' כך מה שצופה ומביט כל הדורות בכלל בא בפרט וא\"כ גם שמו הכללי שהוא לעולם דא\"ס זכרך לדור ודור בלי הפסק בפרט וכמ\"ש זה שמי לעולם וזה זכרי לדור ודור שזה וזה א' הוא רק שזה בכלל ובהעלם עצמותו וזה בפרט ובגילוי חלוקי הדורות עליונים ותחתונים המסתעפים בבחי' נבדל מן העצמו' שאין זה שינוי לפניו כנ\"ל וד\"ל. (ועוד יש לפרש דה' זכרך קאי על עצמותו ממש שלמעלה משמו כי הרי אמר הי' הוא ושמו בלבד ותחלה אמר ה' שמך לעולם שהוא מל' דא\"ס ואח\"כ קאמר ה' זכרך לדור ודור שנזכר עצמותו ממש ולא זכרון שמו לבד"],[2400650543,"וכמ\"ש מי כה' אלקינו בכל קראינו אליו ממש שקוראים עצמותו בשמו אבל הכוונה לעצמותו ולא לשמו כו' כמשל הקורא לאדם שיפנה עצמותו אליו שקוראו בשמו בודאי אין הכוונה רק לעצמותו ולא לשמו כו' וזהו דשמך להיות נבדל מן העצם אמר לעולם בלבד וזכרך שהוא על העצם אמר לדור ודור שהוא לנשמות שבכל דור כו' דאדם אדמה כו' וכידוע ההפרש בין עולם שנה נפש כך ההפרש בין עולם לדור כו' ולפי\"ז ה' זכרך לדור ודור שכולל כל קומת א\"ק ממש ה' שמך לעולם כמו לע\"ל דכתיב מלכותי' מלכות עלם אז ג\"כ זכרך למעלה משמך כו' וד\"ל. ה' בשמים הכין כסאו ומלכותו בכל משלה. הנה בפסוק שלפניו דיבר בבחי' שם מ\"ה וכמ\"ש ה' שמך לעולם והוא לע\"ל בימות המשיח שאז נקרא כתר שם טוב שלמעלה מבחי' כתר מל' דדוד וכידוע בענין שם ומל' (כמבואר במ\"א בענין ע' שנין דדוד שנקרא חיים שאולים מאדה\"ר אבל במשיח נאמר חיים נתת לו וכמ\"ש וגבה מאד למעלה מאדם כו'). ועתה מדבר בבחי' מל' דדוד שנקרא כתר מל' כמ\"ש וישב ה' מלך לעולם כו' ואמר ה' בשמים הכין כסאו שנקרא כסא הוי' וכמו וישב שלמה על כסא הוי' כו' והענין הוא דפי' שמים היינו שמים עילאין בחי' התכללות המדות דז\"א שכלולים מחו\"ג אש ומים וזהו שמים כידוע וכמ\"ש לעולם ה' דברך נצב כו' שהוא דבר מל' נצב בשמים דוקא שהוא בחי' ת\"ת דז\"א והוא שרש התורה כידוע ו[כ]מ\"ש מלך במשפט יעמיד ארץ במשפט שבתורה שכלול מחו\"ג שהוא בחי' התיקון דשם מ\"ה וכמ\"ש דהתורה מן השמים נתנה כו' והוא כמו החכ' שבתושבע\"פ שבאה במדות כשר פסול כו' בבחי' קו המדה שלא להוסיף ולגרוע ובזה מתברר עה\"ד טו\"ר בתכלית שלא יהי' [תוס'] יניקה לחיצוני' רק כפי המדה הקצובה כו' דבחכ' אתברירו דוקא ולכך נקרא מתניתין מלכתא כמלך שגוזר זה יכשר וזה לא כו' בדקדוק דבר מל' כו' ולכך במשפט דוקא יעמיד ארץ בבחי' התיקון כידוע וז\"ש דאחר שהכין כסאו למלוכה בשמים דוקא אז ומלכותו בכל משלה גם בע\"ש דנוגה דעשיי' שמעורב רע גמור שמתלבש גם שם לבררם ולהכניעם לקדושה כמ\"ש בסידור דבכל גימט' ב\"ן והוא רומז לע\"ס דנוק' דקדושה הנכנסת בהיכלות דנוגה להכניעם כו' וזהו בכל משלה כמו דבר מלך שלטון שדבר מל' נתפשט למרחוק ולהכניעם תחת ממשלתו כך ומלכותו בכל משלה גם ביותר רחוקים גם בנפרד ממש כמו גם בקליפות הנק' רע גמור הרי מושל בהם שהרי גם בלעם אמר לא אוכל לעבור את פי הוי' כו' וכידוע וכל זה בבחי' מל' שמתפשט בעולמות בי\"ע עד תחתית המדריגה דקליפה שם נקרא ממשלה בע\"כ כי הן בבחי' הפירוד אבל כתיב מלך אלקים על גוים להשפיל ולהרים על מלכי האדמה באדמה וכמ\"ש השופט כל הארץ כו' וכמו לא שלם עון"],[2400650544,"האמורי עד הנה כו' ואמנם מה שמלכותו בכל משלה להכניעם ולבררם הכל הוא במשפט וכמ\"ש השופט כל הארץ כו' והוא ע\"פ משפט דתורה וכמארז\"ל ג' שעות יושב ועוסק בתורה ואח\"כ יושב ודן את כל העולם כו' והיינו מלך במשפט כנ\"ל וז\"ש ואשים דברי בפיך לנטוע שמים וליסוד ארץ וכמ\"ש במ\"א בענין שאין העולם מתקיים אלא בהבל תשב\"ר כו' שהכל במשפט דבר ה' והוא בבחי' דבר מל' שבתורה שבע\"פ דוקא דמל' קרינן לה כמ\"ש ואשים דברי בפיך והיינו דברי בפיך בע\"פ דוקא רק מפני שתושבע\"פ מקבל מתושב\"כ דוקא כמו מנלן א\"ק כו' ולכך ה' בשמים הכין כסאו בשמים תושב\"כ בחי' המדות דז\"א (דאורייתא מח\"ע נפקת היינו בחי' מדות דתיקון דז\"א שמאור אבא נפקת כידוע) וזהו הכין כסאו דמל' בשמים דוקא ושם נקרא כסא הוי' דהוי' הוא במדות דז\"א שהוא במדות עליונות דאצילות וזהו וישב שלמה [בחי' ח\"ת] על כסא הוי' דז\"א כו' אך הנה כל זה עכשיו ששם מ\"ה מברר לב\"ן ובחכ' אתברירו דוקא והוא ע\"י כתר תורה כו' (והן ע' שנין דדוד ז\"ת דבינה ומל' שמקבל מח\"ע והוא א\"ק וכמ\"ש מה שמו כו') וזהו שרש ענין התורה דמברר לעה\"ד טו\"ר עכשיו ולכך ה' בשמים הכין כסאו (וכנ\"ל בפי' לבש ה' עוז כו' נכון כסאך מאז כו') אבל לעתיד לבוא שעה\"ד טו\"ר יתברר לגמרי דכתיב ואת רוח הטומאה אעביר מן הארץ ולא יצטרכו אז לבירור דחכ' (והוא בחי' כתר שם טוב שלמעלה מכתר תורה וכתר מל' וכנ\"ל בפי' הוי' שמך לעולם כי מלכותי' מלכות עלם וכמ\"ש חיים נתת לו כו') אזי נאמר \"ישמחו \"השמים \"ותגל \"הארץ ר\"ת הוי' דארץ ושמים שהן תושב\"כ ותושבע\"פ ישמחו לאחר תשלום כל הבירורים כמשל לאחר שלימות המלאכה שמתברר היטב בחכ' שבמדות ומעשה אז ישמח האומן במעשה ידיו כו' כך כתיב ואהי' אצלו אמון כו' דח\"ע דאורייתא נקרא אומנא בראשית בחכמתא בחכ' יבנה בית כו' כידוע ואז דוקא ישמחו השמים בחי' המדות דתורה ששרשם בחכמה עילאה עד רום המעלות ותגל הארץ בדבר מל' בתושבע\"פ וכמ\"ש משחקת לפניו בתבל ארצו כו' ויאמרו בגוים ה' מלך פי' דבזמן הבירורים שבחכמה עילאה וחכ' תתאה לא נקרא בעובדי כוכבים עדיין כי הם מקבלים רק מבחי' אחוריים דמל' ע\"כ נאמר ומלכותו בכל משלה בבחי' ממשלה בע\"כ ולא ברצון בבחי' הביטול בתכלית כמו בפנימי' העולמות עכשיו אך לע\"ל שיתברר הכל אז ותגל הארץ לגמרי כמ\"ש אז אהפוך אל עמים שפה ברורה כו' וכן ונהרו אליו כל הגוים כו' (שהוא בימוהמ\"ש שאז בחי' כתר ש\"ט כו' כנ\"ל) ובחי' [א\"א] דאצי' יהי' בבחי' מל' דאצי' בבי\"ע דעכשיו כמ\"ש במ\"א בענין כוסי רוי\"ה [בחי' ארך אפים] כו' וז\"ש ה' מלך לשון הווה ומבואר בסידור"],[2400650545,"שהוא בחי' א\"א דאצי' ה' מלך בחי' או\"א דאצי' שהוא כמו ה' מלך גיאות לבש לבש ה' עוז שהוא התורה עכשיו דמלך במשפט כו' כנ\"ל ה' ימלוך לעולם ועד בחי' זו\"נ דאצי' והוא מ\"ש בדניאל וע\"י יתיב כו' מלכותי' מלכות עלם שהוא בחי' כתר שם טוב דמשיח למטה שלמע' גם מכתר מל' דדוד למעלה עכשיו וכמ\"ש ישכיל עבדי כו' וגבה מאד כידוע וד\"ל:"],[2400650546,"<h3>ה' מלך עולם ועד</h3>\n(קנו) <b>ה'</b> מלך עולם ועד אבדו גוים מארצו. הנה תחלה דיבר בימות המשיח שעל זה אמר ה' ימלוך לשון עתיד ונק' מלכא משיחא וע\"ז אמר כוסי רוי\"ה גימט' רכ\"א שהוא בחי' אר\"ך אפים דהיינו בחי' א\"א דאצי' שנק' כתר דאצי' יהי' אז בחי' מל' כנ\"ל. (ובחי' הכתר דאצי' דלע\"ל יהי' מכתר דא\"ק עכשיו ומל' דא\"ס מאיר בו ויהי' נק' כתר ש\"ט משום דכתר מל' [דדוד] יתעלה אז ויהי' כ\"ע דנעוץ תחלתן בסופן כו' לע\"ל דווקא). ולפי\"ז בחי' הכתר מל' דא\"ס שלפני הצמצום מאיר גם אז בבחי' מקיף בהעלם ומה שאנו אומרים גלה כבוד מלכותך עלינו מהרה היינו רק בחי' מל' דא\"ס לבד שיבא אז בגילוי כמו בחי' כתר דא\"ק כו'. (ובכלל היינו רק פנימי' ע\"י שהוא הממוצע בין עצמות אא\"ס לנאצלים כידוע). וזהו שאנו אומרי' כי המלכות שלך היא כו' וכן לך הוי' הממלכה וכה\"ג הי' ביציאת מצרים שנגלה עליהם מלך מלכי המלכים כו' בחי' מל' דא\"ס שלפני הצמצום הראשון שעל זה אמר מלכותך מל' כל עולמים וכן מ\"ש אני ראשון ואני אחרון וכן ראו כי אני אני הוא כידוע משום דנעוץ סופן בתחילתן והיינו ישכיל עבדי מל' דאצי' שבבריאה ירום בכתר דאצי' ונשא בכתר דא\"ק וגבה במל' דא\"ס שאחר הצמצום שנקרא טהירו תתאה מאוד במל' דא\"ס שלפני הצמצום שע\"ז א' הי' הוא ושמו בלבד ונק' טה\"ע כידוע. אך הנה עוה\"ב הוא למעלה מימוהמ\"ש שאז נק' מנוחה לחיי העולמים והוא אלף הז' שנק' יום שכולו שבת כו' יום שכולו טוב כו'. וכידוע דעוה\"ב אין בו אכילה ושתייה רק צדיקים יושבים כו' שאז הוא בחי' גילוי עצמות אא\"ס שלפני הצמצום (כמו קודם שעלה ברצוה\"פ אנא אמלוך שנק' כתר מל' דא\"ס כידוע) למטה כמו למעלה וכמ\"ש ואמר ביום ההוא הנה אלקינו זה כל אחד מראה באצבעו כו' והיינו נש\"י דווקא דכתיב עין בעין נראה אתה כו' ואין זה אלא בנשמו' דצדיקים שנק' בנים (כמ\"ש במ\"א בענין ותפארת בנים אבותם וכן ישראל אשר בך אתפאר ולכך אין חייבים בראי' רק ישראל שהוא ענין לאסתכלא ביקרא דמלכא כו' שהוא תפארת לבנים דווקא ולא לעבדים וזרים כו' וכך בראי' המהות ועצמות בעוה\"ב אין זה רק לישראל לבד וכמאמר פשט המשנ' כל ישר' יש להם חלק לעוה\"ב ישרא' דווקא שנק' צדיקים שנאמר ועמך כולם צדיקים לעולם יירשו ארץ כו' ואפי' פושעי ישראל מלאים מצות כרימון כו' ע\"כ הם יירשו ארץ ולא זולתם וכמ\"ש במ\"א ע\"פ גמלתהו טוב כו')."],[2400650547,"<b>ושרש</b> הדברים להיות ששרש ישראל עלו במחשבה והיינו בבחי' פנימי' ועצמיות דווקא וגם עובדי כוכבים עלו במחשבה רק שעלו בבחי' חיצוני' ופירוד דהיינו שהפרידן מאחדותו הפשוטה כדי שיהי' דבר זר ונבדל מן העצמו' כו' והוא שרש ענין הצמצום הראשון הנק' חושך סתרו וכמו למטה במל' דאצי' בבי\"ע הוא בחי' צמצום גמור שנק' חושך והסתר כמשארז\"ל כברייתו של עולם ברישא חשוכא והדר נהורא כידוע. וזהו ואלה המלכים כו' לפני מלוך מלך לבנ\"י שהוא בחי' ז' מלכין דתוהו שקדמו לתיקון שהם יעקב וישראל (וזהו שהשיב ר' יהודא לר' זירא על שאלתו מ\"ט עיזי מסגי ברישא שהן עובדי כוכבי' ועשו איש שעיר וישראל נק' צאן כו' משום דברייתו של עולם ברישא חשוכא והדר נהורא כו' דהיינו ענין א' כמ\"ש במ\"א וד\"ל). ומ\"ש אשר בך אתפאר היינו לפני הרחוקי' כו' והיינו המבדיל בין ישראל כו' גם בתחלת המח' ורצון כו' ולכך בהגלות נגלות למטה האור העצמי דא\"ס הרי גם חושך לא יחשיך כו' כי אין בחי' חושך סתרו רק עכשיו שהוא בחי' צמצום הראשון ולמטה נק' חושך גמור אבל כשיאיר למטה כמו למעלה ממש בהשוואה אחד א\"כ בהכרח שלא יהי' בחי' חשך סתרו למע' וממילא יובן מזה שבעוה\"ב לא יהי' הגילוי הזה רק לישראל לבד כי אין כח לז' מלכין דתוהו שרש עובדי כוכבי' שם כלל וכלל וכמ\"ש במ\"א בענין ויעקב איש חלק וכן חלק ה' עמו ממש וע\"ז היסוד הוסדו כל הפסוקים הללו שאומרים אח\"כ כמו כי בחר ה' בציון כו' כי יעקב בחר כו' כי לא יטוש ה' עמו כו' וקדם תחלה הטעם בשרש הדבר הזה לפי שיהי' גילוי עצמות אא\"ס למטה בלי הסתר כלל ואז ודאי יפר ה' עצת גוים משרשם בצמצום הנק' חושך כו' ועצת ה' היא תקום כו' הן ישראל שמתקשראין באורייתא כו' כי הוא אמר כו'. וזהו שרש כללות המשך הפסוקי' האלה (ויתבארו בדרך פרט בפי' המילות). וזהו מ\"ש ה' מלך עולם ועד. פי' שלאחר שכבר יהי' למלך עולם ועד מהעלם עצמותו ממש לגילוי למטה כמו למעלה ממש ולא ע\"י צמצום כו' אז אבדו גוים מארצו דצדיקים דוקא יירשו ארץ שהוא העוה\"ב וכמ\"ש ה' בדד ינחנו כו' וכן ה' אלקיו עמו ותרועת מלך בו דוקא וז\"ש מארצו דוקא והוא א\"י שארז\"ל עתידה א\"י שתתפשט בכל העולם כולו וירושלים בכל א\"י וכמ\"ש במ\"א. וזהו ההפרש בין עוה\"ב בין ימות המשיח דבימות המשיח רק יהי' מלך על הכל ויאמרו גם הגוים ה' מלך וכמו שאנו אומרים מלוך על כל העולם כו' והופע כו'. אבל עצמות אא\"ס ממש שהוא למעלה גם מבחי' מל' דא\"ס כמ\"ש לך הוי' הממלכה כו' היינו בחי' עוה\"ב שנק' מנוחה לחי העולמי' כידוע ואז נא' מלך עולם ועד ועד בחי' נצחיות דא\"ס בלי שינוי כלל להיותו בלי צמצום דלא"],[2400650548,"כעכשיו שאמר ה' מלך גאות לבש כו' ולכך אבדו גוים מארצו מטעם הנ\"ל וד\"ל. ה' הפיר עצת גוים הניא מחשבות עמים כו'. פי' ע\"ד הפשוט קאי בדור הפלגה שהפיר עצתם ומחשבתם שאמרו נעשה לנו שם בחי' קומה שלימה בחי' שם מ\"ה כו'. רבות מחשבות כו'. הנה ידוע דשרש ע\"ש דנוגה הוא מבחי' ז' מלכין קדמאין דתוהו וכמ\"ש ואלה המלכים כו' ואמר באד\"ר דבאני עלמין ולא אתקיימו כו' ובל' רז\"ל הי' בונה עולמות ומחריבן כו' והענין רומז בבחי' או\"כ דתוהו שקדמה לבחי' התיקון שהי' אורות תקיפין שלא יכלו הכלים לסבול האור ונשברו כו' והן רפ\"ח נצוצות שנפלו בשבירה כו' עד ע\"ש דנוגה וזהו שמע שם ע' רבתי דז' מלכין כו' וז\"ש ורוח אלקים מרחפ\"ת רפ\"ח מ\"ת כו' ובחכ' אתברירו היינו בבחי' חכ' שם מ\"ה דתיקון הוא בבחי' מלך הח' כו' הדר והוא בבחי' חכ' שבתורה שהתורה קדמה לעולם ונק' משל הקדמוני וכתיב ואהי' אצלו אמון כו' אומנא כו' ונק' חכ' ברורה שמבררה בחי' קו המדה שלא להוסיף ולגרוע וזה הי' עיקר בחי' התיקון לבחי' התוהו ע\"י בחי' התכללות ומזיגה נכונה והוא במיעוט האור ובריבוי הכלי' מכלים שונים שעי\"ז יהי' בחי' קיום האורות בכלים בל תמוט לנצח. (וז\"ש ה' מלך גאות לבש בבחי' מל' בחי' ב\"ן דתוהו ואח\"כ לבש ה' עוז דתורה בבחי' התיקון להיות תכון תבל בל תמוט משום דע\"י בחי' התנשאות וישות דאורות דתוהו נעשה השבירה וכמ\"ש וימלוך כו' וזהו לא אתקיימו כו' עד בחי' התיקון דאדם שהוא מדות דתורה שנאמר זאת תורת האדם בחי' ההתכללות בריבוי הרחבת הכלים כו') וז\"ש על מה אבדה הארץ כו' וכן אמרו אין העולם מתקיים אלא בהבל תשב\"ר כו' וכתיב אם לא בריתי כו' וכן כתיב ואשים דברי בפיך כו' לנטוע שמים כו' וכה\"ג רבים בכתובים. וכך יובן כאן מ\"ש ה' הפיר עצת גוים בחי' ז' מלכי' דתוהו שאינם ע\"פ בחי' החכ' שבתורה כי הן ענפי' מתפרדי' כו' זת\"ז ולא ישכון בהם אחד\"פ כו' רק בעצת ה' שהוא בחי' חכ' שבתורה שהוא בבחי' התיקון דשם מ\"ה. וז\"ש רבות מחשבות בלב איש שהן במדות דתוהו שלמע' עדיין מהגבלת האור בכלים בבחי' התיקון והתכללות כו' אבל עצת ה' דווקא היא תקום כי היא נצחי וכל מחשבות ועצות זולתו שלא בבחי' התיקון שע\"פ התורה אינו מתקיים כמ\"ש באני עלמין ולא אתקיימו כו' שהן רבות מחשבות בלב איש קודם בחי' התיקון. אך אח\"כ עצת ה' לעולם תעמוד והוא לעולם דא\"ס שמאיר באלף הז' שאז עצת ה' שהיא התורה שבחכ' אתברירו כל הרפ\"ח ניצוצין דתוהו היא תעמוד ותקיים כל מחשבות לבו שהוא רבות ולא יפול א' מהם כי כולם יבואו בבחי' התיקון וזהו תעמוד מחשבות לבו לדור"],[2400650549,"ודור כי בכל דור ודור מתבררים מבחי' רפ\"ח ניצוצין דתוהו עד סוף כל הדורות כשיהי' מנוחה לחי העולמים וזהו עצת ה' לעולם תעמוד כו' גם בעוה\"ב שהיא למעלה מתו\"מ וכמ\"ש שש שנים יעבוד ע\"ע ובשביעית יצא לחפשי חנם בלא מצות שהוא אלף הז' שהוא זמן קבלת שכר כו'. וכמשארז\"ל למחר לקבל שכרם כו' מ\"מ עצת הוי' דתורה תעמוד גם אז ולא להיות בבחי' התיקון לתקן ולברר לתוהו אחר שכבר נברר הכל ואין מה לברר רק מפני שסוף מעשה דבחי' הבירורים דרפ\"ח כו' עלה בתחלת המח' שיהי' בבחי' שבירה ותיקון שמזה יהי' בחי' קבלת השכר דצדיקים בעוה\"ב לראות בראיי' המהות עין בעין כו'. ע\"כ אמר דעצת ה' לעולם תקום גם בעוה\"ב רק שאז נשלם עצת ה' לבא לתכלית תועלת שלה עד\"מ כאשר ישאל עצה ועושה כאשר יעצהו שבא העצה לטובה בפו\"מ אז נק' עצה טובה משא\"כ קודם שנעשה מעשה ע\"פ העצה ולא ידעו אם היא עצה טובה אם לא כך ע\"י בחי' עצת ה' שבתורה לברר לרפ\"ח ניצוצין בסור מרע ועש\"ט כל זמן זה שעדיין לא נגלה כל טוב העליון שמעצה זו עד שכבר נעשה מעשה בתכלית כל הבירורים אז נגלה כל הטוב העליון שבעצה זו בפו\"מ. והוא ענין וגילוי עצמות אא\"ס שיהי' בעוה\"ב ע\"י מעשה המצות דווקא כמ\"ש כל ישראל יש להם חלק לעוה\"ב משום שנק' צדיקים ע\"י המצות דווקא ולכן אמר עצת ה' היא כו' לשון נוק' כו' משום דאשת חיל עטרת בעלה נקבה תסובב גבר שהמל' נק' עצת ה' כמו עד\"מ כל דבר שצריך לבוא לידי מעשה בפו\"מ דווקא שם הוא עיקר ענין העצה דכליות יועצות איך לעשות כי המעשה אחת היא והעצה תפול שם דווקא איך תהי' המעשה (וז\"ש רבות בנות עשו חיל לברר כו' ואת עלית כו' שהמל' היא כנ\"י שנק' אחת היא כו' שמקבלת מאחד כו' הוא במצות מעשיות שבהן ועל ידן מכוונין לרצון וחכ' שבפנימי' עצמותו דווקא בלי נטיות ימין ושמאל). וזהו שנק' עצת ה' היא תקום לשון נוק' והן כנ\"י שמקיימין המצות שעושים עצת ה' בפו\"מ כמ\"ש סוף דבר כו' את האלקים ירא כי זה כל האדם נעוץ תחב\"ס דווקא והוא עיקר בחי' עצת ה' שבא לידי סוף מעשה דווקא. וז\"ש רבות מחשבות כמו רבות בנות עשו כו' ועצת ה' היא תקום היינו תושבע\"פ מל' קרינן לה שבא לידי מעשה בפו\"מ כמ\"ש סוף דבר כו'. עצת ה' לעולם תעמוד כו' דהלכות אינן בטילות לעתיד לבא מטעם הנ\"ל. שזהו סוף מעשה שעלה כו' שמזה כל עיקר חיי עוה\"ב ולכך אמר יפה שעה אחת בתשובה ומעש\"ט בעוה\"ז מכל חיי העוה\"ב שאין שם רק חלק אור מעצת ה' שבתורה שקדמה לעולם ובתשובה ומעש\"ט בעוה\"ז מאיר מכל עצמות רצונו וחכמתו לפי שעוה\"ז קודם הבירור"],[2400650550,"ועוה\"ב לאחר הבירור שאין שם תשובה כלל והיינו דלאחר הבירור אינו שורה רק לראוים כו'. אבל בעוה\"ז גם הרע יוכל להיות טוב ולכך יוכל להיות השראת העצמות בתשובה ומעש\"ט בעוה\"ז בשעה אחת יותר מכל חיי העוה\"ב וזהו שכר מצוה מצוה כו' כמ\"ש במ\"א באריכות וד\"ל:"],[2400650551,"<h3>כי הוא אמר ויהי </h3>\n(קנז) <b>כי</b> הוא אמר ויהי הוא צוה ויעמוד כו'. הנה ארז\"ל שלשה דברים קדמו לעולם תורה ותשוב' כו' וישראל קדמו לכולן כו'. וזהו בראשית כו' בשביל התורה כו' ובשביל ישראל שנק' ראשית כו' כמ\"ש שישראל עלו במחשבה ומחשבה זו קדמה לכולם ובתחלה דבר בעצת ה' דתורה שקדמה לעולם כו' ובכאן מדבר בישראל שקדמו שבשבילם נתנה התורה [הקדומה] וכמ\"ש ויקם עדות כו' ותורה שם בישראל כו' וזהו כי הוא אמר במחה\"ק לכולם והוא שרש ישראל שעלו במחה\"ק לכל ולכך הקדי' זה הפסוק לפסוקים שאחריו כי בחר ה' בציון כו' כי יעקב בחר כו' כי לא יטוש כו' דקאי הכל בשרש ישראל למעלה שנבחרו קודם כמ\"ש הבוחר בעמו ישראל והבוחר בתורה כו'. אבל ההפרש בין ישראל לתורה הגם שלמטה התורה למעלה מישראל וכמ\"ש בזוהר ישראל מתקשראן באוריי' כו' ונק' כלה והתו' נק' חתן כידוע בענין תורה צוה לנו משה כו' אך למעלה הרי אמיתות שרש הנשמות דישראל הוא בעצמות ופנימי' אא\"ס ממש שלמעלה גם מבחי' פנימי' ועצמית רצונו וחכמתו שבתוה\"ק ג\"כ להיות' בבחי' פנימי' ועצמות ממש כי נק' אדם כמו נפש אדם שמוליד בדומה לעצמו ממש כידוע וזהו ענין הבחירה שנבחר הפנימי' מן החיצוני' וההפרש ביניהם הוא שהפנימי' ועצמות יעמוד לעולם ולא יהי' בו שינוי ותמורה שהעצם אינו משתנה והחיצוני' יחלף ויעבור ולזה בפסוק זה נותן טעם למה שקדם שהפיר עצת כו' ולא נתקיימה רק מה שהוא אמר וצוה שיעמוד לעולם (וכמ\"ש במ\"א בענין כאשר השמים החדשים עומדים לפני כן יעמוד זרעכם ושמכם כו' וכשם שא\"א לעול' בלא רוחות כך א\"א בלא ישראל כו' וכמארז\"ל במי נמלך בנשמתן של צדיקים הרי גם מה שעלה ברצון הפשוט להאציל ולברוא כו' במקור הרצון הפשוט נמלך בנשמתן כו' כי נתאווה להיות לו דירה בתחתונים לכך נתעורר חפץ חסד זה העצמי להיות מקור לרצה\"פ זה כו' כדי להיות לו דירה בישראל דווקא א\"כ ודאי בהכרח שכבר קדמו במחשבה [העצמי'] בבחי' פנימיות ועצמות ביותר וכמ\"ש בראשית בקדמין ובחוכמתא כו' בשביל ישראל כו'. וזהו שסמך זה הפסוק דכי בחר ה' בציון למה שאמר כי יעקב בחר לו כו' דהכל ענין אחד דמה שאמר וצוה לעמוד לעולם בבחי' בחירה בעצמות ופנימיות הוא וזה שבחר בציון למושב כו'. ועוד יתפרש גם כפי הפשוט שיהי' קיום נצחי וכן ההשתלשלות רק בשביל"],[2400650552,"שנתאווה ואוה למושב לו בציון דווקא שהוא הבוחר בעמו ישראל להיות לו דירה והשראה בהם דווקא וכמ\"ש ונתתי משכני בתוככם דווקא מטעם הנ\"ל דישראל קדמו לכולם ואין טעם כלל לבחירה זו רק היות הדבר בבחי' פנימי' ועצמו' ממש וכמ\"ש במ\"א בענין יבחר לנו את נחלתנו (דבאמת כמו שהוא ית' מרומם לעצמותו ממש הרי קמי' כחשיכא כאורה כו' וישראל ועכו\"ם שוין ולכך ביקש משה ונפלינו כו' שלא תשרה שכינה בעובדי כוכבים לכך היא הנותנת דווקא שנבחר לישראל גם שם לפי שהם מבחי' פנימי' עד רום המעלות והוא ית' כל יכול להגביל ולברר גם במדריגה העליונה שברוממות עצמותו כו' וכמ\"ש במ\"א בענין הפיל פור הוא הגורל כו' ובבואה לפני המלך אמר עם הספר ישוב מחשבתו שיבחר משם דווקא בישראל ומ\"ש אמר עם הספר כו' היינו מ\"ש כאן כי הוא אמר ויהי משום שכבר בחר ה' בציון מטעם הנ\"ל וד\"ל. כי בחר ה' בציון כו' כי יעקב בחר לו יה כו'. הנה בציון בחר שם הוי' בשלימות וביעקב בחר לו י\"ה משם הוי' כו'. ולכאורה ידוע בענין ציון שהוא בחי' המל' בחי' מקבל ויעקב בחי' ת\"ת דז\"א בחי' משפיע כו' והקדים בחירה זו דבציון לבחירה דיעקב כו'. וכנ\"ל דשרש נש\"י קדמה לתורה כו' (ומ\"ש ויקם עדות ביעקב ותורה שם בישראל הכל מתפרש בשני אופנים או עדות דתורה נבחר עם יעקב לאחר שבחר בציון או דויקם עדות לאחר שבחר ביעקב שיקיימו התורה כו'). הנה הענין הוא כידוע דבחי' ציון הוא בחי' עצמיות התקשרות המקבל אל המשפיע בהעלאת מ\"ן תמיד בלי הפסק וביטול כלל לעולם וזה מורה על בחי' עצמות ע\"כ התקשרות עצמות מכל עצם אינו משתנה ולא יתחלף ויעבור לעולם כו' (וכמ\"ש בסידור דציון הוא בחי' יסוד דנוק' והוא בארה של מרים כמ\"ש עלי באר ענו כו' בידך אפקיד רוחי עליות הנשמות מצד עצמיות דוקא). ודוגמא לדבר בשעת מ\"ת שהקדימו ישראל נעשה לנשמע הרי זה הי' רק מצד בחי' [עצמיות] ההתקשרות שממילא נכלל בזה כל ביטול רצון במס\"נ על התו\"מ אפי' התומ\"צ שאח\"כ כביטול מנה במאתיי' כו'. ועוד דוגמא לזה ממה שמצינו בבע\"ת שגם לאחר שנשקעו ברע יוכלו לשוב בתשובה שלימה בכלות הנפש כראבד\"ר שיצאה נשמתו בבכיה וכה\"ג מצד עצמות התקשרות דבחי' יחידה כו' וז\"ש לא מאסתים כו' להפר כו' בריתי אתם כו' כי שרש נשמתם אחוז וקשור בבחי' עצמות על כן לא יוכלו להפרד לעולם וזהו העולה למעלה מכל תו\"מ שישראל עושין כי גם אם לא אכשר דרא בתו\"מ כלל אם ימצא בהם התשובה מעומקא דליבא בהתעוררות התקשרות זאת העצמי' כמו בע\"ת וכה\"ג שרוצה ה' בהם ג\"כ בבחי' עצמיות שיש לו בהם מקודם שעלה ברצון להשתלשלות"],[2400650553,"וז\"ש כי בחר ה' בציון דוקא ונקודת התקשרות עצמות ששרשה מעוררת עצמית בחירתה למעלה מן הטעם להיות אווה למושב לו בציון דוקא שיהי' לו דירה בהם דוקא כנ\"ל. ונתתי משכני בתוככם משכונא דילי גבייכו והוא רוחא דשביק כו' שלא יוכלו להפר בריתי ומפני שאין האשה כורתת ברית כו' כמ\"ש במ\"א בענין ותאמר ציון עזבני כו'. כי יעקב בחר לו י\"ה. פי' יעקב הוא בחי' המדות המשפיע בכנ\"י שנק' בריח התיכון כו' להיות מקיימין המצות באהוי\"ר בהתכללות כו' וכמ\"ש ויקם עדות ביעקב כו' והוא קו האמצעי דת\"י כו'. דלכאורה המדות שנמשכים מחו\"ב שנק' י\"ה הן למעלה מבחי' נקודת התקשרו' דציון הנ\"ל אבל באמת אנו רואים שנקודת עצמות התקשרות הנ\"ל יתקיים יותר מפני היותה מבחי' עצמות יותר וכמו בכל דור ודור שיש שינויים וחילופים במדות ובמעשה דכנ\"י ולא יש עוד שינוי ותמורה בעצם נקודת יהדותם כלל מטעם הנ\"ל. ולזה לא אמר רק כי יעקב בחר לו י\"ה כו' שענין הבחירה שנבחר יעקב אינו אלא בשלימות ב' הקוין ימין ושמאל חח\"ן בג\"ה מב' אותיות הללו די\"ה כידוע דחו\"ב שהן י\"ה הרי החכמה מקור החסדים ובינה מקור הגבורות וכן למעלה מן החכ' שהוא הרצון יש ב' קוין חו\"ב וחו\"ג ובחי' הדעת ות\"ת דיעקב נק' בריח התיכון קו האמצעי ע\"כ נק' מובחר שבאבו' שכוללם יחד ונבחר מאמצעות שניהם כמ\"ש יעקב אלקי אבי אברהם ופחד יצחק הי' לי כו' כמ\"ש במ\"א בענין וי\"ו דוהנורא שהוא בחי' ת\"ת דיעקב וז\"ש כי יעקב בחר לו י\"ה כו' וכמארז\"ל גדולה דעה שנתנה בין ב' אותיות די\"ה וזהו סגול התחתון שני נקודות דחו\"ג למעלה והת\"ת מחברם למט' ואם הדעת מחברם למע' נק' סגול העליון אבל כ\"ז בבחי' המדות שמקבלי' מחו\"ב ע\"י הדעת אבל ג\"ר דכח\"ב הרי חו\"ב למטה והכתר מחברם למע' זהו מ\"ש ישראל לסגולתו סגול העליון יותר כידוע. וזהו מפני שבהתכללו' אמיתי בשני הפכים מגיע בעצם השלימות באחדות בכתר שהוא הרצון טרם שמתחלק לחו\"ב וחו\"ג וכו' דהיינו בפנימי' ועצמי' הרצון שנק' כתר שבכתר שאין טעם כלל לרצון כידוע וזהו כי יעקב בחר לו לעצמו בעצמו' הרצון ע\"י בחירה י\"ה שנבחר מאמצעות שניהם כנ\"ל בבחי' סגול התחתון בדעת ות\"ת וזהו נעשה ישראל לסגולתו בפנימי' הכתר שמשם בא התחלקות הג' קוין כו'. ואמנם כל זה למטה מבחירה שבחר ה' בציון בבחיר' עצמיות ממש כנ\"ל ולא מצד עצמי' הרצון כמו עצמי' הרצון דנעשה ונשמע וכה\"ג בבע\"ת שבא מכחה של עצמות נקודת ההתקשרות הנ\"ל. ולכך הקדים תחלה כי בחר ה' בציון לבחור לו י\"ה ביעקב דאחר שבחר ה' בציון ואוה למושב לו מטעם בחי' העצמות ממש אז נאמר כי יעקב בחר לו י\"ה בעצם הרצון דהא בהא תלי' אם לא בחר ה'"],[2400650554,"בציון למושב לו לא הי' בחירה ורצון עצמי ביעקב כי יש בכלל מאתיים מנה וד\"ל. כי לא יטוש ה' עמו ונחלתו לא יעזוב. הנה ידוע שישראל נק' בנים ונק' עבדים ג\"כ כמ\"ש כי לי בני ישראל עבדים ונק' עמו ונחלתו כמ\"ש יעקב חבל נחלתו ולהיות שקדם תחלה בשרש העצמיות דכנ\"י כמ\"ש כי בחר ה' בציון שהן הנשמות שנק' בנים וביעקב בחר לו י\"ה כו' ע\"כ גם בהיותם בבחי' עם נק' עם סגולה וכמ\"ש והייתם לי סגולה מכל העמים כו' שלא יהי' בהם חילוף לעולם. וזהו כי לא יטוש ה' עמו לעולם ונחלתו לא יעזוב לעולם כי מה שבחר ה' בציון וביעקב אין זה פלא כ\"כ להיות שקדמו בבחי' העצמו' ופנימי' מצד שרשם הראשון. אך מה שבחר בעמו ישראל וכן מה שיבחר לנו את נחלתנו כו' דזהו כאשר נק' ישראל עבדים ואין מלך בלא עם העובדים אותו כו'. הנה גם בזה בחר בעמו ישראל ובנחלתו יעקב חבל נחלתו דוקא וזה קאי על מה שהקדים תחלה במ\"ש ה' מלך אבדו גוים מארצו דקאי לע\"ל באלף הז' שיהי' ה' מלך רק לישראל עמו כו' והוא מטעם הנ\"ל דאין לז' מלכין דתוהו שרש שם אחר שהפרידן כו' ואז יהי' בחי' גילוי עצמותו למטה כמו למעלה בעצמו' לפני הצמצום ושם דווקא יבחר לנו את נחלתנו כו' שיהי' יעקב חבל נחלתו מיוחדת לעצמותו כו' משום דבחר ה' בציון אוה למושב לו כו' וכמ\"ש כי לא יטוש ה' עמו כו' שלא כמו שהי' בבהמ\"ק ראשון ושני שנטש עמו ונחלתו ולע\"ל לא יטוש [לעולם] וכמ\"ש בדניאל וע\"י יתיב כו' וגם בעוה\"ב הרי יהי' נשמות בגופים ונקראים עמו אבל לא יטוש אותם לעולם להיות שלפני בוא יום הגדול יום שכולו טוב כו' ישוב לב אבו' על בנים ולב בנים על אבותם בבחי' התקשרות עצמיות הנ\"ל בענין כי בחר ה' בציון כו' וד\"ל:"],[2400650555,"<h3> והוא רחום</h3>\n(קנח) <b>והוא</b> רחום יכפר עון כו'. הנה לכאורה אין לפסוק זה שייכות לפסוקים שקודמים וגם בו לא נזכר שם הוי' כלל. אך הענין הוא בהיות מבואר בסידור בשרש ח\"י פסוקים דיהי כבוד כו' שהוא בחי' ח\"י הוויות דיסוד דצדיק ח\"י עלמין כו' ולהאיר בג\"ע שהוא בכ\"ב אתוון דתהלה לדוד כו' וכנ\"ל. וידוע דכל הוי' הוא בבחי' החסדים דדכורא (ועי\"ז נמשך בחי' חוליות דז\"א בח\"י ברכות דש\"ע וז\"ש לעולם יסדר אדם שבחו של מקום ואח\"כ יתפלל דהא בהא תליא וכן יש ח\"י הוויות בשירת הים) ועד פסוק כי לא יטוש נשלם עיקר עצם החסדים שנמשכו מחו\"ב ע\"י הדעת לנוק' (והן ב' פעמים ח' אותיות דהוי' ואדנ\"י שהן י\"ו) ופסוק זה דוהוא רחום הוא להמתיק הדינים דוקא שהוא ע\"י בחי' גבורות ממותקות דחסדים שביסוד כו' ושרשן נמשך מי\"ג מדה\"ר דכתר שהן י\"ג תיבות דאל רחום וחנון כו' והן י\"ג"],[2400650556,"תיבות והוא רחום כו' כשבא המשכת י\"ג מדה\"ר להמתיק כח הדין הקשה שנתהווה בפו\"מ כמו לכפר העוון שנעשה בפו\"מ שהוא המקטרג בפו\"מ וזהו בבחי' מל' דמל' דעשי' ע\"כ הוכן שרש להמתקה זו בבחי' צדיק ח\"י עלמין בפסוק זה והוא רחום כו' כדי שיומשך ממנו אור השפע ישועות וחסדים בלי תערובות דינים כלל והוא בפסוק שאח\"כ ה' הושיעה המלך יעננו כו' שהוא בחי' המשכת מ\"ד וכמשי\"ת וד\"ל. וביאור פסוק זה הנה מ\"ש והוא רחום לשון נסתר ולא הזכיר שם הוי' להיות ששרש י\"ג מדה\"ר הוא מבחי' פנימי' הכתר שלמעלה משם הוי' (וכמ\"ש במ\"א בענין כי ביום הזה יכפר סתם) והוא לנגד מ\"ש ויעבור הוי' כו' ויקרא אל רחום כו' וידוע שי\"ג מדות הרחמים העליונים הוא בעצמות רוממות אא\"ס מצד גדולתו דלכך נק' הוא לשון נסתר כמו אנכי [אנכי] מוחה פשעיך דכל המרומם יותר יותר ירחם (וכמ\"ש לכן ירום לרחמכם ואמר בזוהר שהוא בבחי' גלגלתא דא\"א כו'). אך הנה י\"ג תיבות הללו דוהוא רחום יכפר עון כו' הוא להמתיק הדינין שנתהווה בגשמיות שהוא בא מן העון בפו\"מ בגשמיו' כמ\"ש תייסרך רעתך ואין יסורים בלא עון שהעון הנעשה בפו\"מ הוא עושה רושם המשכת אותיו' רעים למע' ברוחניו' שממנו נברא כח הדין המקטרג הרע שנק' רצועא לאלקאה בפו\"מ והוא המייסרו עד שממית כמ\"ש תמותת רשע רעה (כמ\"ש במ\"א בענין מחוק ברחמיך הרבים כל שטרי חובותינו). והנה כאשר מלקין את החוטא בב\"ד ל\"ט מלקות שמשלשין ההכאות ואומרי' י\"ג תיבות דפסוק והוא רחום כו' הרי בזה יכופר עון החוטא וכמ\"ש ונקלה אחיך כיון שנקלה הרי הוא כאחיך ממש ונמצא אין ההכא' הזאת דין ומשפט ועונש כדבר הממית ומכלה אדרבה מתקן במה שמסיר הרע והמות ומצילו ממות לחיים ממש ונק' גבורות ממותקות בחסדים והיינו כשאומר פסוק זה כל תיבה ותיבה תיקון מיוחד להמתיק הדין הקשה שנעשה בפו\"מ שהן י\"ג מדה\"ר שמשלשלין אותו נגד צלם אלקים שפגם כו' למלאות החסרון והפגם ובאמת עיקר כחה של י\"ג מדה\"ר העליונים שלמעלה אינו נראה רק בבוא המשכת שפעם עד למטה מטה עד הנפש החוטאת שבגוף גשמי לכפר עון הנעשה בפו\"מ להמתיק כח הדין הקשה שמייסרו בפו\"מ זהו הורא' גמורה על גבורות כח החסדים שברחמים לעמוד גם נגד הדין הקשה הבא בהגשמה להעבירו ולמוחקו כו' וכך יובן בענין פסוק זה באמרו והוא רחום היינו כמ\"ש הוא מוחה פשעיך דווקא דכל הגבוה יותר יותר גדול כחו לבוא למטה לכפר עון שבפו\"מ שהוא נעשה למטה מאוד כו' והמשכת י\"ג מדה\"ר הללו נמשכים מפנימי' המו\"ס דא\"א דאצילות עד מל' דאצי' בבריאה ומל' דבריאה ביצירה ומל' דיצירה בעשי' עד מל' דמל' דעשי' למט' ברחמנו' על החוטא בפו\"מ"],[2400650557,"לכפר על עונו לגמרי וקטיגור שלו נעשה סניגור כו' וזהו ולא ישחית דקאי גם על העוון שלא ישחית המקטרג הבא מן העון כי נהפוך מדין לחסד כנ\"ל וד\"ל. והרבה להשיב אפו ולא יעיר כל חמתו. הנה לכאורה אין זה מובן אם יש בכח הרחמנות כ\"כ להשיב אפו וחמתו שכבר יצא לדין ועונש להחזירו לטוב וחסד כמו קריעת גזר דין קשה של ע' שנה שקורעין למי שעשה תשובה כו' שמשיב את שלוח האף וחימה א\"כ ק\"ו הוא שלא יעיר כל חמתו בתחילה לעורר את החימה ואף שזה הרבה יותר בנקל כו'. אך הנה כתיב טוב ארך אפים מגבור כו' שהמאריך אפו היינו כמו המושל וגובר ברוחו לעצור ולכבוש כח הכעס וחרון ולא יחרה אפו כלל מכל מה שיכעיסוהו כי החרון והכעס הוא באף והסובל ומתיישב ברוח אפו לסבול החרון ולקבל ברצון נק' מאריך אפו וקצר אפיים הוא להיפוך שנוח לכעוס מיד ולא יוכל למשול ברוח אפו כלל כו' ושרש הדברים דנשמת רוח החיים שבאפו דווקא בב' נקבים הוא מבחי' חי' יחידה שבנפש שלמעלה מכל כוחות הנפש כרצון ושכל כו' כך בחוטם יש בו ב' הפכים דחו\"ג לתכלית העומק שבעצמות הנפש ממש כמו הכעס וחרון אף שמגיע גירעון בעצם הנפש ולהיפוך בהמתקת חסד וטוב יתפעל כל עצם הנפש כמו מריח הטוב וכמו ישימו קטורה באפיך כו' ותהלתי אחטם לך כו' וא\"כ כאשר יכבוש החרון שבאף ויהי' מאריך אף כנ\"ל זהו מגבורות עצמות הנפש בכל עוז כחה שלמעלה מן גבורות כל כוחות המתפשטי' ממנה וז\"ש טוב ארך אפים מגבור ממש וד\"ל. ולפי\"ז יובן ג\"כ מ\"ש והרבה להשיב אפו שזהו כאשר מנחם על הרעה מצד התגברות עצמות כח החסדים והרחמים כאב לבן כמ\"ש המו מעי לו רחם ארחמנו כו' אז ישיב אפו הגם שכבר נגזר למעלה ישוב ויחזירם להפכם מדין לחסד כמו ישוב ירחמנו כו'. אך כ\"ז מצד כח וגבורות הרחמים שכובשים לאף ומשיבו כמו ארך אפים שסובל מתחלה וזהו למעלה ענין ובחי' מדות הוי' המסתעפים מארך אפים ורב חסד כו' שע\"ז נאמר טוב ארך אפים מגבור כנ\"ל. אמנם כח וגבורה זו יש לה סוף כמו מאריך אף לרשעים עד שיהי' קץ לדבר שלא יוכל כח החסד לעצור ולסבול כו' משא\"כ כשלא יעיר כל חמתו בתחילה הוא למעלה ממדת ארך אפים כו' שהרי מה שלא מעורר לכל חמתו כלל זהו רק מצד עצם טובו ורחמנות העצמיות שבו כמו המו מעי לו רחם ארחמנו כו' שהרחמנות עצמיות ממש ולא מצד כח וגבור' החסדי' הרבי' המושלים לפי שעה לעמוד נגד הדין וחרון כו' וזהו ולא יעיר כל חמתו בתחלה שאם יעיר כל חמתו אין כח בחסדים לעמוד לנגדם כלל ע\"כ לא יעיר כל כח חמתו בתחלה וזהו רק מצד עצמיות הרחמים והוא לנגד אל רחום וחנון בעצם שלמעלה מארך אפים ולכך בא בפסוק זה"],[2400650558,"בתיבות האחרוני' דלא יעיר כל חמתו דזהו הכלל בכל דבר עליון הנמשך למטה דמה שבא ראשון למעלה בא אחרון למטה במקבל כמו חותם המתהפך כמ\"ש במ\"א וד\"ל. ה' הושיעה המלך יעננו ביום קראנו. הנה הפסוק הזה האחרון הוא תכלית אור השפע דצדיק עליון ברב חסד שנק' ישועות וכמ\"ש דוד כוס ישועות אשא כו' כוס מלא ישועות וחסדים עליונים דהוי' דז\"א וכמ\"ש אני המדבר בצדקה ורב להושיע. דהנה הישועה עיקר ענינה לעמוד לנגד המנגד ולהושיע מידו כמו ויושע ה' ביום ההוא כו' וכן ישראל נושע כו' הרי מקבלי' התשועה מן המושיע העליון שנק' רב להושיע. וזהו ה' הושיעה להמשיך הישועה לכנ\"י מבחי' ש\"ע נהורין העליונים כמ\"ש יאר ה' פניו כו' והוא להיות שהארת הפנים ממתיק כל דין ומושיע בתגבורת גדולה ולכך נכלל בפי' הושיעה זה מענין וישע ה' אל כו' ובתפלתם שעה ש\"ע נהורין וזהו ה' הושיעה כו' שהוא תכלית כל החסדים העליונים שבהוי' דז\"א כו' (והוא מבחי' תגבורת החסדי' שביסוד לאחר המתקת הדינין להיות תשועה בפו\"מ מדין לחסד. וזהו ענין ברכות אתה גבור כו' שהוא בחי' גבורות שבחסד בחי' יצחק שהיא למעלה מחסדים דאברהם כמ\"ש בענין כי אברהם לא ידענו כו' וז\"ש ועלו מושיעים בהר ציון כו'). המלך יעננו כו'. והנה יעננו ביום קראנו ר\"ת יב\"ק כמ\"ש בסידור דהנה הפי' הפשוט דיעננו ביום קראנו היינו שבאותו יום שקראנו יעננו מיד ולא יתאחר העניי' אחר הקריאה זמן מה אלא יעננו מיד ביום קראנו וזהו מעלה יתירה שמיד אחר ההעלאה תהי' ההמשכה ולא תתעכב ההמשכה זמן רב. והענין הוא כידוע דרוח אייתי רוח ואמשיך רוח והוא בחי' העלאת מ\"ן שגורם המשכת מ\"ד ויש בזה ב' אופנים הא' שבהמשכה לא תהי' מיד אחר ההעלאה וכמו השואל ומבקש דבר מן המלך שלא ישיב לו מיד כי אם יתן הדבר במשפט לדונו לפי מעשיו אם ראוי למלאות שאלתו והיינו לפי אופן בחי' העלאת מ\"ן באותה שעה דרוח אייתי רוח כו' וכמ\"ש יהי חסדך ה' עלינו כאשר יחלנו לך דווקא כמים הפנים לפי ערך הקריאה כו' ואעפ\"י שנאמר אם [ישים] אליו לבו ורוחו כו' דודאי כל העלאה גורם המשכה אבל יובא הדבר במאזני צדק כו' שנק' נו\"ה ושרשו בחו\"ב שברצון להטות לחסד או לדין ולכך יוכל להתעכב מהילוך ההמשכה משכל למדות הרבה עד שיומשך למעשה בחסד בפו\"מ לענות לו על שאלתו. אבל אופן הב' הוא שלא יובא השאלה ובקשה במשקל מאזני השכל ע\"פ משפט אופן של העלאת מ\"ן אלא מיד ישיבוהו לטוב וחסד בלי שיקול הדעת לראו' בדבר שאלתו כמו תפלת דרחב\"ד כו' והוא מפני שנמשך מיד מעצמות הרצון שלא בא בהגבלת טעם לרצון"],[2400650559,"לכך ממשיך מיד בלי עיכוב בדבר כלל והוא עיקר ענין צלותא דמסכונא שמיד שיצעק ישמעו לו כו' וכן יעננו ביום קראנו דקאי ארישא דיענך ה' ביום צרה כו' וגם נאמר טרם תקרא ואני אענה כו' דיוכל להיות זה גם לא מצד הקריאה בצר לו או בעת צרה שמגיע בעצם הרצון אלא מצד המשפיע שמאיר מהארת פנים מצד העצמות והוא בבחי' ש\"ע נהורין וכמ\"ש ה' הושיעה ע\"כ המלך יעננו ביום קראנו כי באור פני מלך כו' וזהו ר\"ת יב\"ק \"יחוד \"ברכה \"קדושה שלמעלה מהעלאת מ\"ן והמשכת מ\"ד וכמ\"ש במ\"א בענין עתידה אשה שתלד בכל יום כו' וד\"ל:"],[2400650560,"<h3>אשרי יושבי ביתך</h3>\n(קנט) <b>אשרי</b> יושבי ביתך עוד יהללוך סלה אשרי העם שככה לו אשרי העם שה' אלהיו. הנה ב' פסוקים הללו סידרום אכה\"ג להיות פתיחה והכנה לכללות פסוד\"ז ומ\"ש אותו לפני המזמור דתהלה לדוד דוקא לפי שהעיקר בפסוד\"ז הוא מזמור זה דתהלה לדוד שהוא בא\"ב כידוע כי הוא כולל כל הללויה באמרו תהלה לדוד שהוא בבחי' כתר שכולל הא\"ב ושרש הדברים להיות שכל עיקר כללות ענין פסוד\"ז הוא בהללוי' להיותו בבחי' תוס' אור בשם הוי' כי הלל זה מלשון בהלו נרו עלי ראשי כו' כמ\"ש במ\"א באריכו' בענין הלל ברכה והודא' וכמ\"ש רוממו' אל בגרונם בחי' הרוממות והוא השבח וההלל שבפסוד\"ז הוא ממשיך בחי' תוס' אור בכל שם הוי' והעיקר באותיות י\"ה דהוי' כמ\"ש הללוי' וע\"כ מסיים בהללוי' שזהו העיקר כידוע ומבואר במ\"א. ולזה הקדים למזמור זה דתהלה לדוד ב' פסוקים דאשרי שהוא בבחי' אור הכתר שמשם מקור מוצא תוס' אור זה בשם הוי' כידוע דהוי' בחכ' והחכ' מאין כו' וזהו פי' אשרי כמו באשרי כו' והוא בחי' התענוג שברצון שמאיר בקוצו של יו\"ד דהוי' כו' והוא מקור המוסיף אור בהללויה ולזה א' אשרי יושבי ביתך עוד יהללוך סלה בלי הפסק כלל כו' וד\"ל. ומ\"ש יושבי ביתך דוקא והפשוט הוא דאשרי היושבים בביתך דוקא שהמה דוקא יהללוך סלה. הענין ידוע שהאותיות נק' בתים כמ\"ש בס\"י ה' אבנים בונות ק\"כ בתים כו'. ומבואר במקום אחר ע\"פ אחת שאלתי כו' שבתי בבית ה' כו' שאז ממילא נמשך כל המקיפים שבכתר שהוא לחזות בנועם ה' וכך כאן בחי' האותיות דפסוד\"ז שאו' בפה שנק' אבנים ומצירופיהן נעשו בתים נק' יושבי ביתך שבהן דוקא ישכון אוה\"מ דכתר שהוא ענין אשרי מעולם התענוג שבעצמות שלמע' מן החכ' וטעם שהן רק בחי' הכוונות שבהשגת אלקות בשבחי' הללו כו' וזהו ענין התוס' אור בשם הוי' שהוא בי\"ה חו\"ב מאוה\"מ דכתר דוקא ע\"י שהן יושבי ביתך דוקא ע\"כ עוד יהללוך סלה בלי הפסק כי יש באור הכתר מבחי' האחרונה שבעולם הא\"ס כידוע ומה שנקרא הלל מלשון בהלו נרו כו' א\"ז מצד עצם השבח וההילול שבא"],[2400650561,"בשכל וטעם ההשגה אלקי' שבשבח והלל זה רק מצד בחי' אותיות הדבור שמדבר ומשבח בפה שאותיות הללו מגיע שרשם בבחי' מקיף דכתר כידוע בשרש כ\"ב אותיות מצד עצם מהותן שהוא בבחי' הכתר דהיינו כמו באדם למטה והוא בבחי' יחידה שלמע' מחכ' שבה כו' וזהו ענין אשרי ג\"פ שהזכיר כאן שהן שרשים ומקורים לכללות פסוד\"ז שבדיבור ובפרט למזמור זה דתהלה לדוד שהוא כולל כל כ\"ב אתוון דמל' שהוא בבחי' כתר דמל' דיצי' כו' (ושרשו בבחי' כתר דיצי' עצמו כמ\"ש בסידור וע\"כ כולל כל ט\"ס שהן ט' הויו' הנזכ' במזמור זה ומ\"ש ג\"פ אשרי נגד ג' עולמות בי\"ע ואשרי אותיות שאר יו\"ד ושאר יו\"ד הוא המשכת שאר לנוק' שהן המזונות כמו המשכת מ\"ד בח\"י ברכות דש\"ע שנק' עונתה ושאר דמל' דעשי' שנמשך מכתר דעשי' היינו אשרי הא' דיושבי ביתך שהוא בית אלקי' דעשי' ואשרי הב' אשרי העם כו' בחי' שאר דמל' דיצי' שנמשך מכתר דיצי' ואשרי הג' אשרי העם שה' אלקיו הוא שאר מל' דבריאה מכתר דבריאה כו' וכללות הענין הוא אור הכתר במל' בבחי' שאר והוא כמו המזון שמוסיף אור חיות הנפש בגוף כך יומשך תוס' אורות ומוחין באו\"א וזו\"נ שהן ד' אותיות דהוי' ע\"י אור הכתר דוקא בג' עולמות דבי\"ע וד\"ל). (ופי' הפשוט דיושבי ביתך קאי על בית התפלה ששם דוקא יהללוך סלה ששם מאיר בחי' מקיף למקיף דרצוה\"ע כמ\"ש במ\"א בענין מזון לבוש בית ע\"פ מזמור שיר חנוכת הבית). אשרי העם שככה לו. הנה שככה גי' משה משום דאתפשטותי' דמשה בכל דרא כו'. והיינו שככה לו כי ככ\"ה גימט' מ\"ה והוא גילוי אור שם הוי' דז\"א שהוא פנימי' ומקור דכנס\"י ששרשן בשם הוי' כמ\"ש כי חלק ה' עמו כו' וכמ\"ש בסיפא אשרי העם שה' אלקיו כו' ולהיות כי ידוע דכמו דבפסוד\"ז עיקר ההילול הוא להוסיף אור בהוי' למע' כך הוא הוספות אור בהוי' ששוכן בנש\"י כמ\"ש כי נר הוי' נ\"א להאיר אורה מן החושך דקליפה משכא דחויא שבחומר הגוף המסתיר כמ\"ש רוממות אל בגרונם וחרב פיפיות בידם ולכך נק' פסוד\"ז לשון זמיר עריצים להכרית יניקת הקליפות כו' (וכמ\"ש שם באריכות) וכמ\"ש כי אתה תאיר נרי וה' יגיה חשכי כו' ולהיות שאין חבוש מתיר את עצמו כו' ואיך יאיר תוס' אור בהיר בנשמתו בשם הוי' שבה א\"ז אלא מאור שם מ\"ה שבשם הוי' למע' דידוע דשם מ\"ה מלגאו איהו אורח כל האצי' כו' והיינו שממנו יהי' מקור מוצא לבחי' כח מ\"ה בחי' הביטול בכל נפש מישראל הגם שאין לו רק בחי' נפש דעשי'. וזהו אשרי העם שככה לו ככ\"ה בחי' מ\"ה בבחי' כ\"ף הדמיון שדומה לבחי' מ\"ה העליון דהוי' דאצי' כמ\"ש מה שמו ומה שם בנו כי נש\"י נק' בנים כידוע. ואמנם אע\"פ שנק' עם מאיר בהם מהארת שם מ\"ה משום שאין בהם בחי' נפרד כעם ממש וכמ\"ש"],[2400650562,"וכי ימכור איש את בתו כו' לא תצא כו' אע\"פ שנקר' עבדים כמ\"ש כי לי בנ\"י עבדים ולכך אומ' אבינו מלכנו כידוע וז\"ש אשרי העם לרבותא דאע\"פ שהן עם מ\"מ אשרי העם שככה לו שמאיר בהם מבחי' מ\"ה דמשה בכל דור להיות בהם בחי' הביטול בכ\"ח לפושי\"ד (וראי' ממס\"נ על קדה\"ש שהוא מבחי' כח מ\"ה שבנפש כמ\"ש בלק\"א) ובזה הפ' נעשה הכנה לבחי' הילול דפסוד\"ז להיות תוס' האור בא בגילוי בכלי מן ההעלם והיינו פי' שככה לו דלו לשון נסתר והוא שרשי' הכללי' דס\"ר נש\"י בו\"ק דז\"א ו\"פ ו' גימט' ל\"ו וכלולי' בי\"ה שנק' שבטי יה שנא' הנסתרות כו' ושככה לשון גילוי כמ\"ש במ\"א בענין מה ראו על ככה ומה הגיע אליהם דמ\"ה דחכמה בא בגילוי על ככה דמל' שנק' ככה כ\"ה בכ\"ף הדמיון כו' וזהו ג\"כ שככה לו וד\"ל. אשרי העם שה' אלקיו. הנה בזה המאמר בא לומר רבותא גדולה יותר ממ\"ש שככה לו והוא במה שהוי' אלקיו כמ\"ש יעקב כמו והי' הוי' לי לאלקים דוקא וא\"ז המע' רק בעם ה' שה' אלקיו וכמ\"ש ה' אלקיו עמו ותרועת מלך בו. ובה\"ד הנה ידוע ומבואר במ\"א בענין מי כמוכה באלים הוי' כו' דבחי' הת\"ת שהוא בהוי' אין הכלי מסתיר את האור כלל ובחי' אלקי' שבו שהוא בחי' הכלי שוה עם בחי' האור שבו שהוא בחי' הוי' כי מדה זו היא מדת הת\"ת באו\"כ שבה נבדל משאר המדות כחו\"ג וכה\"ג שהכלי שבחסד מסתיר לאור כי הכלי הוא בחי' הגבלת האור ובחי' הישות שלו כשבא לגילוי שפע כידוע ואור שבה נק' בחי' אין כו' וכן מדות הגבו' והנצח וההוד וכה\"ג אבל מדת הת\"ת אעפ\"י שהוא ג\"כ באו\"כ וכל כלי מגביל [ומתאר] לאור בבחי' יש כו' מ\"מ אין הכלי בחי' יש להסתיר לאור כלל אלא הכלי ג\"כ בבחינת אין ממש כמו האור שבה ונמצא בחי' אלקי' שהוא הכלי שוה עם בחי' הוי' שהוא האור ממש. וזהו ה' אלקיו עמו וכן שהוי' אלקיו דהוי' שהוא האור הוא אלקיו בחי' הכלי כולא חד בלי הפרש כלל ביניהם כו' עד שיוכל להיות שם שם הוי' בבחי' אלקים ממש מפני שאינו בחי' אלקים המצמצם ומסתיר כלל וכמ\"ש יעקב והי' הוי' לי לאלקים דוקא משום דשרש יעקב בבחי' הת\"ת דז\"א כידוע וד\"ל. וטעם הדבר מבואר במ\"א (בענין ו' דוהנורא) לפי שבמדת ת\"ת יש בחי' אין העליון דכתר שלמעלה מהתחלקות קוין בגילוי גמור שהרי סובל ב' הפכים דחו\"ג שא\"ז רק מצד היות שרשו בבחי' אין הנעלם דכתר שהוא למעלה מב' הפכים דחו\"ג כו' והת\"ת בא בגילוי מדה ע\"כ גם בבחי' הכלי שבו הוא בא בגילוי בלי הסתר כלל ואין ויש דאו\"כ שלו שוין ממש כו' כדוגמא דאין ויש שלמעלה מן הטבע בטבע כמקום שנעשה בו נס וכמקום ארון אינו מן המדה וכמ\"ש במ\"א באריכות). וכך יובן כאן בשרש"],[2400650563,"ישראל למעלה להיותם בבחי' ת\"ת דז\"א וכמ\"ש ישראל אשר בך אתפאר אע\"פ שהן בבחי' כלי' דנה\"י דת\"ת כו' אבל בחי' אין דפנימי' הכתר שהוא מעצמות המאציל מאיר שם כמו באור עצמו כו' ולכך גם בנש\"י בהיותן מוגבלים בכלי הגוף בנה\"ט מאיר בהן מבחי' מ\"ה דהוי' שבאור כמו בשרש אור נשמתם למעלה ממש וז\"ש אשרי העם נשמות שבגופים שה' אלקיו בבחי' כלי שאין הכלי מסתיר ע\"כ בחי' הוי' לו בבחי' אלקים משא\"כ זולתם שמקבלים מאלקי' המסתיר בחו\"ג שכלים שלהם מסתיר ומעלים עד שאברהם יצא ממנו ישמעאל כו' (ולזה א' כולך יפה רעייתי ומום אין בך גם מצד הכלי של הנשמה האלקי' כמ\"ש ב\"ה כלה נאה וחסודה ואע\"פ שהיא חגרת וסומא מצד הגוף מטעם הנ\"ל) וזהו ענין ג\"פ אשרי הא' בחי' נפש דעשי' והב' בחי' רוח דיצי' והג' בחי' נשמה דבריאה ובכל א' הכלי שוה עם האור כידוע דל' כלים דנה\"י דת\"ת דז\"א נעשי' נר\"נ בבי\"ע והן ס\"ר שרשים כו' ובעשי' אמר אשרי יושבי ביתך בחי' עשי' שבדיבור בפה וביצי' א' שככה לו ובבריאה אמר שה' אלקיו וד\"ל:"],[2400650564,"<h3>תהלה לדוד ארוממך</h3>\n(קס) <b>תהלה</b> לדוד ארוממך אלקי המלך. הנה מבואר בסידור דתהלה לדוד הוא בבחי' כתר דיצירה והוא בבחי' כתר מל' דיצירה משום שנסבת\"ח דכתר מל' איהו כתר עליון בכל מקום ועיקר תהלה לדוד מדבר בשרש המל' דדוד איך שהוא בבחי' הכתר דוקא ע\"כ אמר תהלה לדוד ארוממך אלקי המלך המרומם לבחי' אלקי המלך בשרשו שהוא בבחי' הכתר עליון ומשום דנתחב\"ס וסוב\"ת ולכך ארוממך אלקי המלך כו'. ולהבין זה יש להקדים תחלה בבחי' הכתר עצמו שכלול מי\"ס ובחי' האחרונה שבו הוא בחי' מל' שבכתר והוא המתלבש בנאצלים ובחי' הראשונה שבו הוא בחינת הכתר שבו ונק' כשב\"כ ונחשב מבחי' האחרונה שבעצמות המאציל כידוע דכתר נק' ממוצע בין עצמות המאציל לנאצלים וענין נתחב\"ס וסוב\"ת היינו גם בבחי' הכתר עצמו דתחילתו שהוא בחי' כשב\"כ נעוץ בסופו דוקא שהוא בחי' מל' שבכתר דהיינו דתחלת אור הכתר אינו מאיר בגילוי רק בסופו במל' שבו דוקא וכן נסוב\"ת דמל' שבכתר בכשב\"כ דוקא כו' כי כמו שנתחב\"ס כך ממש נעוץ סוב\"ת וע\"כ נק' אות הכ\"ף כפופה דכתר כתר מל' דוקא וכן בבחי' המל' דאצי' סוף כל המדרגות אמר דכתר מל' דוקא איהו כתר עליון דהיינו בחי' כתר מל' נעוץ בבחי' כשב\"כ שבתחלתו דכמו דנעוץ סופו שבו בתחילתו כך במל' סוף הכל כו' וד\"ל. ולהבין ביאור כ\"ז הנה ידוע ומבואר בטעם שהרצון נק' כתר מלשון כותרת ומקיף כו' לפי שהרצון בעצם הוא למעלה מן השכל והטעם שבמוח הראש ע\"כ נקרא כותרת כעצם הגולגולת המקפת המוחין שבו וז\"ש כצנה רצון תעטרנו כו' וכנראה ברצון אדם התחתון למטה שעצם"],[2400650565,"ומהות הרצון אין לו טעם כלל רק שרוצה כך בלא טעם כי אין טעם לרצון כו'. אך א\"כ איך יוכל להיות בכתר התכללות דע\"ס שזהו חכ' ומדות שברצון הענין הוא דחכ' שבכתר אינו נק' שכל וטעם לגלוי רצון דודאי אין טעם גילוי לרצון אלא הוא טעם כמוס והוא העלם הטעם להיות לו התעוררות לרצון זה (וכמ\"ש במ\"א בענין שאמר גבי ר\"ע וכי זו תורה כו' והשיב לו שתוק כך עלה במח' לפני כו' פי' מחשבה הוא הרצון כי הרצון ומחשבה אחד הוא כידוע). והנה מבואר בזוהר שיש תחלה דמחשבה וסופא דמחשבה שהוא בחי' כתר שברצון ומל' שברצון ונק' מחשבה סתימאה ומחשבה הגלוי' כי תחלת הרצון הוא בהעלם עצמותו ובא לידי בחי' התפשטות ואז כלול מט\"ס חב\"ד ומדות כו' עד בחי' גילוי הרצון לבא לידי מעשה בפו\"מ שזהו בחי' מל' שבכתר ונק' סופא דמחשבה כמו כאשר עלה ברצונו להטיב חסדו ונק' חפץ חסד ונק' תחלת הרצון וגילוי אור החסד ברצון זה נק' סופא דמחשבה וכך הוא בתחלה וסוף דכתר מל' שבמדות המל' כאשר עלה במח' תחלה ורצון אנא אמלוך כו' נק' כתר ובחי' גילוי אור הרצון במל' נק' מל' שבכתר וכן עד\"ז בכל רצון בפרט ומפני שהכל בחי' הרצון עצמו עדיין נקרא התחלה שבו כשב\"כ והסוף שבו בחי' מל' שבכתר מאחר שכל עיקר הרצון נק' בשם כתר להיותו בעצם למעלה מן השכל וטעם כמו שברצון בפרט הבא באיזה מדה בפרט כמו במדת החסד או במדת המל' וכה\"ג כך הוא ברצון הפשוט ההיולי כלול מע\"ס ראש תוך סוף כו' ובדרך כלל היינו בחי' הרצון הנעלם בעצמו שכלול מתחלה וסוף שנק' תחלת המחשבה וסופא דמחשבה וכאשר אמר נתחב\"ס וסופו כו' היינו בחי' הרצון עצמו שעיקר שלימות התחלה שבו נעוץ בסופו שהוא בבחי' הגילוי שבו הנק' סופא דמחשבה וסופו נעוץ בתחלה ומה שהוא בתוך ואמצע שהוא בחי' חכ' ומדות שבו אינו אלא דרך מעביר שבהן ועל ידן יבא לסופא שהוא העיקר כו'. וכ\"ז דמיון להבין למעלה בבחי' הכתר עליון בכלל שנק' ממוצע בין עצמות המאציל עם הנאצלים שזהו כאשר עלה ברצונו להאציל נק' תחלה דמחשבה ונחשב מבחי' האחרונה שבעצמות ומה שנגלה אור הרצון שנק' בחי' מל' שבו הוא עיקר להשתלשלות הנאצלים ונתחב\"ס וסופן כו' וכך יובן ברצון הפשוט בעצמו לבחי' המל' שעבמ\"ח כו' הרי בחי' מל' זה שבכתר נעוץ בתחלתו ותחילתו כו'. וא\"כ יובן מזה גם בע\"ס הגלויות מן העלם עצמותו שנק' ע\"ס דאצי' כידוע דבחי' מל' דאצי' שהוא סוף הכל כידוע נעוץ בו התחלה שהוא הכתר דאצילות שהוא בחי' הרצון הגלוי מן ההעלם כו' ובחי' חב\"ד ומדות דאצילות אינו אלא בחי' מעביר שיבא ע\"י לסוף המח' והרצון הזה שהוא בחי' מל' דאצילו' ולפי\"ז יובן ג\"כ במדות מל' דאצי' שכולל מע\"ס רצון ושכל"],[2400650566,"ומדות כו' שבחי' מל' שבמל' נעוץ בתחלתו בבחי' כתר מל' שהוא בחי' רצון שבמדה זו ושרש רצון זה הוא נעוץ בכתר שבכתר עצמו שזהו תחלת עצם רצונו שבעצמותו בהעלם שעלה במחשבה למדה זו דמל' בעצמו טרם שבא לגילוי להיות שרש לנאצלים והיינו מ\"ש דכתר מל' דוקא איהו כתר עליון שהוא בחי' כתר שבכתר והיינו הך ממש וד\"ל. והנה מעתה י\"ל בפי' ארוממך אלקי המלך דהנה לכאורה בפי' ארוממך יש ב' פי' שהם ב' הפכים ממש דהלא אמיתית הענין בתיבת ארוממך קאי ודאי על בחי' עצמות הרוממות שנק' רוממות אל כו' ונק' מרום שהוא בחי' אור הכתר עצמו שהוא מרומם ומתנשא מימות עולם וכמ\"ש בע\"ח דאור הכתר עצמו אינו נמנה בכלל הי\"ס כו' והיינו בחי' ג\"ר כח\"ב שבו עד בחי' מל' שבו שאינו מלובש בנאצלים כלל ונחשב הכל מבחי' האחרונה שבעצמו' כנ\"ל שהוא בחי' כתר שבכתר כנ\"ל ואין לנאצלים ערך לו כלל וכלל דהיינו כמובן מענין הנ\"ל בבחי' הרצון שבהעלם עצמו טרם שבא לידי גילוי שנק' תחלת המח' שאין טעם גילוי לרצון כלל ולא ישיגנו הטעם ושכל לעולם כו'. וכך אין לחכמה דאצילות שהוא כמו בחי' שכל וטעם גילוי ערך לו כלל ומכ\"ש שאר הספי' דאצילות הנאצלים כו' וא\"כ פי' ארוממך היינו ברוממות לרוממות מאחר שארוממך לרוממות אל דכתר עצמו והענין הוא דבחי' פנימי' הכתר שנק' כתר שבכתר עד המל' שבו שנחשב מבחי' אחרונה שבעצמות אע\"פ שנק' מרומם ומובדל בערך ומתנשא מימות עולם שהן הנאצלים עכ\"ז אינו רק בחי' אחרונה שבעצמות כמו עד\"מ גם תחלת הרצון ומח' שבעצמות שכלא חשיב לגבי עצמותו ממש ולזה שייך בחי' רוממות לרומם גם לאור פנימי' הכתר לבחינת העצמות ממש וכמ\"ש דגם אור צח ומצוחצח אוכם הוא לגבי עילת העילות כו'. ולזה אמר ארוממך לכתר עצמו להיות עולה ברוממות העצמות דא\"ס ממש וזהו פי' הא' בארוממך. ויש עוד פי' בארוממך זה היפך פי' זה ממש. דהנה לכאורה יש סתירה גדולה על פי' הא' שהרי אנו אומרים המלך המרומם לבדו כו' וכן ה' מלך גאות כו' וכה\"ג דמשמע שכל בחי' רוממות והתנשאות וגיאות אינו אלא מבחי' המל' דוקא שההתנשאות וההבדלה ורוממות הערך אינו אלא כמלך על עם כידוע. ולפי\"ז כאשר אנו אומרים המלך המרומם כו' מתנשא מימות עולם הנאצל דקאי ודאי על בחי' מל' הרי זה בהכרח בבחי' מל' שבכתר עליון הנקרא ממוצע כנ\"ל להיות דגם שהוא בחי' האחרונה שבכתר עליון ונקרא סופא דמחשבה סתימאה שבעצמות הנ\"ל מ\"מ נקרא מרומם ומתנשא מימות עולם הנאצלים דבחי' מל' שבעליון נעשה כתר לתחתון כו'. ולפי\"ז ארוממך אין הכוונה לרומם אותו לבחי' העצמות אלא ארוממך על העולם שלמטה הימנו"],[2400650567,"היינו מ\"ש ארוממך אלקי המלך דוקא מפני שבחי' המל' הוא המרומם דוקא וא\"כ פי' זה היפוך הפי' הא' דלפי פי' הא' בחי' המל' שבכתר שנקרא סופא דמחשבה בא בגילוי ובהתלבשות בנאצלים ונקרא מקור להם ולא ברוממות והסתלקות כו'. וראי' לפי' זה הב' דקאי ארוממך על בחי' מל' שבכתר דוקא ולא על בחי' כתר שבכתר הנה אנו רואים שיש כ' פשוטה בארוממך וידוע דכ\"ף פשוטה הוא מל' שבכתר וכ\"ף כפופה הוא כתר שבכתר להיות שהפשיטות למטה מטה מורה על בחי' ההתגלות וההתפשטות מגבוה לנמוך הוא גילוי רצון שנקרא סופא דמח' שבאה למטה מטה דוקא וכ\"ף כפופה הרי הכפיפות הוא ענין מורה עצם העלם הרצון שהוא כפוף בלתי התפשטות והתגלות למטה כלל זהו בחי' כשב\"כ שכולל ט\"ס בהעלם עד בחי' המל' שבו כידוע. ולפי\"ז ך' פשוטה דארוממך מסייע לפי' הב' דקאי על בחי' מל' שבכתר דוקא שבא בגילוי למטה. אך באמת גם בזה עצמו יש סתירה מיני' ובי' דאם עיקר הכוונה על בחי' מל' להיותו בחי' הגילוי למטה שלזה מורה אות הכ\"ף פשוטה דוקא אם כן לשון ארוממך שהוא בחי' התנשאות והסתלקות בהעלם עצמותו שמרומם לבדו כו' היפך הגילוי וירידה למטה. ועוד יקשה בזה שהרי ידוע שכל ך' פשוטה מורה לנוכח דוקא כמו וישמחו בך אברכך ואגדלה שמך וכן מלכותך כו' וגם ארוממך קאי לנוכח שמדבר למי שעומד לנגדו בגילוי דוקא וזהו ודאי בבחי' המל' שבכתר בחי' אחרונה שבו ובאמת עיקר שם הכתר הוא באות הך' שבו שהוא כ' כפופה דוקא ובראש האותיות דכתר ובכאן א' ארוממך לנוכח בך' פשוטה והוא בסוף האותיות שהוא רק בחי' מל' שבכתר ואיך נקרא כתר מלשון כותרת ומקיף להיות נקרא מלך מרומם ואיך יאמר בו לשון ארוממך על עולם הנאצל דלכאורה הרי יש בזה תרתי דסתרי אהדדי לגמרי וד\"ל:\n(קסא) <b>אך</b> הנה ע\"פ הקדמה הנ\"ל הרי ב' הפירושים הנ\"ל בארוממך שניהם אמת ואינם ב' הפכים כלל. וגם בענין ך' פשוטה דארוממך בפי' הב' ג\"כ אין זה ענין תרתי דסתרי אהדדי כלל והכל ענין וכוונה א' והא בהא תליא והכל ענין א' ממש. דהנה מבואר למעלה בענין נתחב\"ס וסופן כו' בבחי' הכתר עצמו שכלול מי\"ס דתחלת הכתר אינו מאיר רק בסופו דוקא והוא להיות שתחילת הרצון הנעלם עיקר שלימותו הוא כשבא לידי גילוי בסופא דמחשבה דוקא שנקרא מל' שבכתר ולפי\"ז הרי בבחי' מל' שבכתר מאיר מבחי' כשב\"כ דוקא וא\"כ בבחי' מל' שבכתר שהוא מקור לנאצלים שלזה מורה ענין הך' פשוטה דארוממך בבחי' התפשטות למטה דוקא שם דוקא נעוץ התחלה שנקרא כתר שבכתר שהוא באמת מובדל ומרומם מימות עולם הנאצל כנ\"ל. והיינו"],[2400650568,"פי' הב' דלעיל בענין ארוממך לבחי' מל' שבכתר דוקא שהוא מרומם לבדו כמו בחי' כתר עליון שנקרא כתר שבכתר ולזה אמר ארוממך אלקי המלך דוקא וכמ\"ש המלך המרומם וכן ה' מלך גיאות לבש כו' שמבחי' המל' דוקא הוא הרוממות וההתנשאות מצד שרשו בכתר עליון ונק' כתר מל' בכ' כפופה משום דמל' שבכתר הוא כשב\"כ שבראש האותיות ובזה מתורץ הקושיא שבפי' הב' דלעיל בך' פשוטה שהוא לנוכח בגילוי ובסוף האותיות איך אומרים ארוממך דאדרבה הרי היא הנותנת משום דנעוץ סופו דכתר בתחילתו דוקא שהוא בחי' כשב\"כ שעל זה אומרים המלך המרומם לבדו דוקא ונקרא כתר דמל' שבכתר דאיהו כתר עליון כו' וגם זה אמת דמל' שבכתר זה הוא רק בחי' האחרונה שבו שהוא בגילוי לנוכח בך' פשוטה ובסוף האותיות והא בהא תליא והיו לאחדים ממש כפי המבואר בהקדמה דלעיל וד\"ל. ונמצא פי' הב' ממילא עולה בסגנון א' ממש עם פי' הא' דלעיל דארוממך קאי על בחי' כתר שבכתר דוקא ומרומם אותו לבחי' העצמות ממש כו' דודאי כמו שנתחב\"ס שהוא כשב\"כ במל' שבכתר שזהו ענין פי' הב' דלעיל כך ממש נעוץ סוב\"ת שהוא מל' שבכתר בכשב\"כ שהוא בך' כפופה דכתר שעולה ברוממות יותר והוא ברוממות העצמות דא\"ס ממש והא בהא תליא ממש דכאשר נקרא מלך מרומם לבדו ומתנשא על עולם הנאצל שהוא כתר מל' שנעוץ בו תחלתו דכתר עליון אז ממילא נקרא כתר עליון שהוא כשב\"כ מרומם ומוגבה למעלה בעצמות הרוממות ואינו נמנה בכלל הי\"ס ונמצא ב' הפי' דארוממך בין שהוא על מל' שבכתר שמרומם ומתנשא בבחי' כתר מלכות לגבי הנאצלים ובין שהוא על כתר שבכתר שמרומם בעצמות ממש הכל ענין א' ממש דהא בהא תליא והי' לאחדים ממש. ובזה מתורץ הכל ומתיישב בלשון הפסוק דקאי ארוממך לנוכח דוקא ומך' פשוטה נעשה כ\"ף כפופה דהיינו כתר מל' דאיהו כתר עליון שהוא בחי' כתר דכתר שמרומם בעצמות ממש רק שזה נקרא נעוץ תחלתן בסופן וזה נקרא נעוץ סוב\"ת אבל המכוון משניהם אחד הוא ואינם תרתי דסתרי אהדדי כלל אדרבה ענין וכוונה א' ממש ונכלל הכל בפי' א' שזהו עיקר הענין בתהלה לדוד שמדבר בשרש כתר מל' והוא כולל ך\"ב אתוון שבכתר עצמו מתחילתו לסופו ומסופו לתחילתו כא' ממש לפי שאין הפרש בין ראש לסוף כלל מטעם הנ\"ל וד\"ל. ועדיין יש להבין זה בתוספות ביאור בענין נעוץ תחלתן בסופן וסופן כו' איך שהכל א' דלכאורה ב' עניינים הם דכאשר תחלה מאיר בסוף אז נקרא מל' שבכתר מרומם שהוא הנקרא כתר מל' כנ\"ל וכאשר הסוף דמל' נעוץ בתחילה"],[2400650569,"אז בחי' כ\"ע נקרא מרומם בעצמות שהוא בחי' כשב\"כ ואמנם איך יתייחדו ויתחברו שני הדברים הללו כאחד לומר דהא בהא תליא דוקא כנ\"ל. והנה יש להקדים לביאור זה עוד ענין א' והוא בענין אמיתית פי' המאמר הזה דנתחב\"ס וסוב\"ת שהוא מדבר בבחי' ע\"ס דאו\"י למטה שזה ענין נעוץ תחב\"ס ובע\"ס דאו\"ח מלמטה למעלה שע\"ז אמר נעוץ סוב\"ת וכללות שניהם יחד כאשר מתכללים ע\"ס דאו\"י ואו\"ח יחד זהו כללות המאמר הזה באמרו דנעוץ תחב\"ס וסוב\"ת כלומר לא ששני עניינים נבדלים הם זה בלא זה אלא כלולים הם מע\"ס דאו\"י ואו\"ח דכאשר נעוץ תחב\"ס בבחי' או\"י אז ג\"כ נעוץ סופן כו' בבחי' או\"ח. וביאור הדברים הנה ידוע ביאור ענין ע\"ס דאו\"י ואו\"ח שבחי' או\"י הוא בחי' ירידת והמשכת השפע מגבוה לנמוך מעילה לעלול שלמטה הימנו והוא התלבשות כח העליון בתחתון אעפ\"י שלפי סדר ההשתלשלות הרי כל עלול לא ישיג העילה שלו לעולם כמו כח השכל לא ישיג לכח הרצון כי אין טעם לרצון שהרצון למעלה מן השכל והטעם וכן המדות לא ישיגו את השכל כו' עכ\"ז בחי' ירידה דאו\"י הרי כח הרצון יורד ומתלבש בשכל להיות בחי' טעם לרצון והשכל מתלבש במדות כמו שמצד השכל יתפעל באהבה וכה\"ג עד שיורד הרצון שבתחלה גם בדיבור ומעשה ונמצא נעוץ תחב\"ס הוא בבחי' או\"י דוקא דהיינו שתחלת הרצון שלמעלה מן החכ' באה בהתלבשות עד סוף מעשה ממש ונעוץ סופן בתחילתן הוא בבחי' או\"ח מלמטה למעלה דוקא והיינו ענין סוף מעשה שעלה במחשבה ורצון בתחלה שהרי כל עיקר הרצון שלמעלה מהטעם עדיין הוא רק בסוף מעשה דהיינו כשיבוא ויקיים רצונו בפו\"מ דוקא ומה שהדבר ברצונו עדיין אין זה שלימות עיקר הרצון כלל וע\"כ מה שיורד הרצון ומתצמצם בחכ' ומדות מעילה לעלול אינו רק דרך מעבר והעיקר הוא כשבא לידי מעשה וזהו הנקרא או\"ח שאינו אלא לאחר או\"י שקודם שירד הרצון בסוף מעשה אעפ\"י שעלה סוף מעשה זו ברצון תחלה עדיין לא הי' בו שלימות מאחר שעדיין לא ירד למטה בקיום בפו\"מ רק עלה המעשה במחשבה כו' אך לאחר בחי' או\"י דרצון שבא לידי מעשה דוקא אז עולה סוף מעשה זו ברצון וזהו בחי' שלימות עצם הרצון והוא שנתרומם עצם הרצון שהי' לו בתח' לבוא לשלימו' מקורו לבעל הרצון כו'. וכמו וירא אלקים את כל אשר עשה בפו\"מ דוקא שזהו לאחר ירידת אור הרצון בחכ' ומדות ביו\"ד מאמרות כמ\"ש בקדמין ובחוכמתא עד סוף מעשה דוקא אז עלה סוף מעשה זו ברצון הקדום שבעצמות המאציל וזהו והנה טוב מאוד שנשלם אז עצם הרצון העליון שנק' כשב\"כ ונתעלה בעצמות ממש שנקרא טוב מאוד בבחי' א\"ס ממש"],[2400650570,"כמ\"ש במ\"א וזהו הנקרא נעוץ סופן בתחילתן וד\"ל. והנה ידוע דבבחי' ע\"ס דאו\"ח בחי' המל' נקרא כתר והכתר מל' היפך בחי' ע\"ס דאו\"י מלמעלה למטה שהמל' אחרון והיינו מטעם הנ\"ל דסוף מעשה שהוא בחי' המל' עולה בעצם הרצון שבתחלה שנקרא כתר שבכתר הרי המל' בבחינת כתר שבכתר והכתר שהוא ירידת הרצון לבוא למעשה נקרא מל' כו'. וזהו היפוך ענין ע\"ס דאו\"י שהכתר נקרא תחלה והמל' שהוא המעשה נקרא סוף. ואמנם לכאורה ב' הפכים הם מאחר שזהו בבחי' הירידה וזהו בבחי' העלי' שמתחלף בהן מעליון לתחתון כמו בעיגול שבו קו הולך מעליונו לתחתיתו שהעולה והיורד בו ב' הפכים המה מה שאצל זה נקרא תחלה אצל זה נקרא סוף אבל בעיגול עצמו אין בו מעלה ומטה תחלה וסוף לכך כשזה בא למעלה ממש וזה בא למטה ממש שניהם שוין לענין התחילה וסוף מבלי שימצא חילוק בין ראש לסוף בעיגול עצמו כידוע כך הדוגמא יובן בענין התכללות דע\"ס דאו\"י עם הע\"ס דאו\"ח שע\"ז אמר נעוץ תחב\"ס וסוב\"ת כנ\"ל שאינן חלוקים בב' הפכים בעלי' וירידה להיות מה שבזה בחי' תחלה אצל זה סוף רק כשעדיין הם בבחי' הילוך עכ\"פ שזה עולה וזה יורד אבל לאחר תשלום ההילוך שלהם מלמעלה למטה ומלמטה למעלה אזי מתכללים כאחד ממש מבלי שימצא חילוק דתחילה וסוף בשניהם דכמו שזה נקרא סוף לתחילה דזולתו כך בהיפוך ונמצא שניהם נק' תחלה ושניהם נק' סוף כמו בעיגול שהוא כדורי כו'. כך יובן בענין תכלית שלימות עצם הרצון כאשר הוא בא מאמצעות הירידה דרצון בסוף מעשה מלמעלה למטה ממש שנקרא או\"י ומאמצעות העלי' דסוף מעשה זו בעצם הרצון מלמטה למעלה ממש הרי אז נתחברו ונתכללו בחי' האו\"י והאו\"ח יחד מבלי ימצא בהן חילוק בענין תחלה וסוף הנ\"ל וזהו ענין הג' דעות בגמרא א' דשמים נבראו תחלה לארץ שהוא הרצון שקודם למעשה. והב' דארץ נברא תחלה לשמים שהוא המעשה שעלה במח' תחילה והג' דשמים וארץ כאחד נבראו כמ\"ש קורא אני עליהם יעמדו יחדיו וזהו בחי' מקיף הכללי דכולל ע\"ס דאו\"י ואו\"ח יחד כעיגול שאין בו מעלה ומטה ע\"כ כולל מעלה ומטה דאו\"י ואו\"ח יחד וזהו ענין אות הך' כפופה דכתר שכלול מב' מדריגות דע\"ס הללו דאו\"י ואו\"ח שהוא שם מ\"ה ושם ב\"ן שהן היו ב' הפכים מה שבזה בחי' מל' בזה בחי' כתר כנ\"ל אך בהתכללות שלהם כשעלה סוף מעשה בתחילת המחשבה אז נעשה כ' כפופה בראש האותיות לכלול הע\"ס דאו\"י וע\"ס דאו\"ח והיינו ענין המאמר דנעוץ תחלתן בסופן וסופן כו' שאינן ב' עניינים נבדלים אלא כאשר נעוץ תחלה בסוף אז נעשה סוף"],[2400650571,"בתחילה שזהו כמ\"ד כאחד נבראו כו'. ובכל זה יובן בתוס' ביאור יותר בענין פי' הב' דארוממך למל' שבכתר לבחי' כתר מל' שנקרא מלך מרומם הוא מצד בחי' או\"ח דסוף מעשה עבמ\"ת דוקא והיינו ארוממך לך' פשוטה דודאי רוממות כתר שבכתר בעצמות מצד ירידה דאו\"י בא שהוא מ\"ש נתחב\"ס כתר דמל' ומה שמל' שבכתר נקרא כתר מל' דאיהו כ\"ע כנ\"ל מצד או\"ח ולא שהן ב' דברים אלא שמאמצעות שניהם כאחד הוא מטעם הנ\"ל והיינו ארוממך בך' פשוטה דאו\"י להיות בכתר דכ' כפופה ליכלל ב' המדריגות דאו\"י ואו\"ח להיות כאחד ממש וב' הפי' דלעיל בארוממך ענין א' ממש וד\"ל:"],[2400650572,"<h3>ואברכה שמך</h3>\n(קסב) <b>ואברכה</b> שמך לעולם ועד. הנה מבואר למעלה בפי' ארוממך אלקי המלך שהוא בבחי' עליות דע\"ס דאו\"ח בבחי' ב\"ן שלזה אמרו נעוץ סופן בתחלתן וממילא נמשך אח\"כ בחי' ברכה שהוא יורד מלמעלה למטה דנעוץ תחלתן בסופן כו' וזה שאחר ארוממך דוקא ואברכה שמך כו' וארוממך הוא בבחי' כתר מל' דאיהי כתר עליון בבחי' כשב\"כ דוקא כנ\"ל ע\"כ מזה יובן במה שאמר ואברכה שמך דוקא שבחי' ברכה זאת היינו כמ\"ש וחסידיך יברכוכה יברכו כ\"ה שהוא כמו ענין ברכת כהנים יברכך ה' שהוא רק להאיר פנים העליונים דבחי' א\"א דאצילות במל' דאצי' שנק' כ\"ה בכ' הדמיון כידוע וז\"ש יאר ה' פניו אליך דוקא כמ\"ש במ\"א וכך הוא ענין המשכת י\"ג מדה\"ר דא\"א שנק' ג\"כ בשם הארת פנים דוקא כמ\"ש ויעבור ה' על פניו ויקרא ה' ה' כו' שזהו בחי' הארת פנים העליוני' דא\"א במל' דאצילות סופא דכולא וז\"ש כאן ואברכה שמך דוקא שבחי' המל' נק' שם כידוע ונמשך לשם מי\"ג ת\"ד דא\"א הארת אור פניו להאיר אור המל' בתוס' מרובה ביותר משום דנעוץ תחב\"ס דוקא כנ\"ל ופי' תחלתן זה היינו בחי' כתר שבכתר דוקא שמשם עיקר בחי' הארת פנים דא\"א בי\"ג מדה\"ר שבי\"ג ת\"ד כידוע וד\"ל והיינו דוקא אחר בחי' העלי' דאו\"ח דארוממך דלעיל עד שנעשה כ' כפופה בכתר שכולל ע\"ס דאו\"י ואו\"ח יחד והוא בבחי' כתר שבכתר שמשם דוקא יאר ה' פניו בי\"ג מדה\"ר וזהו שאז דוקא אברכה שמך כו'. ולהבין ביאור הדברים הנה תחלה י\"ל למה דוקא בבחי' המל' שנק' סופא דכולא יאיר שם מאור העליון ביותר שהוא בחי' כשב\"כ ואם משום דנעוץ תחב\"ס מה שייך זה לענין י\"ג מדה\"ר דוקא שאז ואברכה שמך כענין וחסידיך יברכוכה כנ\"ל הלא כבר נעוץ תחב\"ס וסוב\"ת כענין הנ\"ל ברצון הנעלם שבא בגילוי בסוף מעשה דוקא וסומ\"ע עלה במח\"ת כו' כנ\"ל. אך הנה באמת שרש י\"ג מדה\"ר למעלה גם מבחי' כשב\"כ שהרי בחי' כשב\"כ הוא הנק' תחלת הרצון הנעלם"],[2400650573,"בעצמו טרם שבא לכלל גילוי גם בטעם כמוס לרצון וזהו כמו הגולגלתא שמקיף המו\"ס ג\"כ כמ\"ש במ\"א וזהו כתר כותרת שהוא כ' כפופה הנ\"ל. אבל י\"ג מדה\"ר שרשם נעלה יותר בעצמות בעל הרצון שלזה בוקע האור רק דרך בחי' שערות מעצם הגולגלתא בי\"ג ת\"ד דא\"א כו' מפני שהוא בא בבחי' דילוג גדול להיות שרשו מבחי' העצמות דאא\"ס שמאיר בבחי' מקיף על הגולגלתא כו' ולזאת ג\"כ בוקע האור בבחי' מותרות ונובלות מבחי' מו\"ס להיות שלא יכילנו כלל ע\"כ יוצא ובוקע לחוץ כו' כמ\"ש במ\"א בענין אז יבקע כשחר כו' וכמו ענין נובלות חכ' של מעלה שלמע' מחכ' של מעלה עצמה כמ\"ש במ\"א באריכות בשרש ענין מזלות דא\"א שלהיות כן אמר ויעבור ה' על פניו שדילג גם על פנימי' הכתר שבמו\"ס כו' שנק' פניו ויקרא ה' ה' ב' פעמים ה' אחד בעצמותו ממש והב' הוא אשר בוקע ויוצא להאיר בי\"ג ת\"ד בבחי' מותרי מו\"ס ושרשם מבחי' העצמות ממש (וכמ\"ש במ\"א בענין לבושי' כתלג חיוור ושער רישי' כו' וד\"ל). והנה במה שאמר ארוממך כבר הי' עליי' לבחי' כתר שבכתר עצמו בעצמות ממש ע\"י בחי' עלי' דאו\"ח דנעוץ סופן בתחלתן שהוא סוף מעשה שעלה במח' תחלה והיינו ארוממך בחי' כתר מל' למטה דהא בהא תלי' כנ\"ל ע\"כ משם דוקא יומשך אחר כך אור מבחי' העצמות לבחי' כתר שבכתר שנק' מקיף דגולגלתא (והוא כמו בחי' מקיף דיחידה למטה) שיהי' מזה בחי' תוס' הארת אור פנים העליוני' דא\"א מבחי' מו\"ס שבו בי\"ג ת\"ד להיות מאיר עד למטה מטה דוקא דהיינו בבחי' המל' שזהו למעלה הרבה מבחי' נעוץ תחב\"ס שאינו בא רק מירידת תחלת רצון בסוף מעשה ולא מן העצמות של בעל הרצון אך לאחר שעלה סוף מעשה במח\"ת ונעשה כ' כפופה [דכתר] בבחי' מקיף דכתר דוקא אז נמשך מבחי' אור עצמות במקיפי' דכתר הנק' גלגלתא דא\"א להיות תוס' אור בפנים דא\"א בהארת י\"ג מדה\"ר למל' דוקא משום דכל הגבוה גבוה יותר לא יבא לגילוי למעלה כ\"א ביותר למטה דוקא (כמו אור שכל עמוק שלא יובן ויושג במחו\"ד כ\"א במשל זר וכל שעמוק יותר צריך עוד משל למשל כו'. וכאור הבהיר ביותר שאינו ניכר רק בחושך) דזהו הכלל שכל אור עליון ביותר התגלותו בסוף הכל דוקא ולכך כל התגלות י\"ג מדה\"ר דא\"א הוא בא במל' דוקא להיות שבחי' עצמות רוממות דכתר שבכתר כמו שהוא למעלה בעצמות ממש אינו מושג כלל גם בכתר דא\"א כו' כי נחשב מעצמות המאציל ממש ע\"כ לא יוכל להאיר כ\"א בבחי' המל' דוקא וגם זה בבחי' אותיות דמל' (שנק' קישוטי כלה שנק' אבנים טובות שמאירים פנים דנוק' מאור הכתר ודוקא מבחי' רוממות אור דכתר שבכתר כנ\"ל וכמשי\"ת)"],[2400650574,"וד\"ל. והנה מלבד זה יש עוד טעם לענין המשכת הארת י\"ג מדה\"ר שנק' הארת פנים דא\"א במל' דוקא ולא בעליון הימנו כמו בז\"א ואו\"א כו' לפי שבחי' המל' הוא סוף כל המדות דאצילות להיות שמדה זו היא רק בחי' ההתגלות וההתפשטות חוץ מן העצמות והוא כמו בחי' אותיו' הדבור שאינו רק גילוי עצם המדות והשכל והרצון ואינה מדה עצמי' כמדת חכ' כו' כידוע או כמו מדת ההתנשאות שהוא רק על זולתו ולא נחשב מעצם הכוחות כמו עצם מדת החסד והחכמה כו' וכה\"ג וכמ\"ש במ\"א ויש כאן ב' דברים לגריעותא האחד שהוא בחי' היותר אחרונה שאינה רק בחי' התגלות (כידוע בע\"ח דמבחי' מל' שבכל ספירה דז\"א נבנה בנין הע\"ס דמל'). ועוד מה שיורדת בהתגלות זו לחוץ מעצם אור האצילות לעולמות הנפרדים עד למטה מטה מאוד גם להשפיע לע\"ש דנוגה דעשי' שהם בבחי' הפירוד ממש וכידוע דבחי' מל' דאצילות ראש לשועלים להיות בדבר ה' בצירופי אותיות מתהווים כל העולמות בע\"ג ותכלית עד סוף עולם העשי' בע' שרים שמקבלים ממ\"ח צירופי' אחרונים דמל' כמ\"ש מלך אלקים על גוים כו' כי אזלעו\"ז עשה אלקים דוקא כו' ולזאת בעוצם ירידת המל' עד היכלות החיצוני' בע' שרים דנוגה דעשי' שם יוכל להיות הסתר אלקות בתכלית עד שנק' חושך וכידוע בענין פגימת הלבנה משום דשם ההעלם וההסתר בא בריבוי צמצומים עד שנק' לבוש שק וכמ\"ש ושק אשים כו' וז\"ש ואתה אל מסתתר כו'. הרי מב' טעמים הללו הא' להיות בחי' המל' היותר אחרונה באצילות עצמו והב' מצד עוצם הירידה שלה בבי\"ע עד היכלות החיצוני' דסוף העשי' יוכל להיות בחי' חושך גמור באור המל' בבחי' נפילה למטה ונק' סוכת דוד הנופלת וכמו בזמן הגלות שאומרת שחורה אני כו' ששזפתני השמש כו' וכן אמר דרישא שכיבת לעפרא כו' וכה\"ג משום דהחיצונים מקבלים תוס' יניקה מבחי' מוחין דנוקבא שנק' רישא ועי\"ז נעשה חשכת הפנים דוקא היפוך הארת הפנים כמו המראה השחור שבפנים שבא מצד המרירות בנפש שנעשה הדם שחור דשחור אדום הוא אלא שלקה על ידי המרירות כמו מדוע פניך רעים אין זה כ\"א מרוע לבב וכמ\"ש וימררו את חייהם ואמר בזוהר חייהון דכנ\"י כו' וכן כתיב בחנה והיא מרת נפש כמ\"ש במ\"א וע\"כ מב' טעמים הללו צריכה המל' חיזוק יותר משאר המדות דאצילות דהיינו שיבוא לה חיזוק כח ואור להאירה משפלותה וירידתה בחושך וגם מצד עצם קטנות מדרגתה צריכה לחיזוק גדול והחיזוק הוא ממקום ומדריגה גבוה ביותר וכמ\"ש וה' יגיה חשכי כו' שכל מי שהוא הולך באפילה יותר צריך לאור רב שיאיר לו משא\"כ היושב במקום אור כו' כך בבחי' המדות וחו\"ב דאצילות דבאצילות איהו וחיוהי"],[2400650575,"חד כו' אין צריך לחיזוק אורם מאור הכתר כ\"כ משא\"כ המל' שמסתתרת למטה באפילה דהיכלות החיצוני' צריכה לאור גדול ועליון ביותר שיחזק כח אורה בתוס' גדולה כדי שלא יחשך אורה כו'. ועוד לבד עוצם ירידתה הנה מצד עצמה להיותה בחי' האחרונה ביותר צריכה לחיזוק בתוס' אור ממקום עליון דוקא והוא מבחי' כשב\"כ דוקא והיינו ענין י\"ג מדה\"ר דפנימי' הכתר הנ\"ל נמשך לבחי' המל' דוקא להאיר פניה ולחזק כוחה ביותר וכמו משל התינוק קטן מצד שפלותו וקטנות דעתו יפול לבו ודעתו ולא יוכל לדבר ולהשכיל דבר כלל אך כאשר הגדול מראה אליו פנים שוחקות וקירוב גדול בזה מתרומם לבו ודעתו קצת כי מתחזק מזה אזי יכול להכין לבו ודעתו ויקבל הכל אבל הגדול בדעת שאינו בשפלות עצמו אין צריך לחיזוק הגדול ממנו ולא יתרומם ויתחזק על ידי זה כלל כי יש בו חיזוק מכח עצמו כו'. ולפי\"ז המשל החיזוק של התינוק מקירוב פנים שוחקות של הגדול הימנו [מאיש] גדול וחשוב ביותר דוקא שעל ידי זה דוקא מתרומם ומתחזק ביותר ולא ממי שאינו גדול כ\"כ וכל מי שהוא בשפלות יותר כעני ונבזה צריך חיזוק מאיש רב ונכבד ביותר להרימו ולחזקו מעוצם שפלותו וכו' שלא יפול לעולם וכך יובן למעלה בבחי' המל' שנק' דל (ושכיבת לעפרא כמ\"ש מקימי מעפר דל מאשפות ירים כו' כנ\"ל) והוא להיותה בבחי' הקטנות במדריגה (דנשים דעתן קלות בקטנות המוחין ונק' אנפי זוטרי) צריכה חיזוק ורוממות הארת פניה מאור הגבוה ועליון ביותר דוקא שהוא בחי' כשב\"כ שמאיר באור פני מלך כו' בי\"ג מדה\"ר כמ\"ש יאר ה' פניו אליך דוקא מב' טעמים הנ\"ל (וכמ\"ש במ\"א בענין יונתי בחגוי הסלע כו' דש\"ע נהורין דא\"א מאירין באסתכלותא במל' שבראי' והסתכלות זאת מתחזקים ומאירים אור פני המל' היותר מכל שפע אור חידוש המוחין שבאין בריבוי השתלשלות מא\"א ע\"י או\"א וז\"א לנוק' כו' וכמו תלמיד המקבל פני רבו כו' וכמו עולת ראי' בג' רגלים דכתיב יראה כל זכורך כו' כשם שבא כו') וזהו מ\"ש אשא עיני אל ההרים מאין יבוא עזרי מאין דכתר כו' וכן עיני כל אליך כו' והיינו שיאר ה' פניו בי\"ג מדה\"ר במל' דוקא וכל זה הטעם מלבד טעם ענין נתחב\"ס הנ\"ל ומלבד טעם כלל הנ\"ל דכל הגבוה כו' לפי שזה הטעם הוא האמיתי יותר וד\"ל:\n(קסג) <b>ובכל</b> הנ\"ל יובן ענין קישוטי כלה כמ\"ש בקישוטין אזלא ומאנין ולבושין כו'. דהנה עד\"מ הקישוטין שהאשה מתקשטת בהן הרי על ידם נראית ביופי כי הבהקת התכשיטין טובים מאירים פניה עד שנראית במראה יפ\"ת ואע\"פ שאינה יפ\"ת ומראה בעצם אך ע\"י הקישוטין הללו שהן ציור רקמת"],[2400650576,"אבנים טובות ומרגליות יאירו ויצהיבו את פניה כאלו היא יפה בעצם ולזאת כל אשה שצריכה ליופי להיותה איננה יפה בעצם צריכה לקישוטים יפים ביותר שתתיפה על ידם כו'. והנה זה היופי הנקנה באשה על ידי הקישוטים אינו יופי בעצם רק בשעה שהקישוטים על פניה אבל מיד שתסירם אינה יפה כלל אבל מ\"מ נק' יופי שבאמצעות הקישוטים בשם בחי' מקיף מאחר שהוא מפעיל היופי גם במה שאינו יפה הרי מהם מקור מוצא מציאת היופי שבגילוי בפנים או בבגד ועץ ומתכת וכה\"ג וכמו בחי' או\"מ שהוא בהעלם ועושה לגילוי אור הפנימי שיאיר בגילוי כך בתכשיטין עצמם אין היופי בגילוי עדיין רק שמחמתם ימצא ההידור והיופי על מראית עין באותו שעה שהם מונחים על פניה כו' (וכמו כליל תפארת בראשו כו' שמבואר במ\"א שהוא מקור הפאר לכל אשר ילבשנו שיפארנו לפי תוארו וצורתו כך תכשיט אחד מייפה לכל לובשו כו') וכך יובן למעלה בבחי' קישוטי כלה העליונה בבחי' מל' דאצי' שנק' כלת משה כו' ונק' אשה יראת ה' כו' ונזכר בשיר השירים ענין תכשיטין שלה כמו מה נאוו לחייך בתורים צווארך בחרוזים כו' וכה\"ג שמייפים לבחינת המל' וכמ\"ש בקישוטין אזלא כו' דהיינו גם בהיות בחינת המל' בחשכת תואר מראה מצד עוצם ירידתה בהסתר אלקות בלבוש שק כו' שאז פניה חשוכים מאד מצד יניקת החיצונים ביותר כנ\"ל ע\"כ צריכה לתכשיטין שיאירו פניה לעשות בה הארת הפנים ביותר ביופי והידור הגם שאינו רק בשעה זו שמתקשטת כו' אבל יש בהארה זו בחי' אור מקיף מאחר שמפעיל זה היופי מן ההעלם שבקישוטין כו' וכנ\"ל בקישוטין גשמיי' וזהו מצד בחינת הארת אור פנים העליוני' דכשב\"כ דאצי' שאור עליון זה מצד עוצם רוממותו יורד למטה ביותר והוא שמתלבשת בקישוטי' שהם אבנים טובו' ונקרא ז' מרגלאן טבאן שהן קישוטי דכלה להאיר פניה מבחינת החשך דנוג\"ה כמ\"ש וה' יגיה חשכי כו' ע\"י הקישוטין כו' והיינו משום דאין אשה אלא ליופי כדברי רז\"ל והוא ע\"י בחי' הארת הפנים דא\"א במל' שמקבלת היופי מלמעלה שהיא צריכה לקבלה זו מפני שפניה חשוכים וצריכה לקישוטים להיות מאירים פניה מזה כו' והיינו בקישוטין אזל' כו' והקישוטין הללו נותן החתן לכלה שתתקשט בהם לפי שאין אשה אלא ליופי ע\"כ צריכה לקישוטין וגם אם היא יפ\"ת ויפ\"מ בעצם עכ\"ז צריך החתן לשלוח לה קישוטים שתתנאה בהם לפניו ותלבשם לכבוד ולתפארת בעיני כל רואיה בשוק כו' וד\"ל. והנה לכאורה אין כ\"ז מובן דהנה אין המשל דומה לנמשל כלל דהקישוטים הגשמיי' נעשים מאבנים טובות גשמיי' וכן מרגליות וכה\"ג ולמעלה איך נמשך קישוטין כאלה מאור הארת פנים דא\"א"],[2400650577,"שאור הארת פנים שבכתר כו' הוא אור צח ומצוחצח שלמעלה גם מאור החכ' כו' ואיך נעשה משם בחינת קישוטין גשמיי' לכלה העליונה שהוא בחי' מל' דאצי' כנ\"ל. ועוד י\"ל בעיקר הענין דלפי הנ\"ל משמע שעיקר הקישוטים אינו אלא כשפני' חשכים והוא בהיות בחי' המל' למטה בהתלבשות בע\"ש כו' ואיך יגיע לה שם דוקא אור הארת הכתר להיות מזה קשוטין כו' ובאמת הרי בחי' המל' נק' רחל עקרת הבית שנא' בה ורחל היתה יפ\"ת ויפ\"מ בעצם ואינה צריכה לקשוטים כו'. וגם מה שהחתן שולח לה קישוטים אינו מובן הטעם משום דאין אשה אלא ליופי שהרי מקרא מלא דבר שקר החן והבל היופי אשה יראת ה' דוקא היא תתהלל ואיך אמרו שאין אשה אלא ליופי ועוד שהרי אשה היא למצות פו\"ר ולא ליופי כו' ואיך מהפך הדבר לשלול הכל ולומר שאין אשה אלא ליופי בלבד כו'. וגם יש להבין שרש טעם הקישוטין שנק' בחי' מקיף בבחי' היופי דוקא וכמ\"ש ככלה תעדה כו'. אך הנה כ\"ז יובן בהקדים ענין אחד בשרש ענין הקשוטים שהן נעשים מאבני' טובי' ומרגליות גשמיי' כו' כידוע ומבואר במ\"א בענין פנים מאירות ופנים מסבירות שזהו תושב\"כ ותושבע\"פ דפנים מאירות הוא בעצם האור דפנימית חכ' כמו חכמת אדם תאיר פניו במ\"ת דאוא\"ס מאיר בפנימי' ח\"ס והוא נק' בחי' עונג הנרגש בגילוי אור ונעשה מקור מוצא כח המשכיל להשכיל ולהוליד אור שכל חדש עד שמזה יצהיבו פניו בגשמיות ויש כאן ג' מדרגות אור מורגש בעונג ואור כח המשכיל להוליד ואור השכל הנולד עד אור המתגלה בדם ובשר שבפניו שנק' תרין תפוחי' כמו ר' אבהו מצא תוספתא חדתא ונהרין אנפוהי כו' וזהו פנים המאירות בעצם וכמ\"ש ותורה אור והוא מבחינת גבורה דע\"י המלובש בח\"ס שנק' טל תורה ונק' עדן שנק' טעמי תורה תענוג המורגש בח\"ס כו' והן אותיות דתושב\"כ אבל אותיות דתושבע\"פ נק' פנים מסבירות והוא ענין התלמוד שמפלפל לבאר אותיות דתושב\"כ כמו הדרשות שע\"כ קוץ כו' אחר ריבוי הקושיות וההעלמות דוקא דהיינו כמו הסבר הדבר שכל עמוק הרי תחלה נסתר אורו לגמרי בלתי מושג כלל ואחר היגיעה הרבה יוציאו האור הגנוז ונעלם בו זהו הנק' פנים מסבירות כמו מאי טעמא דר' פלוני כו' דהיינו מן המקרא עצמו לא הי' מושג כלל רק ע\"י פלפול קושיות ותירוצים הרבה אז דוקא יבא הסבר טעם הדבר לאור ונק' אור חדש לגמרי וכמו הרבה הלכות שנתחדשו בתושבע\"פ בבחי' גילוי העלם האור שבתושב\"כ וזהו כל עיקר ענין תושבע\"פ שנק' א\"ח כו' וזהו בקישוטין אזלא כו' ונק' קישוטי כלה כל הלכות שבא מן הפלפול שהוא הסתר הקושיות ומשם דוקא יאיר מתוך ההעלם ונמצא ההעלם עצמו מאיר זהו עיקר ענין"],[2400650578,"פנים מסבירות שהוא למעלה מפנים מאירות בעצם הנ\"ל להיות שיש בחי' עונג הנעלם בעצמות התענוג שבלתי יבא כלל לבחי' הרגשה בחכ' ונק' מקור העדן שבח\"ס שלמעלה מטעמי תורה וטעמי מצות (וכמו שאין תענוג וטעם לרצוה\"פ כך אין טעם ותענוג לתעה\"פ בעצם כו') אך בסוף מעשה בבירורי' דרפ\"ח כו' בפו\"מ דמצות שעבמ\"ת בעצם הרצון והתענוג הנעלם הפשוט והוא עונג הנעלם שבתושבע\"פ מל' קרינן לה כשבא לברר הדבר כמו הפלפול והקושיא שבזה יוצא לאור בחי' העונג הנעלם שבעצמות דוקא (ולכך האותיו' שבתושבע\"פ נלקחים מע' לשון ולא בלה\"ק דוקא כמ\"ש במ\"א בענין ותהי להם הלבנה לאבן כו' והוא ההפרש בין מ\"ד למ\"ן דמ\"ד נק' המשכת אור בעצם אבל המ\"ן נעשה מדבר זר שהוא האודם שהוא מן המאכלים שאוכלת כו' וכמו\"כ המים שבדם שהוא עיקר המחי' וכן אכל ולא שתה כו') ונמצא בחי' פנים מסבירות אע\"פ שהוא בחי' מקבל בחי' נוק' כמו תושבע\"פ שמקבל מתושב\"כ אבל בזה דוקא נמצא גילוי אור עונג הנעלם בעצמות משא\"כ בפנים מאירות כו' ולכך נק' א\"ח עט\"ב כו' וז\"ש דאין אשה אלא ליופי דידוע שהתורה בבחי' ת\"ת כמ\"ש במ\"א אמנם עיקר בחי' זו אינה רק פנים מאירות דח\"ס כנ\"ל בפי' חכמת אדם תאיר פניו דקאי במ\"ת דכ' כחתן יכהן פאר כו' אבל עיקר שלימות של היופי הזה הוא בפנים מסבירות דתושבע\"פ ששם נשלם [תחילת] הרצון והעונג הנעלם אך בחי' היופי שבנוק' להיותו גילוי הנעלם בב' אופנים בפנימי' ומקיפים ולכך א' בקישוטין אזלא כו' והקישוטין הללו הן באין מבחי' בירורים דרפ\"ח כו' כמו המרגליות שמבהקת וכמ\"ש במ\"א בענין ותחת רגליו כמעשה לבנת הספיר וכן אבן ספיר כו' כך ענין ז' מרגלאן טבאן כו' דמל' שהן לנגד ז' מדות דנוגה דוקא שמתבררים ועולים מלמטה למעלה בבחי' בירור דחכ' בתושבע\"פ דוקא ונעשה לה קישוטין לפעול בה היופי בבחי' ההעלם שהוא היופי שבבחי' מקיף הנ\"ל שבקישוטין מצד עצמן שיש בהם כח זה מצד שרש הבירורים דרפ\"ח שגנוז בהם אור עונג עצמי ופשוט הנעלם וע\"י תושבע\"פ יוצא לאור ומבהיק כנ\"ל בענין פני' מסבירות כו' והיופי הב' הוא היופי בעצם דהיינו בבחי' או\"פ בגילוי הארת הפנים ממש (והוא בנוק' דוקא וכידוע בטבע מזג הדמים שבאשה שהן באי' יותר בצלילות להיות עי\"ז דוקא יפין בטבעם יותר מן האנשים והוא מצד בירור הדם מריבוי הפסולת שבדמים הטמאים ששופעת דוקא כמו החוחים שהן דוקא הגורמים יפה תואר השושנה הגדלה ביניהם וכמ\"ש כשושנה בין החוחים כן רעייתי כו' שהחוחים צומחים מן הפסולת והשושנה הצומחת במקום ריבוי פסולת יותר הוא דוקא הגורם ההידור והבירור שבה כו' כמ\"ש במ\"א) וזהו שקר"],[2400650579,"החן כו' שאינו מתקיים מצד עצמו שלפעמים אורה נחשך מיניקת החיצוני' עד שפניה רעים וחשוכים או כמו בימי נדותה כו' כמ\"ש נאלמתי דומיה החשתי ר\"ת נדה כידוע אבל אשה יראת ה' כו' הוא היופי הבא מצד הבירורים דרפ\"ח כו' שנברר מכל סיג ופסולת כו' כשושנה בין החוחים כו' היא תתהלל כמו בהלו נרו כו' שמקבלת מיופי העליון שהיא מהארת פנים דא\"א כמ\"ש יאר ה' פניו אליך כו'. ונמצא אין אשה אלא ליופי הוא בב' אופנים הא' אלא ליופי שבה שהוא מצד הבירורים כו' ומה שנשלם היופי דמשפיע בזה ונק' עט\"ב. והב' ענין הקישוטין שהן בבחי' מקיף בהעלם. אך מ\"ש אלא ליופי והלא עיקר הבנין דנוק' לבנות ממנה בנין עדי עד לפו\"ר הענין הוא דזהו ענין הסבלונות שהוא העושה המקור ליחודים להיות מזה התולדה כו' כמ\"ש במ\"א ולפי\"ז יתורץ הכל דעיקר הארת פנים דמל' בא מאור הפנים דח\"ס שנקרא פנים מאירות אבל הקישוטים ששולח לה הוא למעלה מזה והוא גם בהיות המל' בע\"ש דנוגה יאירו פניה עי\"ז מטעם הנ\"ל דעונג הנעלם בעצמו גנוז בהן כו' ונמצא בקישוטין שלה יש בהן מפנימי' האור הנעלם שבכתר ואינו מקשט ומייפה רק לבחי' המל' דוקא כי בסוף דוקא מאיר אור הנעלם בתחלה כו' וזהו שתכשיטי אשה אינן תכשיטין לאיש כלל כו' וקישוטי כלה הם באין מן המשפיע דוקא הנק' סבלונות כו' מטעם הנ\"ל וד\"ל. וזהו ואברכה שמך בי\"ג מדה\"ר כו' ולשמך דוקא מטעם הנ\"ל וד\"ל:"],[2400650580,"<h3>בכל יום אברכך</h3>\n(קסד) <b>בכל</b> יום אברכך ואהללה שמך כו'. הנה מבואר למעלה בפי' ואברכה שמך כו' דברכה זו קאי בהמשכת י\"ג מדה\"ר מהארת פנים דא\"א כו' וגם בפסוק זה שאו' בכ\"י אברכך ברכה זו קאי על י\"ג מדה\"ר דוקא אלא שבתחלה א' בדרך כלל בכללות הברכה שנמשך מבחי' הכתר למל' שנק' שמך לפי שנתב\"ס דוקא מטעמים המבוארים למעלה באריכות ובכאן מדבר בדרך פרט בפרטי המשכות הברכה מאור הכתר במל' והוא מ\"ש בכל יום [דהיינו בכל יום ויום] נמשך ברכה מיוחדת בפ\"ע וכמו ברכת כהנים שמצוה זו נוהגת בכ\"י כשיש מנין שמתפללין וכהן א' מברך בכ\"י ויום (רק מטעם קרי אין מברכין בכ\"י כידוע) כי ברכת כהנים שרשו הוא ג\"כ כמו בבחי' המשכת י\"ג מדה\"ר שהוא מבחי' הארת פנים דא\"א כמ\"ש יאר ה' פניו אליך ויחונך ישא ה' פניו כו' לפי שהכהנים שרשם בחי' רב חסד דא\"א כו' שזהו בחי' כה\"ג שנוטל חלק בראש דחכ' (ומשם נמשך לז\"א שיצוה עליו לברך כמו שמבואר במ\"א בפי' יברכך הוי' שהוא ז\"א בלשון ציווי כו') וגם כאן א' בכ\"י אברכך כו' שבכ\"י ויום נמשך י\"ג מדה\"ר דא\"א בכל פרטי האורות דז\"א"],[2400650581,"שנק' ימים עליוני' דאצי' ויש לכל יום ברכה והמשכה מיוחדת בפ\"ע והענין הוא כידוע דבחי' ז\"א הוא בחי' המדות דאצי' שנק' יומין עילאין כמ\"ש בזוהר ע\"פ ששת ימים עשה כו' דהיינו ו' יומין עילאין דז\"א שהן וי\"ו מדות דאצי' יום א' בחי' חסד דז\"א והוא מאמר יהי אור ויום ב' בחי' גבורה דז\"א והוא מאמר יהי רקיע כו' ומכל יום נמשך למטה אלף שנים כמ\"ש כי אלף שנים בעיניך כיום אתמול כו' והן ו\"א שני דהוי עלמא כו' כידוע. אך הנה ידוע דבחי' ו' מדות כלולים זה מזה וכ\"א כלול מיו\"ד ויו\"ד מיו\"ד ומטעם זה כמה כלים מכלים שונים יש לכ\"א מפני שכ\"א כלול מזולתו בכמה ריבוי אופנים התכללות שונות דכמו שיש רבוי התכללות באורות שמחמת זה נמצא ריבוי פרטי מדרגות באורות. כך ממש נמצא ריבוי התכללות בכלי' מכלי' שוני' מפני שכ\"א כלול מזולתו והן הנק' יומין עילאין כידוע בפי' ויקרא אלקי' לאור יום שהיום נק' בחי' כלי לאור וכמ\"ש ימים יוצרו שהימים נוצרו בבחי' הגבלה וכן מל' ויצר בחרט כו' שכולל ב' דברים הא' ההגבלה במספר כמו כצל ימינו עלי ארץ כו' וההגבלה במהות שהוא כמו יב\"ש הוי היום שהאור הוא עצם בלתי מוגבל והגבלתו נק' יום כימי חיי האדם שהן כלי הגבלה לאורות חיי נפשו שבכל יום מאיר אור וכח חדש כו' ולכך ניתן ימי' לאדם במספר לברר בכ\"י אור וכח א' המיוחד לאותו היום כו' (וכמ\"ש במ\"א בענין בכ\"י ויום חייב אדם לראות א\"ע כאלו יצא כו' וכן ענין ק' ברכות בכ\"י דוקא כו'). ואמנם כל הימים כלולים זע\"ז ולא יש יום שאין בו התכללות מזולתו כו' (ומ\"ש את מספר ימיך אמלא היינו שלימות הכלי מצד שלימות האור בשרשו בעצמות כמו שהוא טרם שיבא לבחי' הגבלה בכלי וזהו אמלא מבחי' המילוים דכתר) וכך יובן למעלה כמו בוי\"ו ימי בראשית דכל יום הוא בחי' כלי מיוחד להגבלת אור עליון דאצי' וכלול הוא מזולתו לפי שכל בחי' אורות דז\"א כלולים זע\"ז ומחמת זה גם בכלים שנק' ימים דאצי' נמצא ריבוי התכללות שונות. וזהו בכ\"י אברכך בכל מדריגה ומדריגה בפרט שבבחי' הכלים דאורות דאצי' בכל יום ויום בפרט נמשך הארת י\"ג מדה\"ר דא\"א כנ\"ל בפי' ואברכה שמך בברכת כהנים שנמשך בכ\"י ויום כו' כי בחי' הארת פנים דא\"א מאיר בימים דז\"א דאצי' ומשם נמשך למל' וכמ\"ש יום ליום יביע אמר כו' (ומ\"ש ימים יוצרו ולא א' בהם ולא קרי ולו כתיב והוא כאשר נמשך הארת אחד דא\"א בהם כו'. ולהבין טעם הדברים למה בכל יום אברכך כו' להיות מבואר במ\"א בענין מאה ברכות שחייב אדם לברך בכ\"י לפי שמאה ברכות הם בבחי' ע\"ס דכתר שכלול כ\"א מיו\"ד ע\"כ הן מאה דווקא. והענין הוא כידוע שבחי'"],[2400650582,"הכתר הוא הרצון והתענוג וכלול מחב\"ד ומדות כו' ונק' ע\"ס שבכת' ומפני שבהם מאיר מע\"ס הגנוזות בעצמות ממש כמו חכ' וחסד שבעצמות אוא\"ס ע\"כ א' שחייב אדם שהוא בצלם אדה\"ע דאצי' בחי' ז\"א לברך ק' ברכות הללו שהן ע\"ס דעצמו' שהן בחי' מקור הברכות שנמשכי' ע\"י בחי' הכתר דווקא שהוא הממוצע בין העצמות וכו' וכידוע וזהו פי' הפשוט דבכ\"י אברכך דהיינו הק' ברכות הללו שעז\"א ועתה מה ה' שואל כו' א\"ת מה אלא מאה כידוע. ולמעלה היינו בחי' ק' ברכות דכתר דאצי' בז\"א שעליו א' חייב אדם לברך כו' וכידוע שהקב\"ה מתעטף בטלית כו'. ולפי\"ז גם טעם שבכל יום דוקא יובן מפני שבכל יום ביומין עילאין דאצי' מאיר אור חדש בז\"א מאורות עליונים דכח\"ב דאצי' כמו עד\"מ באדם התחתון שבכל יום מאיר בנפשו כח חדש כנ\"ל לברר בירורים כו' והוא בחי' אור חסד עליון הנמשך בכל יום בפ\"ע כמ\"ש כי חסד אל כל היום וכן יומם יצוה ה' חסדו דהיינו ריבוי אורות החסדים העליוני' שנמשכים בימים עליונים דז\"א בריבוי התכללות או\"כ שבו שנק' ימים כנ\"ל. וכ\"ז רק ענין תוס' ריבוי ברכה והמשכה דחסדים העליונים שבעצמות המאציל ונמשך בכ\"י ויום כמו ענין ב\"כ שהוא בכל יום כנ\"ל. ומחמת ריבוי כל אורות החסדים הללו מן העצמות ע\"י ק' ברכות דכתר אז יהי' באדם זה מבחי' פנימי' דעצמו' המאצי' כי כל או\"כ שבו יתברכו בכל פרטיהם בכ\"י ויום שבו ממקורא דכולא ואז נק' אדם אדמה כו'. והנה בפסוק שלפניו בארוממך אלקי כו' כבר הוכנה בחי' ברכה כללי' זאת במקורה עדיין בעצמות כמ\"ש ארוממך דווקא כנ\"ל מפני שנתחב\"ס כו' וז\"ש ואברכה שמך כו' אח\"כ בדרך כלל אך בפסוק זה מדבר בענין פרטי הברכות שנמשך בכ\"י וזהו הסדור לפי סדר הא\"ב דכתר דוקא וכנ\"ל דכ\"ב אתוון דתהלה לדוד הכל הוא בבחי' הכתר רק שהוא בבחי' הכתר דנוק' כי כל המשכות הברכות הללו לבחי' המל' דוקא כנ\"ל וד\"ל. ואהללה שמך לעול\"ו. פי' ההלל הוא אחר הברכה דוקא כי הברכה היא בחי' ריבוי ותוס' המשכת אורות החסדי' העליוני' שבעצמות דוקא כנ\"ל. ועי\"ז ממילא נעשה ונמשך בחי' ההלל שהוא ענין הבהקת האור כמו בהלו נרו כו' כשמבהיק ונק' אור בהיר אור צח כי אור החסד אורו מבהיק ביותר מצד העצם והוא כאשר אור החסד נמשך מן העצמות (שז\"ש בכ\"י אברכך) וע\"כ ע\"י ריבוי אור העצמי יוכל להיות תוס' הבהקת אור במל' ג\"כ וז\"ש ואהללה שמך דווקא להיות ידוע שבחי' המל' נק' סופא דכולא כו' שיורדת למטה מטה עד היכלות החיצוני' עד שיוכל להיות פגם והעדר האור מצד עוצם התגברות הקליפות הנק' חושך המחשיכים אורה והם בחי' גבורות"],[2400650583,"קשות דנוג' דעשי' לזאת צריכה לאור גדול ובהיר להאירה מחושך גם ע\"י תוקף אור הבהיר ומבהיק ביותר עד\"מ שבמקום חשך גס ואפילה ביותר צריך לאור בהיר ומבהיק שדוחה כל חשך גס ועב כמו אור שלהבת גדולה שתאיר גם באישון לילה במקומות האפלים ביותר או גם במסך ולבוש גס ועב ביותר וז\"ש וה' יגיה חשכי כו' וכך הוא למעלה שע\"י ריבוי אורות הבהירים ומבהיקים בעצם שהן החסדים הגדולים שבעצמות בק' ברכות דכתר שבזה א' בכ\"י אברכך אזי ואהללה שמך שם ב\"ן להאיר גם בחושך הגס שהן בחי' הגבורות הקשו' דנוג' שנאחזים במל' שלא יחשיכו כלל וכמ\"ש גם חושך לא יחשיך ממך כו' ואין זה אלא ע\"י אור צח ומצוחצח דאורות הכתר דוקא שהן בחי' המשכת י\"ג מדה\"ר דא\"א שנמשך מבחי' הארת פנים שבו במל' ומתלבשים תחלה בבחי' החסדים דז\"א שנק' ימים כמ\"ש בכ\"י כו' שריבוי החסדי' דוחין הגבורות הקשות המחשיכים כי כל אור דוחה חושך מפניו כידוע. ולכך בכל יום אברכך תחלה ואח\"כ ממילא ואהללה שמך כו' וד\"ל. ולפי המבואר במ\"א בענין הלל וברכה והודאה הרי ההלל דפסוד\"ז שהוא ריבוי האור להאיר גם את החושך קודם לברכה שהוא שפע עצמיות כו' ובכאן אמר תחלה אברכך ואח\"כ ואהללה שמך כו' וקאי בברכות שלפני פסוד\"ז כו' והענין הוא שיש ב' מיני הלל. הא' מלמעלה למטה והוא בחי' ריבוי אורות החסדים עליונים המאירים מלמעלה מצד עוצם אורם הבהיר כמשל אור העצמי' שבשמש או אבן טוב המאיר מצד עצם בריותו שדוחה העכרירות והחושך והוא בהלו נרו כו' וזה בא אחר הברכה שפע עצמי' הנ\"ל דוקא וכמו במ\"ת דחכ' אדם תאיר פניו בעונג שהוא אור העצמי כו' (וכן בימי משיח שיהי' נצחי כמשי\"ת). והב' ההלל שמלמטה למעלה והוא עד\"מ כשמזככין את האבן מכל סיג ועכרורי' עד שנעשה בהיר ומבהיק מאד ונק' אבן ספיר כו' וכמ\"ש במ\"א בענין שהם וישפה כו' שזהו ע\"י בחי' הבירורי' דעה\"ד כו' מלמטה למעלה שהחושך יהפך לאור בבחי' ביטול היש הגשמי לאין וזהו אור הבא מן החושך שהחושך מאיר ובהזדככות הגוף ע\"י אור הנשמה והיינו פסוד\"ז שנק' זמר עריצים להכרית יניקת החיצוני' בביטול היש כו' וזהו אור שאינו אלא משמש רק להאיר החושך דהיינו שהחושך יאיר כמ\"ש במ\"א והלל זה קודם לברכה שהוא בחי' הכנת החומר בהזדככות לקבל אור ושפע העצמי דברכה כו' וכך הוא כל ענין הגלות עד ימי המשיח שהוא הכנה לקבלת האור העצמי כו' וכמ\"ש במ\"א בענין ותחת רגליו כמעשה לבנת הספיר שהוא בחי' שם ב\"ן לאחר הבירור שנק' ספיר שנתברר מלמטה למעלה ובאמת בחי' הבירורים דאו\"ח יהי' גבוהים מבירורי'"],[2400650584,"דאו\"י כידוע בענין א\"ח עט\"ב כו' וכמ\"ש מים חיים כו' חצים אל הים הקדמוני כו' וז\"ש ואהללה שמך לעולם ועד ולכאורה זהו פלא גדול איך יאמר דוד המלך ע\"ע שיהי' חי וקיים לנצח ויהלל שמו לעולם ועד שהרי לא הי' חייו רק ע' שנה. אך הענין ידוע דע' שנין דדוד דעכשיו מאדה\"ר ולע\"ל יתעלה בחי' מל' דדוד למעלה מבחי' הכתר דעכשיו ולכך אומר דוד מ\"י חי וקיים וכמ\"ש ה' ימלוך לעולם ועד מלכותו מלכות עלם וכמ\"ש במ\"א באריכות והוא מצד בחי' הבירורים דשם ב\"ן דווקא שנק' אבן ספיר כו' דסוף מעשה עלה במחשבה תחילה כו' וזהו שא' ואהללה שמך לשון עתיד דהיינו בימות המשיח דמה שבעוה\"ב יהי' אור העצמי שמלמעלה למטה נצחי חי וקיים לעד הוא מטעם בחי' התשלום של הבירורים מלמטה למעלה דווקא בימות המשיח כו' ואז דווקא ואהללה שמך לעולם ועד בלי הפסק והוא מב' טעמים הא' שלא יהי' גירעון והעדר האור מחושך החיצוני מאחר שנשלם הבירור שלהם. והב' מצד שהחושך עצמו יאיר שזהו אין לזה הפסק וכמ\"ש כיתרון האור מתוך החושך כו' וכן מגלה עמוקות מני חושך דוקא שהרי א' דאפי' אור צח אור מצוחצח [בעצם] אוכם הוא לגבי עה\"ע עצמו ובחי' חושך אוכם זה למעלה גם מבחי' אור העצמי דאור צח משום דבחי' העלם העצמות למעלה הרבה מבחי' אור עצמי' כו'. אמנם מה שהחושך יאיר היפוך טבעו זהו ג\"כ מצד בחי' אור העצמי' דווקא שנא' בו גם חושך לא יחשיך ממך פי' גם חושך סתרו דמגלה עמוקות מני חושך בגלוי אור מתוך החושך כו' וזהו שאמר ואהללה בגילוי ההעלם וד\"ל. והוא מפני שאמר בפסוק שלפני זה ואברכה שמך לעולם ועד דהברכה שהיא [שפע] עצמי' ג\"כ לעולם ועד בבחי' נצחי' דא\"ס עצמו ע\"כ ואהללה שמך ג\"כ לעולם ועד ושניהם קאי בימות המשיח דהברכה והלל יהי' בבחי' העצמות דא\"ס שהוא לעולם ועד דוקא וזהו שלא הזכיר ענין לעולם ועד רק בב' פסוקים הללו שהן באות א' וב' דמזמור זה קאי בכתר וחכמה דמל' כנ\"ל ובבחי' הכתר הברכה קודם להלל ע\"כ א' בפסוק זה ברכה קודם והיא ברכה דבכל יום בפרט בכל ו\"א שני כו' וכמ\"כ ברכה כללי' דאברכה כו' קודם להלל שלעולם ועד אעפ\"י שהוא מדבר בבחי' או\"ח דשם ב\"ן שהוא ענין תהלה לדוד לאחר הבירור שע\"ז א' ארוממך לעתיד כו' מ\"מ אברכה שמך קודם ואהללה מטעם הנ\"ל בענין נתחב\"ס וסוב\"ת שזהו ענין ארוממך ואברכך שמך כו' דלכך תחלה ארוממך ואח\"כ ואברכה כו' ובכל יום אברכך ואח\"כ ואהללה כו':"],[2400650585,"<h3>גדול ה' ומהולל מאד</h3>\n(קסה) <b>גדול</b> ה' ומהולל מאד וכו'. הנה ידוע דשם הוי' בניקוד פת\"ח הוא בחכ' דוקא כי"],[2400650586,"הקמ\"ץ בכתר והפת\"ח בחכ' לפי שהפת\"ח הוא ענין פתיחה וגילוי אור מלמעלה למטה מן ההעלם שבעצמותו לגילוי והמשכה למטה הימנו כמו שנאמר פיה פתחה בחכמה שהחכמה מאין תמצא בבחי' גילוי אור ההעלם העצמות ולזה נק' החכ' ראשית כי הוא בחי' ראשית מן הגילוי מן ההעלם ולכך כל שם הוי' סתם הוא בחכמה וכמ\"ש ה' בחכמה יסד ארץ כו' וכה\"ג וכידוע בענין בראשית נמי מאמר הוא (וגם ח\"ס דא\"א שנק' תעלומות חכ' ע\"ז אמר ג\"כ והחכ' מאין תמצא מעצמות המאציל רק שנק' מקור לאור הגילוי דחכ' שהרי נאמר חכמת אדם תאיר פניו וקאי בח\"ס בזמן מ\"ת ומ\"ש ותורה אור היא שנק' נובלות חכמה של מעלה כידוע). (וכמ\"ש במ\"א בענין כי אתה אבינו דאור אבא נק' אתה וכמ\"ש בזוהר דתלת דוכתי אקרי אתה כו' והוא כמו ענין גילוי אור בריקת השכל הנק' הבנה שהוא כמו בחי' אותיות לגבי עצם כח אור שכל זה וגם מקור זה השכל נובע מעצמות כח המשכיל ההיולי וגם עצם כח המשכיל יש בו קטנות וגדלות בבחי' צמיחה כמו מתינוק לגדול הרי גם הוא מתפשט מן ההעלם לגילוי מעט מעט כו'). והנה ידוע דאור אבא מקור החסד והוא כללות קו הימין חח\"נ שהחסד ענף החכ' כו' וכמו שאנו רואים בטבע כל חכם יותר שחסדו גדול ומתפשט יותר בהתרחבות וכל מי שדעתו קצרה וחכמתו מצומצם דיני' ואכזריות נמשך ממנו כתינוקות ונשים שדעתן קלות כו' וכמ\"ש במ\"א שלזה אנו אומרים אבינו אב הרחמן כו' וגם מטעם אחר מפני שהחכמה שרשה ומקורה הוא בבחי' החסד דוקא והוא הנק' רב חסד דבי' אחיד אבא כו' (כידוע בענין כה\"ג ששרשו ברב חסד דע\"י שמלובש בגלגלתא דא\"א וזה שאמר כשמן הטוב על הראש כו') ולזה חסד גי' ע\"ב שהוא הוי' במילוי היודי\"ן דחכ' כידוע והן ע\"ב גשרים דרב חסד דע\"י כו' והענין הוא לפי שירידת שפע גילוי אור דחכ' באה רק מסיבת החסד העצמי שבטבע הטוב להאיר ולהוריד מגבוה לנמוך וזהו מקור כח הגילוי אור דחכמה מאין הנעלם כו' ולזאת גם בטבע אור החכמה עצמה לירד ולהתפשט בגילוי אור ושפע המשכת חסד למטה וכידוע דהחסד ענף החכ' אלא שנק' חסד זוטא שלמטה מן החכ' כידוע וזהו ענין קו הימין דחח\"ן (והוא שרש כהן הדיוט ואיש כהן כו') וכמ\"ש במ\"א בענין אור מים רקיע שהחכמה מצד גילוי מן ההעלם ונק' מים בבחינת התפשטות חסדים למטה כמים שהולכים ונמשכים כו' והוא כאשר הברקת אור בא לבחי' התפשטות והמשכה שהוא בחי' החסד שיורד מגבוה לנמוך כטבע המים (וז\"ש אך טוב וחסד כו' אור נק' טוב וכד אתפשט לתתא נק' חסד כו' וז\"ש ויקרא אלקים לאור יו\"ם שהוא"],[2400650587,"החסד ענף החכ' כמ\"ש יומם יצוה ה' חסדו וכן חסד אל כל היום פי' חסד אל חסד שנסתעף מן החכמה שנק' אל כידוע בזוהר דאל נהירו דחכמתא וזהו אל הוי' כו') וזהו גדול הוי' כו' כי הנה ידוע דפי' גדול הוא בבחינת החסד דוקא שהוא ההתפשטות לאורך ורוחב שנק' גדולה בכ\"מ שכל בחינת ההתפשטות שפע אור למטה מטה יותר נק' בשם גדולה כמו מדת הגדולה בטבע שמתפשטת למרחוק דוקא וכמו להשפיל רב חסדו לפחותי הערך דוקא זהו עיקר ענין מדת הגדולה (ולכך המקובלים הראשונים כינו לחסד בשם גדולה ומה שקורין המקובלים האחרוני' חג\"ת נק' [אצלם גג\"ת] גדולה וגבורה כו' כמ\"א במ\"א באריכות) ולזה הטעם יובן דבחי' החסד המתפשט מן החכמה נק' גדולה (וכמ\"ש במ\"א בכוונות דהגדול הגבור כו' דה\"א דהגדול הוא מקור דקו הימין חח\"ן כו' והוא בבחינת רב חסד דע\"י כנ\"ל וכאשר נעשה מקור לגילוי חסד דחכ' נקרא הגדול וע\"ז נא' ג\"כ גדול הוי' פי' גדול הוי' דע\"ב דחכ' כמשי\"ת) פי' הוי' בניקוד פת\"ח דחכ' גדול בבחי' התפשטות החסדים דאבא בקו הימין חח\"ן כו' שנקרא גדולה (דכמו שיש בכח החכ' בעצם למעלה מעלה בעילוי אחר עילוי שהוא בחי' גבורה דע\"י שמלובש בח\"ס שנק' דין כך יש בכח החכ' בחי' החסד שנק' תורת חסד דווקא כמ\"ש במ\"א בפי' פיה פתחה בחכמה ותורת חסד כו' והן ב' יודי\"ן דאלף אאלפך חכ' כו' כמ\"ש במ\"א). ומהולל מאוד. פי' מהולל הוא השבח והתהלה הבא בהשגת שכל בצמצום אופן דבר המשובח לא פחות ולא יותר אבל עכ\"ז בחי' גילוי אור זה מהעלם העצמות יוכל לבא בלי שיעור וגבול כלל ולכך נק' מאד בלי גבול כלל כי הגם שבהשגה בא הדבר בהגבלת כלים מכלים שונים כנראה בחוש בהשגה דבינה שנתפס הדבר באותיות גילוי כלי המושג בכל חד לפום שיעור כלי השגתו כמו הנשמות נהנין בהשגתם בכל חד לפי צמצום כלי השגתו בלבד משא\"כ טרם שבא האור לכלל השגה ותפיסא עדיין שאינו מוגבל עדיין בכלים כלל מ\"מ יש בזה דוקא בחי' בלתי מוגבל שבעצם מקור אור החכ' כמו שהוא בבחי' אין הנעלם דכתר כו'. וזהו ומהולל מאד בלי גבול לפי שריבוי הכלים דוקא שם מתפשט כל עצם האור כמו שהוא ממש עד\"מ חכם גדול שניכר ונגלה כל עצם חכמתו בריבוי כמה מיני השפעות שכליי' לכמה מיני מקבלים שונים דווקא שריבוי הכלים ביותר מכילים כל ריבוי עצם האור כו' וכמ\"ש במ\"א אור מים רקיע כו'. וזשארז\"ל אימתי גדול כשהוא בעיר אלקינו שהוא בחי' בינה שנק' רקיע כו' וכידוע דעיקר התגלות בחי' עתיק עצמו בבינה דוקא וז\"ש אהי' אשר אהי' כו' וזהו ומהולל מאוד בבינה דוקא וד\"ל. ולהבין ביאור הדברים הנה מובן עד\"מ הידוע מגדול דיעה ביותר"],[2400650588,"שיוכל להכיל ריבוי עניינים מחולקים ביותר ובזה ניכר כל עצם כח חכמתו [אם רב] אם מעט. וכה\"ג יובן עוד מענין פירוד חלקי האותיות של השכל שמכילים כל עצם כח אור המושכל כמו שהוא דוקא שבהן דוקא נתפס כולו אעפ\"י שאינן רק בחי' לבוש וגילוי העצם כמ\"ש במ\"א וד\"ל. (והדמיון האמיתי הוא המבואר במ\"א בענין ג' קוצין דיו\"ד דקוץ התחתון הוא כח ההסבר שמסביר בטוב טעם לנקודת אור השכל בכמה אופנים שונים עד אין שיעור שזהו ודאי בהכרח מכחו של עצם מקור נקודה זו ההיולי כו' שהוא קוצו של יו\"ד העליון בחי' כתר דחכ' כו') ולכך עיקר התגלות ע\"י בבינה כמו הנשמות נהנין בהשגה דבינה [שבמל'] מזיו השכינה שהוא בחי' ע\"י דבריאה לפי שעונג הבא בכלי אופן השגתו שם דוקא מהולל מאד באין שיעור כמו שהוא בעונג הנעלם שלמעלה מן החכ' והיינו אימתי גדול כשהוא בעיר אלקינו בחי' אותיות שנק' בתים ועיר והיינו באותיות דמחשבה בהשגה דבינה הנתפס שנק' עיר אלקינו שם הוא גדול ומהולל מאד מטעם הנ\"ל. ואעפ\"י שא' תחלה גדול הוי' מצד בחי' החכ' אבל בחי' ההלל ושבח שבא בריבוי כלים בהשג' שרשם בלתי מוגבל ושם הוא מהולל מאוד (ולפמ\"ש במ\"א בענין אל ברוך גדול דיעה יתפרש בבחי' הדעת שמחבר חו\"ב וכמארז\"ל גדולה דיעה שנתנה בין ב' אותיות י\"ה כו' ודעת שמחבר חו\"ב הוא בחי' ד\"ת שמטה השכל כלפי חו\"ג בריבוי אופנים שוני' עד אין שיעור וז\"ש ומהולל מאוד בכמה ריבוי רבבות דיעות כו'). ולגדולתו אין חקר. הנה ידוע דאוא\"ס למעלה מעלה עד אין קץ ולמטה מטה עד אין תכלית והא בהא תלי' דהנה כמו שבעצם הוא בחי' א\"ס כך יהי' בחי' מדותיו הכלולים בעצמו ממש הן בבחי' א\"ס ממש וזהו בדרך כלל ובדרך פרט. ותחלה יש להבין דרך פרטי פרטיות איזה מדה וספיר' כמו מדת החסד שנק' גדולה כנ\"ל. הנה מצד שנמשכת מכחו של עצמות הא\"ס גם בדרך פרטי באור וכח חסד זה שנמשך הוא בא בבחי' א\"ס בפרט (כמו חסדי ה' כי לא תמנו כו' וכה\"ג) [דהיינו] שא\"ס להתפשטות אור חסדו העצמי למטה מטה עד אין שיעור ותכלית כלל והוא ענין גדול ה' ומהולל מאד בריבוי השתלשלות המקבלים בלי גבול כלל כנ\"ל רק שזה בבחי' התפשטות למטה והיינו מפני שאין לחסד זה העצמי שיעור למעלה למעלה והא בהא תלי' ממש דהיינו שעצם כח החסד זה כמו שהוא בעצם בחי' חפץ [חסד] ההיולי אין לו שיעור למעלה בעצם עד\"מ עצם מדת הטוב וחסד באדם דמה שאנו רואי' בהתפשטות טובו בריבוי כלים מכלים ולבושים עד אין שיעור זהו רק לפי ערך עצם כח חסדו וטובו שאינו מוגבל בעצם וזהו הנק' אין לו שיעור למעלה כלומר בעצם דלפ\"ע זה הוא"],[2400650589,"ערך ההתפשטות למטה ממש במשקל מכוון וכמו בכח החכ' שלפ\"ע שעור עצם כח השכל כך ימצא ערך שעור התפשטות השכל בכמה ענינים שונים כו' דערך ריבוי הכלים מכילים כל עצם האור וכח כמו שהוא דוקא לא פחות ולא יותר ואם אין שיעור בעצם כך אין שיעור בהתפשטות ממש במשקל מכוון וכך הוא בכל המדות פרטיות בבחי' העצם והתפשטות שלהן דהא בהא תליא בשיעור א' ממש (ובזה יובן בתוס' ביאור המאמר דאיהו וחיוהי חד ואיהו וגרמוהי חד דהן במשקל א' דכמו דאיהו עצמו הא\"ס והאורות הכלולים בבחי' עצמות שלו חד בבחי' א\"ס שזהו הנק' אין לו שיעור למעלה כנ\"ל בעצם ממש בעצמו' הא\"ס וגרמוהי בחי' הכלי' דאורות שהן בחי' ריבוי התפשטותן למטה כידוע חד) שזהו אין לו שיעור למעלה בכל פרט מן המדות וד\"ל. ומזה יובן גם בדרך כלל בכללות אור הא\"ס עצמו דכמו שאין לו שיעור למעלה בעצם כך אין לו שיעור למטה דמשום זה דווקא כל המדות הכלולי' בו גם הן אין פרט ופרט שבהן שאין בהן מכחו של עצם הא\"ס בב' עניינים הללו דהיינו שאין לו שיעור למעלה ולמטה מטעם הנ\"ל וד\"ל. ובכל זה יובן סדר הפסוק הזה שכולל כל ענין הזה בדרך פרט במדות הגדולה שהוא מדת החסד באמרו גדול ה' ומהולל מאד בבחי' אין שיעור למטה משום דלגדולתו בחי' חסד העצמי אין לו שיעור למעלה בעצם משום שהוא בא מכחו של עצם הא\"ס שאין לו שיעור למעלה ולמטה כנ\"ל. וזהו ולגדולתו העצמי' קודם שמתפשט אין חקר וד\"ל. אך למה דוקא במדת הגדולה שהוא מדת החסד דוקא כנ\"ל שהכוונה בגדולה זו רק על מדת החסד בלבד הענין הוא דמדת החס' גם שהוא מדה פרטי' בלבד אבל יש בה הוראה גמורה על כל בחי' העצמות ממש כמו שהוא למעלה מן המדות וכחות הכלולים בעצם והוא כמו ב' דברים הא' מצד שמדת החסד עיקרו ושרשו בעצם הטוב (בל\"א גוטר) שכל עצמו נכלל בזה שהרי עיקר עצם הטוב הוא כאשר נותן כל עצמו כו' כידוע. והב' מצד שהטוב וחסד תלוי בערך הגדולה בעצם כמו שאנו רואים בחוש שכל איש גדול בעצם הרוממות בריבוי עושר מופלג וכבוד והתנשאות אמיתי כן יגדל אור חסדו בלי שיעור ועצם הטוב כשמתחבר עם עצם הגדולה בבלתי מוגבל הוא החסד שאין לו שיעור באמת (כי יש עצם הטוב שיש לו שעור מצד שיש שעור גם לכל בחי' עצם גדולתו כו') ובכאן מדבר בעצמות אוא\"ס ממש שעצם טובו מיוחד בעצם גדולתו שאין לו שיעור ולכך א' מהולל מאד למטה מפני שלגדולתו העצם אין חקר וזהו מדה הכוללת לכל בחי' עצמותו להיותה מורה על כל עצמותו כמו שהוא ממש ולכך הזכיר דווקא מדת הגדולה שבה לחבר הטוב העצמי' וכמ\"ש בע\"ח דמתחלה הי' חפץ חסד כו' וכידוע וד\"ל:"],[2400650590,"<h3> דור לדור ישבח מעשיך</h3>\n(קסו) <b>דור</b> לדור ישבח מעשיך כו'. הנה כתיב דור הולך ודור בא והארץ לעולם עומדת. פי' הפשוט דהדורות מתחלפים מזמן לזמן ודור הולך בזמן ע' שנה וכה\"ג ודור אחר מחדש בא וגם הוא הולך במשך זמן וכן מתחדש דור אחר דור והארץ לעולם עומדת בלי שינוי כלל כו' וכך מתחלף עד כמה דורות והארץ לעולם עומדת וכמו\"כ דבר צוה לאלף דור כו'. דהנה הכל הי' מן העפר והכל שב אל עפר כו' דכמו הארץ הגשמי לא תשתנה מריבוי התחלפות הדורות כך למעלה בבחי' ארץ העליונה דכתיב והארץ הדום רגלי כו' שהוא בחי' המל' שעז\"א תוצא הארץ כו' דהכל הי' מן העפר העליון שנק' עפר אשר בקרקע המשכן כו' (שהוא בחי' דומם כמו אותיות הדבור שנק' אבנים כידוע שזהו בחי' עשי' שבאצי') והנה כאשר בחי' המל' נעשה מקור לבי\"ע אז נא' דבר צוה לאלף דור פי' שמבחי' דבר א' שצוה בדבור נעשה ונמשך אלף [דור] בזמן מאין ליש (וביאור הדבר ידוע שמ\"ש קורא הדורות מראש היינו מעולם המח' ורצוה\"פ קורא וממשיך אותם שיבא מן ההעלם לגילוי בבחי' הדבור שנק' עלמא דאתגלייא מאין ליש וזהו דבר צוה בדבור שיהי' אלף דור בזמן ומקום מאין ליש כו') ועד\"ז הולך ומשתלשל בג' עולמות בי\"ע שדבר א' שצוה נמשך אלף דור בבת אחת ממל' דאצי' בעולם הבריאה ועד\"ז גם במל' דבריאה ביצי' דבר א' ציוה לאלף דור בבחינת עולם היצי' וכן ממל' דיצירה בעשי' עד שנמשך אלף דור בגשמיות הזמן בדורות בנ\"א שמושפעים משמרי האופנים במזלות כו' כמו המלאך שגוזר ואומר טיפה זו חכם כו' עד חלקי דצ\"ח שמקבלים ממזלות עד שאין לך עשב מלמטה שאין לו מזל כו' וכ\"ז רק מבחי' מל' שבמל' [די\"ס] דעשי' שמשפיע מחיצוני' דחיצוניות הכלים דט\"ס בט' גלגלים כו' כמ\"ש בע\"ח בסופו וד\"ל. והנה הגם שנמשך ממקור הראשון אלף דור בבת אחת בכל עולם לפ\"ע מ\"מ בבוא השפע למטה מתחלקים בזמן להיות באין זה אחר זה דוקא כמו דור הולך ואח\"כ דור אחר חדש בא וא\"א שיבא חדש בלתי אם שילך הדור הראשון כמו בדורות בנ\"א למטה כך בכל עולם ועולם עד דורות שבעולם הבריאה והאצי' כו' וא\"כ הלא מובן מזה עכ\"פ שיש יתרון מעלה בארץ נפלאה מאד על היות שרשה בבחי' שלמעלה מן הזמן של הדורות שבא בהתחלקות הזמן להיות כי כדור הולך ודור אחר בא הרי זה בבחי' התחלקות הזמן והארץ לעולם עומדת היינו שלא יש בה שינוי כלל והתחלפות כל הדורות בזמן כמה אלפים שנה כי שרש הכח שיש בארץ הוא בא ונמשך מלמעלה מן הזמן (וכמ\"ש אנכי עשיתי ארץ ואדם עלי' בראתי וכן רוקע הארץ כו' נותן נשמה לעם עליה ורוח להולכים בה דמשמע שהארץ שהנשמות שבאדם על הארץ נקרא"],[2400650591,"בריאה מתחדשת מאין ליש מזמן לזמן כמ\"ש נותן נשמה לעם כו' וכן אדם עליה בראתי אבל הארץ עומדת מו' ימ\"ב (וכמ\"ש והארץ היתה תוהו כו' ומ\"ש עליה לשון עשי' אנכי עשיתי ארץ וכן ביום עשות ה' אלקים ארץ כו' הכוונה על שרש הסוף בתחלה דוקא והוא כמ\"ש אנכי עשיתי [אנכי] דוקא וכן ביום עשות כו' דארץ קדמה לשמים כידוע משום שנתחב\"ס דוקא כמשי\"ת) והענין הוא כמ\"ש במ\"א שיש שרש בארץ מפני שהיא סוף הכל מבחי' התחלה דוקא והוא מבחי' א\"ס שבכתר כי נעוץ תחב\"ס דוקא כידוע והמופת ע\"ז הוא שאנו רואי' בד' יסודות ארמ\"ע הרי מובדל מעלת יסוד העפר הגם שהוא אחרון יותר מג' יסודות הקודמים אליו אש רוח ומים שהרי ענין התהוות חידוש יש מאין ממש אינו נמצא רק ביסוד העפר שבארץ כמה שתוצא צמחה מאין [ממש] ולא ימצא חידוש זה ביסוד המים והרוח ואש כלל שהרי לא יולדו מים חדשים ממים שבגשמי' ונהרות"],[2400650592,"הנק' מים עליונים וכן ביסוד הרוח ואש לא יולד התחדשות בהן כלל רק כמו שהן בעצם [פשיטותן] ומציאותן ולא יתוסף בהן ועל ידן שום התהוות מציאות חדש רק מה שמתרבים בעצם לבד אבל בעפר הארץ הרי מתחדש חדוש מציאות שלא הי' בעולם כמו כל צמח עשב ותבואות וגם מים חדשים יולדו מבטן הארץ ונק' מים חיים כידוע וגם מציאות האש והרוח הן מתחדשים מאין ליש כעפר הארץ דוקא כידוע במיני מתכות ואבנים הצומחים ומתהווים מחדש בארץ דוקא וכענין עצי אלמוגים ומיני מרגליות הרי גם מיסוד הרוח מתחדש שם מאין [ממש] כו' וכה\"ג בד' חלקי דצח\"מ הרי הכל הי' מן העפר דוקא בבחי' החידוש מאין ליש דוקא כי חלקי הדומם והצומח התהוות המציאות שלהם בתמידות מן הארץ בא וגם החי והמדבר חיים וקיימים מן הארץ כמו ארץ מגדלת חכמים כו' (וכמ\"ש נותן נשמה [עליה] עליה דוקא ורוח להולכים בה כו'):"],[2400650593,"<b>וכמו</b> בוימ\"ב שנא' תוצא הארץ נפש חי' כו' וגם האדם יסודו עפר מן האדמה כידוע וד\"ל. ומכל זה מופת גמור אשר ניתן בארץ כח מכח ומקור הראשון שהוא למעלה מארמ\"ע ודצח\"מ והוא כחו של א\"ס המהווה את הכל כמ\"ש כי עמך מקור חיים כו' ולכך יש כח של א\"ס ממש בגידול וצמיחה שבארץ לגדל עד אין שיעור מלבד ענין חידוש הי\"ש מאי\"ן הנ\"ל והוא מפני שנעוץ תחלתן בסופן דוקא שכל התחלת הכל עילת העילות נעוץ בסוף הכל כו'. וזהו והארץ לעול\"ם עומד\"ת וקאי בבחי' ארץ העליונה שהוא בחי' המל' סופא דכל דרגין לעולם עומדת להחיות עולמות עד אין שיעור מפני שעיקר חידוש זה מאין ליש הוא בבחי' המל' דוקא יותר מבאורות העליונים ממנה (כמובן ממשל הארץ הגשמי הנ\"ל וכך יש בחי' ארמ\"ע באצי' וכן בחי' דצח\"ם שהן לנגד ד' אותיות הוי' שבאצי' כו' ובחי' הדומם שבאצי' שנק' עפר שבקרקע המשכן כו' יש בו יתרון מעלה מבחי' אמ\"ר שבאצי' במה שמתחדש בו השפע מאין ליש וחידוש השפע בלתי נפסק שם כנ\"ל והוא מפני שנעוץ תחלתן בסופן דוקא ויש בסוף מכח התחלה דוקא שהוא בחי' א\"ס שבכתר שהוא האין האמיתי כו' שממנו מקור"]]});
